INSERT INTO questions (question_text, option1, option2, option3, option4, correct_answer, solution_text, concept_id, difficulty_tier, source, status) VALUES

-- ============================================================
-- p_electric_charges_coulomb (7 easy, 7 medium, 7 hard = 21)
-- ============================================================
('The minimum charge that can exist freely in nature is', '$1\;\text{C}$', '$1.6 \times 10^{-19}\;\text{C}$', '$1.6 \times 10^{-18}\;\text{C}$', '$9.1 \times 10^{-31}\;\text{C}$', 'option2', 'The elementary charge is $e = 1.6 \times 10^{-19}\;\text{C}$ (charge of electron/proton). Charge is quantized in multiples of $e$.', 'p_electric_charges_coulomb', 1, 'JEE Mains Prep', 'approved'),
('When a glass rod is rubbed with silk, the rod acquires positive charge because', 'Protons are added to the rod', 'Neutrons are removed', 'Electrons transfer from rod to silk', 'Positive charges are created', 'option3', 'Rubbing transfers electrons from the glass rod to silk. The rod loses electrons and becomes positively charged. Charge is conserved, not created.', 'p_electric_charges_coulomb', 1, 'JEE Mains Prep', 'approved'),
('Coulomb''s law gives the force between two point charges $q_1$ and $q_2$ separated by distance $r$ as', '$kq_1 q_2 r^2$', '$kq_1 q_2/r$', '$kq_1/(q_2 r^2)$', '$kq_1 q_2/r^2$', 'option4', '$F = kq_1 q_2/r^2$ where $k = 1/(4\pi\epsilon_0) = 9 \times 10^9\;\text{N}\cdot\text{m}^2/\text{C}^2$.', 'p_electric_charges_coulomb', 1, 'JEE Mains Prep', 'approved'),
('The total charge on a system of $10^{10}$ protons and $10^{10}$ electrons is', '$1.6 \times 10^{-9}\;\text{C}$', '$3.2 \times 10^{-9}\;\text{C}$', 'Zero', '$1.6 \times 10^{-19}\;\text{C}$', 'option3', 'Equal numbers of protons and electrons: net charge $= 10^{10}(e) + 10^{10}(-e) = 0$.', 'p_electric_charges_coulomb', 1, 'JEE Mains Prep', 'approved'),
('The value of $1/(4\pi\epsilon_0)$ in SI units is approximately', '$8.85 \times 10^{-12}$', '$6.67 \times 10^{-11}$', '$9 \times 10^9$', '$1.6 \times 10^{-19}$', 'option3', '$k = 1/(4\pi\epsilon_0) \approx 9 \times 10^9\;\text{N}\cdot\text{m}^2/\text{C}^2$.', 'p_electric_charges_coulomb', 1, 'JEE Mains Prep', 'approved'),
('If the distance between two charges is halved, the Coulomb force becomes', 'Half', 'Double', 'Four times', 'One-fourth', 'option3', '$F \propto 1/r^2$. If $r \to r/2$: $F \to F \times 4$. Force becomes four times.', 'p_electric_charges_coulomb', 1, 'JEE Mains Prep', 'approved'),
('Charge is conserved means', 'Charge can be created but not destroyed', 'Total charge of an isolated system remains constant', 'Charge always stays on one body', 'Charge cannot be transferred', 'option2', 'Conservation of charge: the net charge of an isolated system cannot change. Charge can be transferred but not created or destroyed.', 'p_electric_charges_coulomb', 1, 'JEE Mains Prep', 'approved'),
('Two identical conducting spheres carrying charges $+6\;\mu\text{C}$ and $-2\;\mu\text{C}$ are brought into contact and separated. The charge on each sphere is', '$+4\;\mu\text{C}$', '$-4\;\mu\text{C}$', '$+2\;\mu\text{C}$', '$+8\;\mu\text{C}$', 'option3', 'Total charge $= 6 + (-2) = 4\;\mu\text{C}$. Identical spheres share equally: $4/2 = 2\;\mu\text{C}$ each.', 'p_electric_charges_coulomb', 2, 'JEE Mains Prep', 'approved'),
('Three charges $+q$, $+q$, and $-q$ are placed at the vertices of an equilateral triangle of side $a$. The net force on $-q$ is', '$kq^2/a^2$ along the bisector towards the $+q$ charges', '$kq^2\sqrt{3}/a^2$ along the bisector', '$2kq^2/a^2$ along one side', 'Zero', 'option2', 'Each $+q$ attracts $-q$ with force $F = kq^2/a^2$. The two forces are at $60°$. Resultant $= \sqrt{F^2 + F^2 + 2F^2\cos 60°} = F\sqrt{3} = kq^2\sqrt{3}/a^2$, directed along the bisector.', 'p_electric_charges_coulomb', 2, 'JEE Mains Prep', 'approved'),
('The force between two charges in a medium of dielectric constant $K$ compared to vacuum is', '$K$ times larger', 'Same', '$1/K$ times', '$K^2$ times larger', 'option3', '$F_{medium} = F_{vacuum}/K$. The dielectric reduces the force by factor $K$.', 'p_electric_charges_coulomb', 2, 'JEE Mains Prep', 'approved'),
('Two charges $+4\;\mu\text{C}$ and $+16\;\mu\text{C}$ are $30\;\text{cm}$ apart. The point where the net electric field is zero lies', '$20\;\text{cm}$ from $+4\;\mu\text{C}$', '$10\;\text{cm}$ from $+4\;\mu\text{C}$', '$15\;\text{cm}$ from each', '$10\;\text{cm}$ from $+16\;\mu\text{C}$', 'option2', 'Null point between like charges, closer to smaller charge. $kq_1/x^2 = kq_2/(0.3-x)^2$. $4/x^2 = 16/(0.3-x)^2$. $(0.3-x)/x = 2$. $0.3 = 3x$. $x = 0.1\;\text{m} = 10\;\text{cm}$ from $+4\;\mu\text{C}$.', 'p_electric_charges_coulomb', 2, 'JEE Mains Prep', 'approved'),
('A charge $Q$ is distributed uniformly on a ring of radius $R$. The linear charge density is', '$Q/R$', '$Q/(2\pi R)$', '$Q/(\pi R^2)$', '$Q/(4\pi R^2)$', 'option2', 'Linear charge density $\lambda = Q/\text{circumference} = Q/(2\pi R)$.', 'p_electric_charges_coulomb', 2, 'JEE Mains Prep', 'approved'),
('Two point charges $+2\;\mu\text{C}$ and $-8\;\mu\text{C}$ are $20\;\text{cm}$ apart. The point on the line joining them where the field is zero is', '$20\;\text{cm}$ from $+2\;\mu\text{C}$ on the side away from $-8\;\mu\text{C}$', '$10\;\text{cm}$ from $+2\;\mu\text{C}$ between them', '$40\;\text{cm}$ from $-8\;\mu\text{C}$', '$20\;\text{cm}$ from $-8\;\mu\text{C}$ on the far side', 'option1', 'For unlike charges, null point is outside, beyond the smaller charge. Let distance from $+2\;\mu\text{C}$ be $x$: $k(2)/x^2 = k(8)/(x+0.2)^2$. $(x+0.2)/x = 2$. $x = 0.2\;\text{m} = 20\;\text{cm}$ from $+2\;\mu\text{C}$ on the far side.', 'p_electric_charges_coulomb', 2, 'JEE Mains Prep', 'approved'),
('The superposition principle for electric forces states that the force on a charge due to multiple charges is', 'The scalar sum', 'The vector sum of individual forces', 'The product of individual forces', 'The average of individual forces', 'option2', 'Superposition: the net force on a charge is the vector sum of forces due to each other charge independently.', 'p_electric_charges_coulomb', 2, 'JEE Mains Prep', 'approved'),
('Five equal charges $+q$ are placed at the vertices of a regular pentagon of side $a$. The net force on any one charge is directed', 'Towards the centre', 'Away from the centre', 'Along one side', 'Perpendicular to one side', 'option1', 'By symmetry, the resultant of forces from the other four charges on any vertex charge points radially inward towards the centre of the pentagon.', 'p_electric_charges_coulomb', 3, 'JEE Mains Prep', 'approved'),
('Two identical small spheres of mass $m$ each carry charge $q$ and are suspended from a common point by threads of length $L$. For small angles, the separation between them is proportional to', '$(q^2 L/m)^{1/3}$', '$(q^2/mL)^{1/3}$', '$(q^2 m/L)^{1/3}$', '$(qL/m)^{1/2}$', 'option1', 'At equilibrium: $T\sin\theta = kq^2/d^2$ and $T\cos\theta = mg$. For small $\theta$: $\tan\theta \approx d/(2L)$. So $mgd/(2L) = kq^2/d^2$. $d^3 = 2kq^2L/(mg)$. $d \propto (q^2L/m)^{1/3}$.', 'p_electric_charges_coulomb', 3, 'JEE Mains Prep', 'approved'),
('A charge $Q$ is placed at the centre of a line joining two equal charges $q$. For the system to be in equilibrium, $Q$ must equal', '$-q/4$', '$-q/2$', '$q/4$', '$-q$', 'option1', 'Force on $q$ at distance $d$ from centre: $kqQ/d^2 + kq^2/(2d)^2 = 0$. $Q/d^2 = -q/(4d^2)$. $Q = -q/4$.', 'p_electric_charges_coulomb', 3, 'JEE Mains Prep', 'approved'),
('Eight identical charges $q$ are placed at the corners of a cube of side $a$. The net force on each charge is directed towards', 'The centre of the nearest face', 'The opposite corner', 'The centre of the cube', 'Along the nearest edge', 'option3', 'By symmetry, the resultant force on any corner charge from the other seven points towards the body centre of the cube.', 'p_electric_charges_coulomb', 3, 'JEE Mains Prep', 'approved'),
('Two charges $+4q$ and $+q$ are separated by distance $3L$. A third charge $Q$ is placed between them so that all three are in equilibrium. The value of $Q$ and its position from $+4q$ are', '$Q = -q/4$, at $L$ from $+4q$', '$Q = -4q/9$, at $2L$ from $+4q$', '$Q = -4q/9$, at $L$ from $+4q$', '$Q = -q/9$, at $2L$ from $+4q$', 'option2', 'Let $Q$ be at distance $x$ from $+4q$. For $Q$ equilibrium: $k(4q)Q/x^2 + kqQ/(3L-x)^2 = 0$. $4/(x^2) = 1/(3L-x)^2$. $2(3L-x) = x$. $6L = 3x$. $x = 2L$. For $+q$ equilibrium: $kq(4q)/(3L)^2 = kqQ/(L)^2$ (magnitudes). $4q/9L^2 = |Q|/L^2$. $|Q| = 4q/9$. $Q = -4q/9$.', 'p_electric_charges_coulomb', 3, 'JEE Mains Prep', 'approved'),
('A thin semicircular ring of radius $R$ carries uniform linear charge density $\lambda$. The electric field at the centre is', '$2\lambda/(\pi\epsilon_0 R)$', '$\lambda/(4\pi\epsilon_0 R)$', '$\lambda/(2\epsilon_0 R)$', '$\lambda/(2\pi\epsilon_0 R)$', 'option4', 'By symmetry, only the component along the axis of symmetry survives. $E = \int_0^\pi \frac{\lambda R\,d\theta}{4\pi\epsilon_0 R^2}\sin\theta = \frac{\lambda}{4\pi\epsilon_0 R}[-\cos\theta]_0^\pi = \frac{\lambda}{4\pi\epsilon_0 R}(2) = \frac{\lambda}{2\pi\epsilon_0 R}$.', 'p_electric_charges_coulomb', 3, 'JEE Mains Prep', 'approved'),
('Two identical small conducting spheres carry charges $Q$ and $3Q$. They are brought into contact and then separated to their original distance. The ratio of the new force to the original force between them is', '$16/9$', '$3/4$', '$1$', '$4/3$', 'option4', 'After contact, each has $2Q$. Original force $F_1 = kQ(3Q)/r^2 = 3kQ^2/r^2$. New force $F_2 = k(2Q)(2Q)/r^2 = 4kQ^2/r^2$. Ratio $= 4/3$.', 'p_electric_charges_coulomb', 3, 'JEE Mains Prep', 'approved'),

-- ============================================================
-- p_electric_field_dipole (7 easy, 7 medium, 7 hard = 21)
-- ============================================================
('The electric field due to a point charge $q$ at distance $r$ is', '$q/(4\pi\epsilon_0 r)$', '$q/(4\pi\epsilon_0 r^2)$', '$q\epsilon_0/(4\pi r^2)$', '$4\pi\epsilon_0 q/r^2$', 'option2', '$E = q/(4\pi\epsilon_0 r^2) = kq/r^2$, directed radially outward for positive charge.', 'p_electric_field_dipole', 1, 'JEE Mains Prep', 'approved'),
('Electric field lines', 'Can cross each other', 'Form closed loops', 'Start from negative charges', 'Start from positive and end on negative charges', 'option4', 'Electric field lines originate on positive charges and terminate on negative charges. They never cross.', 'p_electric_field_dipole', 1, 'JEE Mains Prep', 'approved'),
('An electric dipole consists of', 'Two equal and opposite charges separated by a small distance', 'Two equal positive charges', 'A single charge', 'Two unequal charges', 'option1', 'An electric dipole is a pair of equal and opposite charges $+q$ and $-q$ separated by distance $2a$.', 'p_electric_field_dipole', 1, 'JEE Mains Prep', 'approved'),
('The dipole moment $\vec{p}$ of a dipole with charges $\pm q$ separated by $2a$ is', '$q \times a$', '$2qa$, directed from $+q$ to $-q$', '$q \times 2a$, directed from $-q$ to $+q$', '$q/(2a)$', 'option3', 'Dipole moment $p = q \times 2a$, directed from the negative charge to the positive charge.', 'p_electric_field_dipole', 1, 'JEE Mains Prep', 'approved'),
('The SI unit of electric dipole moment is', '$\text{C/m}$', '$\text{N}\cdot\text{m}$', '$\text{C}\cdot\text{m}$', '$\text{V}\cdot\text{m}$', 'option3', 'Dipole moment $= q \times d$. Unit: coulomb-metre ($\text{C}\cdot\text{m}$).', 'p_electric_field_dipole', 1, 'JEE Mains Prep', 'approved'),
('The torque on a dipole of moment $p$ in a uniform field $E$ at angle $\theta$ is', '$pE$', '$pE\sin\theta$', '$pE\cos\theta$', '$pE\tan\theta$', 'option2', '$\tau = pE\sin\theta = |\vec{p} \times \vec{E}|$. Maximum when $\theta = 90°$.', 'p_electric_field_dipole', 1, 'JEE Mains Prep', 'approved'),
('At a point on the axial line of a dipole, the electric field direction is', 'At $45°$ to the dipole moment', 'Perpendicular to the dipole moment', 'Parallel to the dipole moment', 'Opposite to the dipole moment', 'option3', 'On the axial line (far from dipole), the field is parallel to $\vec{p}$ (same direction as dipole moment).', 'p_electric_field_dipole', 1, 'JEE Mains Prep', 'approved'),
('The electric field on the axial line of a short dipole at distance $r$ ($r \gg a$) is', '$p/(4\pi\epsilon_0 r^2)$', '$p/(2\pi\epsilon_0 r^3)$', '$2p/(4\pi\epsilon_0 r^3)$', '$p/(4\pi\epsilon_0 r^3)$', 'option3', 'Axial field: $E_{axial} = 2kp/r^3 = 2p/(4\pi\epsilon_0 r^3)$.', 'p_electric_field_dipole', 2, 'JEE Mains Prep', 'approved'),
('The electric field on the equatorial line of a short dipole at distance $r$ is', '$2p/(4\pi\epsilon_0 r^3)$', '$p/(4\pi\epsilon_0 r^3)$', '$p/(2\pi\epsilon_0 r^3)$', '$3p/(4\pi\epsilon_0 r^3)$', 'option2', 'Equatorial field: $E_{eq} = kp/r^3 = p/(4\pi\epsilon_0 r^3)$, directed antiparallel to $\vec{p}$.', 'p_electric_field_dipole', 2, 'JEE Mains Prep', 'approved'),
('The ratio of electric field on the axial line to the equatorial line at the same distance from a short dipole is', '$1:1$', '$2:1$', '$1:2$', '$4:1$', 'option2', '$E_{axial}/E_{eq} = (2kp/r^3)/(kp/r^3) = 2$. Ratio is $2:1$.', 'p_electric_field_dipole', 2, 'JEE Mains Prep', 'approved'),
('A dipole is placed in a non-uniform electric field. It experiences', 'Both torque and net force', 'Only torque', 'Only net force', 'Neither torque nor force', 'option1', 'In a non-uniform field, the forces on $+q$ and $-q$ differ in both direction and magnitude, producing both a net force and a torque.', 'p_electric_field_dipole', 2, 'JEE Mains Prep', 'approved'),
('The work done in rotating a dipole from angle $\theta_1$ to $\theta_2$ in a uniform field $E$ is', '$pE(\sin\theta_2 - \sin\theta_1)$', '$pE(\cos\theta_2 - \cos\theta_1)$', '$pE(\cos\theta_1 - \cos\theta_2)$', '$pE(\theta_2 - \theta_1)$', 'option3', '$W = \int_{\theta_1}^{\theta_2} pE\sin\theta\,d\theta = pE[-\cos\theta]_{\theta_1}^{\theta_2} = pE(\cos\theta_1 - \cos\theta_2)$.', 'p_electric_field_dipole', 2, 'JEE Mains Prep', 'approved'),
('The potential energy of a dipole in a uniform field $E$ at angle $\theta$ is', '$pE\cos\theta$', '$-pE\cos\theta$', '$-pE\sin\theta$', '$pE\sin\theta$', 'option2', '$U = -\vec{p}\cdot\vec{E} = -pE\cos\theta$. Minimum (stable) when $\theta = 0$.', 'p_electric_field_dipole', 2, 'JEE Mains Prep', 'approved'),
('The electric field at a general point $(r, \theta)$ from a short dipole has magnitude', '$(2kp/r^3)\cos\theta$', '$(kp/r^3)\sqrt{1 + \cos^2\theta}$', '$(kp/r^3)\sqrt{1 + 3\cos^2\theta}$', '$(kp/r^2)\sqrt{1 + 3\cos^2\theta}$', 'option3', 'General field: $E_r = 2kp\cos\theta/r^3$, $E_\theta = kp\sin\theta/r^3$. $E = (kp/r^3)\sqrt{4\cos^2\theta + \sin^2\theta} = (kp/r^3)\sqrt{1 + 3\cos^2\theta}$.', 'p_electric_field_dipole', 2, 'JEE Mains Prep', 'approved'),
('A dipole of moment $p$ is placed in a uniform field $E$. The time period of small oscillations about the equilibrium position is', '$2\pi\sqrt{I/E}$', '$2\pi\sqrt{pE/I}$', '$2\pi\sqrt{I/(pE)}$', '$2\pi\sqrt{p/E}$', 'option3', 'Restoring torque $\tau = -pE\sin\theta \approx -pE\theta$ for small $\theta$. $I\ddot{\theta} = -pE\theta$. SHM with $\omega^2 = pE/I$. $T = 2\pi\sqrt{I/(pE)}$.', 'p_electric_field_dipole', 3, 'JEE Mains Prep', 'approved'),
('Two short dipoles of moments $p_1$ and $p_2$ are placed at distance $r$ apart with their axes perpendicular to each other and to the line joining them. The interaction energy is', '$kp_1 p_2/r^3$', '$-kp_1 p_2/r^3$', 'Zero', '$-2kp_1 p_2/r^3$', 'option3', 'When one dipole is on the equatorial line of the other and perpendicular to it, the field of the first at the second is antiparallel to the equatorial direction. Since $\vec{p}_2$ is perpendicular to this field, $U = -\vec{p}_2 \cdot \vec{E}_1 = 0$.', 'p_electric_field_dipole', 3, 'JEE Mains Prep', 'approved'),
('The electric field at distance $r$ on the axial line of a dipole (charges $\pm q$, separation $2a$, $r \gg a$) varies as', '$1/r^2$', '$1/r$', '$1/r^3$', '$1/r^4$', 'option3', 'For a dipole at large $r$: $E_{axial} = 2kp/r^3 \propto 1/r^3$. Dipole fields fall off as the cube of distance.', 'p_electric_field_dipole', 3, 'JEE Mains Prep', 'approved'),
('A dipole of moment $6 \times 10^{-6}\;\text{C}\cdot\text{m}$ is in a uniform field of $10^5\;\text{N/C}$. Maximum torque on the dipole is', '$6\;\text{N}\cdot\text{m}$', '$0.6\;\text{N}\cdot\text{m}$', '$0.06\;\text{N}\cdot\text{m}$', '$60\;\text{N}\cdot\text{m}$', 'option2', '$\tau_{max} = pE = 6 \times 10^{-6} \times 10^5 = 0.6\;\text{N}\cdot\text{m}$ (when $\theta = 90°$).', 'p_electric_field_dipole', 3, 'JEE Mains Prep', 'approved'),
('The work done in rotating a dipole from stable equilibrium ($\theta = 0$) to unstable equilibrium ($\theta = \pi$) is', '$pE$', '$2pE$', '$pE/2$', 'Zero', 'option2', '$W = pE(\cos 0 - \cos\pi) = pE(1-(-1)) = 2pE$.', 'p_electric_field_dipole', 3, 'JEE Mains Prep', 'approved'),
('An electric dipole is placed at the centre of a sphere. The total electric flux through the sphere is', 'Zero', '$p/\epsilon_0$', '$q/\epsilon_0$', '$2q/\epsilon_0$', 'option1', 'A dipole has net charge zero ($+q + (-q) = 0$). By Gauss''s law, total flux $= q_{enc}/\epsilon_0 = 0$.', 'p_electric_field_dipole', 3, 'JEE Mains Prep', 'approved'),
('At a point where the electric field of a dipole makes angle $\alpha$ with the position vector $r$, $\tan\alpha$ equals', '$\tan\theta$', '$2\tan\theta$', '$(1/2)\tan\theta$', '$(1/2)\cot\theta$', 'option3', '$\tan\alpha = E_\theta/E_r = (kp\sin\theta/r^3)/(2kp\cos\theta/r^3) = \tan\theta/2$.', 'p_electric_field_dipole', 3, 'JEE Mains Prep', 'approved'),

-- ============================================================
-- p_gauss_law (7 easy, 7 medium, 7 hard = 21)
-- ============================================================
('Electric flux through a surface is defined as', '$E \times A$', '$\oint E\,dA$', '$\oint \vec{E}\cdot d\vec{A}$', '$E/A$', 'option3', 'Electric flux $\Phi = \oint \vec{E}\cdot d\vec{A}$ (surface integral of the dot product of $\vec{E}$ and area element).', 'p_gauss_law', 1, 'JEE Mains Prep', 'approved'),
('Gauss''s law states that the total electric flux through a closed surface equals', '$q_{enc}/\epsilon_0$', '$q_{enc}\epsilon_0$', '$q_{enc}/(4\pi\epsilon_0)$', '$\epsilon_0/q_{enc}$', 'option1', 'Gauss''s law: $\oint \vec{E}\cdot d\vec{A} = q_{enclosed}/\epsilon_0$.', 'p_gauss_law', 1, 'JEE Mains Prep', 'approved'),
('The electric flux through a closed surface enclosing no charge is', 'Infinite', '$\epsilon_0$', 'Zero', 'Depends on the surface shape', 'option3', 'If $q_{enc} = 0$, then $\Phi = 0$ regardless of external charges or surface shape.', 'p_gauss_law', 1, 'JEE Mains Prep', 'approved'),
('The SI unit of electric flux is', '$\text{V/m}$', '$\text{C/m}^2$', '$\text{N/C}$', '$\text{V}\cdot\text{m}$ (or $\text{N}\cdot\text{m}^2/\text{C}$)', 'option4', 'Flux $= E \times A$. Unit: $(\text{N/C})(\text{m}^2) = \text{N}\cdot\text{m}^2/\text{C} = \text{V}\cdot\text{m}$.', 'p_gauss_law', 1, 'JEE Mains Prep', 'approved'),
('The electric field inside a uniformly charged spherical shell is', 'Uniform and non-zero', '$kQ/r^2$', '$kQ/R^2$', 'Zero', 'option4', 'By Gauss''s law with a spherical Gaussian surface inside the shell: $q_{enc} = 0$, so $E = 0$.', 'p_gauss_law', 1, 'JEE Mains Prep', 'approved'),
('A charge $q$ is placed at the centre of a cube. The flux through one face is', '$q/\epsilon_0$', '$q/(6\epsilon_0)$', '$q/(4\epsilon_0)$', '$6q/\epsilon_0$', 'option2', 'Total flux $= q/\epsilon_0$. By symmetry, each of the 6 faces gets $q/(6\epsilon_0)$.', 'p_gauss_law', 1, 'JEE Mains Prep', 'approved'),
('The electric field due to an infinite plane sheet of surface charge density $\sigma$ is', '$\sigma/\epsilon_0$', '$\sigma/(2\epsilon_0)$', '$2\sigma/\epsilon_0$', '$\sigma/(4\pi\epsilon_0)$', 'option2', 'Using Gauss''s law with a pillbox: $2EA = \sigma A/\epsilon_0$. $E = \sigma/(2\epsilon_0)$, independent of distance.', 'p_gauss_law', 1, 'JEE Mains Prep', 'approved'),
('The electric field outside a uniformly charged sphere of total charge $Q$ at distance $r$ from centre ($r > R$) is', 'Zero', '$kQ/R^2$', 'Same as a point charge $Q$ at the centre', '$kQR/r^3$', 'option3', 'Outside a uniformly charged sphere: $E = kQ/r^2$, identical to a point charge at the centre.', 'p_gauss_law', 2, 'JEE Mains Prep', 'approved'),
('The electric field due to an infinitely long straight wire with linear charge density $\lambda$ at distance $r$ is', '$\lambda/(4\pi\epsilon_0 r)$', '$\lambda/(2\pi\epsilon_0 r)$', '$\lambda/(2\pi\epsilon_0 r^2)$', '$2\lambda/(\pi\epsilon_0 r)$', 'option2', 'Cylindrical Gaussian surface: $E(2\pi rL) = \lambda L/\epsilon_0$. $E = \lambda/(2\pi\epsilon_0 r)$.', 'p_gauss_law', 2, 'JEE Mains Prep', 'approved'),
('A charge of $+10\;\mu\text{C}$ is placed inside a closed surface. The total outward flux is', '$1.13 \times 10^6\;\text{N}\cdot\text{m}^2/\text{C}$', '$10^{-5}\;\text{N}\cdot\text{m}^2/\text{C}$', '$8.85 \times 10^{-12}\;\text{N}\cdot\text{m}^2/\text{C}$', '$10^{-6}\;\text{N}\cdot\text{m}^2/\text{C}$', 'option1', '$\Phi = q/\epsilon_0 = 10 \times 10^{-6}/(8.85 \times 10^{-12}) = 1.13 \times 10^6\;\text{N}\cdot\text{m}^2/\text{C}$.', 'p_gauss_law', 2, 'JEE Mains Prep', 'approved'),
('Inside a uniformly charged solid sphere of total charge $Q$ and radius $R$, the field at distance $r$ from centre ($r < R$) is', '$kQr/R^3$', '$kQ/r^2$', '$kQ/R^2$', 'Zero', 'option1', 'Gaussian sphere of radius $r$: $q_{enc} = Q(r/R)^3$. $E(4\pi r^2) = Q(r/R)^3/\epsilon_0$. $E = kQr/R^3$.', 'p_gauss_law', 2, 'JEE Mains Prep', 'approved'),
('Two infinite parallel plane sheets have charge densities $+\sigma$ and $-\sigma$. The field between them is', '$\sigma/\epsilon_0$', '$\sigma/(2\epsilon_0)$', 'Zero', '$2\sigma/\epsilon_0$', 'option1', 'Between the sheets, fields add: $E = \sigma/(2\epsilon_0) + \sigma/(2\epsilon_0) = \sigma/\epsilon_0$. Outside, they cancel.', 'p_gauss_law', 2, 'JEE Mains Prep', 'approved'),
('A charge $q$ is placed at one corner of a cube. The flux through the cube is', '$q/\epsilon_0$', '$q/(8\epsilon_0)$', '$q/(6\epsilon_0)$', '$q/(2\epsilon_0)$', 'option2', 'The charge is shared among 8 cubes meeting at that corner. Flux through this cube $= q/(8\epsilon_0)$.', 'p_gauss_law', 2, 'JEE Mains Prep', 'approved'),
('The electric field outside a long charged cylindrical shell of radius $R$ and surface charge density $\sigma$ at distance $r > R$ is', '$\sigma/(2\epsilon_0)$', '$\sigma R^2/(\epsilon_0 r^2)$', '$\sigma R/(\epsilon_0 r)$', '$\sigma R/(2\epsilon_0 r)$', 'option3', 'Total charge per length $= \sigma(2\pi R)$. By Gauss''s law: $E(2\pi r) = \sigma(2\pi R)/\epsilon_0$. $E = \sigma R/(\epsilon_0 r)$.', 'p_gauss_law', 2, 'JEE Mains Prep', 'approved'),
('A sphere of radius $R$ has a volume charge density $\rho = \rho_0(1 - r/R)$. The electric field at $r = R/2$ is', '$\rho_0 R/(8\epsilon_0)$', '$5\rho_0 R/(48\epsilon_0)$', '$\rho_0 R/(6\epsilon_0)$', '$\rho_0 R/(12\epsilon_0)$', 'option2', '$q_{enc} = \int_0^{R/2} \rho_0(1-r/R) 4\pi r^2\,dr = 4\pi\rho_0[\frac{r^3}{3} - \frac{r^4}{4R}]_0^{R/2} = 4\pi\rho_0[\frac{R^3}{24} - \frac{R^3}{64}] = 4\pi\rho_0 R^3 \frac{(8-3)}{192} = \frac{5\pi\rho_0 R^3}{48}$. $E = q_{enc}/(4\pi\epsilon_0(R/2)^2) = \frac{5\pi\rho_0 R^3}{48} \cdot \frac{1}{\pi\epsilon_0 R^2} = \frac{5\rho_0 R}{48\epsilon_0}$.', 'p_gauss_law', 3, 'JEE Mains Prep', 'approved'),
('A conducting sphere of radius $R$ carries charge $Q$. A point charge $q$ is placed at distance $2R$ from the centre. The force on $q$ is', 'Zero', '$kQq/(4R^2)$ exactly', 'Not simply $kQq/(2R)^2$ due to induced charges', '$kQq/R^2$', 'option3', 'The external charge $q$ induces a non-uniform surface charge on the conductor, so the force is not simply $kQq/4R^2$. The method of images gives a more complex expression.', 'p_gauss_law', 3, 'JEE Mains Prep', 'approved'),
('A charge $q$ is placed at the centre of two concentric spherical shells of radii $R$ and $2R$ carrying charges $-q$ and $+q$ respectively. The electric field at $r = 3R$ is', '$kq/(3R^2)$', 'Zero', '$kq/(9R^2)$', '$2kq/(9R^2)$', 'option3', 'Total enclosed charge at $r = 3R$: $q + (-q) + q = q$. $E = kq/(3R)^2 = kq/(9R^2)$.', 'p_gauss_law', 3, 'JEE Mains Prep', 'approved'),
('A non-conducting sphere of radius $R$ has uniform volume charge density $\rho$. The ratio of electric field at $r = R/2$ to $r = 2R$ is', '$4:1$', '$1:1$', '$2:1$', '$1:2$', 'option3', 'At $r = R/2$ (inside): $E_1 = \rho(R/2)/(3\epsilon_0) = \rho R/(6\epsilon_0)$. At $r = 2R$ (outside): $E_2 = \rho R^3/(3\epsilon_0(2R)^2) = \rho R/(12\epsilon_0)$. Ratio $= (R/6)/(R/12) = 2$.', 'p_gauss_law', 3, 'JEE Mains Prep', 'approved'),
('A hollow conducting sphere has a charge $+Q$ on its inner surface and $-Q$ on its outer surface. A charge $+q$ is placed inside the cavity. The charge on the inner surface becomes', '$-(Q+q)$', '$-q$', '$Q - q$', '$-(Q-q)$', 'option2', 'The charge $+q$ inside induces $-q$ on the inner surface (Gauss''s law: field inside conductor is zero). The original $+Q$ on the inner surface redistributes. Net inner surface charge $= -q$. Outer surface gets $Q + q$.', 'p_gauss_law', 3, 'JEE Mains Prep', 'approved'),
('The electric field at the surface of a charged conductor is', '$\sigma/\epsilon_0$, perpendicular to the surface', '$\sigma/(2\epsilon_0)$, perpendicular', '$\sigma/\epsilon_0$, tangential', 'Zero', 'option1', 'Just outside a conductor: $E = \sigma/\epsilon_0$ (using Gauss''s law with a small pillbox). The field is always perpendicular to the surface.', 'p_gauss_law', 3, 'JEE Mains Prep', 'approved'),
('A long coaxial cable has inner conductor (radius $a$, charge $+\lambda$ per unit length) and outer conductor (radius $b$, charge $-\lambda$ per unit length). The field at $r$ ($a < r < b$) is', '$\lambda/(2\pi\epsilon_0 r)$', '$\lambda/(\pi\epsilon_0 r)$', 'Zero', '$\lambda/(4\pi\epsilon_0 r)$', 'option1', 'Gaussian cylinder of radius $r$: $E(2\pi rL) = \lambda L/\epsilon_0$. $E = \lambda/(2\pi\epsilon_0 r)$.', 'p_gauss_law', 3, 'JEE Mains Prep', 'approved'),

-- ============================================================
-- p_electric_potential (7 easy, 7 medium, 7 hard = 21)
-- ============================================================
('The electric potential at a point is defined as', 'Charge per unit area', 'Force per unit charge', 'Energy per unit volume', 'Work done per unit charge in bringing a test charge from infinity to that point', 'option4', 'Electric potential $V = W/q_0$ where $W$ is the work done by an external agent in bringing a unit positive test charge from infinity to the point.', 'p_electric_potential', 1, 'JEE Mains Prep', 'approved'),
('The SI unit of electric potential is', 'Coulomb per metre (C/m)', 'Newton per Coulomb (N/C)', 'Joule (J)', 'Volt (V)', 'option4', 'Potential is measured in volts: $1\;\text{V} = 1\;\text{J/C}$.', 'p_electric_potential', 1, 'JEE Mains Prep', 'approved'),
('The electric potential due to a point charge $Q$ at distance $r$ is', '$kQ^2/r$', '$kQ/r^2$', '$kQ/r$', '$kQr$', 'option3', '$V = kQ/r = Q/(4\pi\epsilon_0 r)$. Potential falls as $1/r$ for a point charge.', 'p_electric_potential', 1, 'JEE Mains Prep', 'approved'),
('On an equipotential surface, the work done in moving a charge is', 'Depends on the path', '$qV$', '$qEd$', 'Zero', 'option4', 'On an equipotential surface, $\Delta V = 0$, so $W = q\Delta V = 0$.', 'p_electric_potential', 1, 'JEE Mains Prep', 'approved'),
('The relationship between electric field and potential is', '$\vec{E} = -\nabla V$', '$\vec{E} = \nabla V$', '$V = -\vec{E}$', '$\vec{E} = V/r$', 'option1', 'The electric field is the negative gradient of potential: $\vec{E} = -dV/dr\;\hat{r}$ (in 1D: $E = -dV/dx$).', 'p_electric_potential', 1, 'JEE Mains Prep', 'approved'),
('The potential at a point on the equatorial line of a dipole is', '$-kp/r^2$', '$kp/r^2$', 'Zero', '$2kp/r^2$', 'option3', 'On the equatorial plane, the potentials due to $+q$ and $-q$ are equal and opposite, so $V = 0$.', 'p_electric_potential', 1, 'JEE Mains Prep', 'approved'),
('Equipotential surfaces for a point charge are', 'Concentric spheres centred on the charge', 'Parallel planes', 'Concentric cylinders', 'Radial lines', 'option1', 'Since $V = kQ/r$ depends only on $r$, surfaces of constant $V$ are spheres of constant $r$.', 'p_electric_potential', 1, 'JEE Mains Prep', 'approved'),
('The potential at a distance of $0.1\;\text{m}$ from a charge of $5 \times 10^{-8}\;\text{C}$ is (take $k = 9 \times 10^9$)', '$45\;\text{V}$', '$450\;\text{V}$', '$4500\;\text{V}$', '$4.5\;\text{V}$', 'option2', '$V = kQ/r = 9 \times 10^9 \times 5 \times 10^{-8}/0.1 = 450\;\text{V}$.', 'p_electric_potential', 2, 'JEE Mains Prep', 'approved'),
('Two charges $+q$ and $-q$ are placed at $(0, +a)$ and $(0, -a)$. The potential at point $(d, 0)$ where $d \gg a$ is', 'Zero', '$kq/d$', '$2kqa/d^2$', '$kq/d^2$', 'option1', 'Point $(d, 0)$ is on the perpendicular bisector (equatorial plane) of the dipole. The potential on the equatorial plane is zero.', 'p_electric_potential', 2, 'JEE Mains Prep', 'approved'),
('The potential at the axial point of a dipole at large distance $r$ ($r \gg 2a$) varies as', '$1/r$', '$1/r^2$', '$1/r^3$', '$r$', 'option2', '$V_{axial} = kp\cos\theta/r^2$. On the axis ($\theta = 0$): $V = kp/r^2 \propto 1/r^2$.', 'p_electric_potential', 2, 'JEE Mains Prep', 'approved'),
('Three equal charges $q$ are placed at the vertices of an equilateral triangle of side $a$. The potential at the centroid is', '$kq\sqrt{3}/a$', '$3kq\sqrt{3}/a$', '$3kq/a$', '$kq/(a\sqrt{3})$', 'option2', 'Distance from centroid to vertex $= a/\sqrt{3}$. $V = 3 \times kq/(a/\sqrt{3}) = 3kq\sqrt{3}/a$.', 'p_electric_potential', 2, 'JEE Mains Prep', 'approved'),
('If the potential in a region is $V = 3x^2 + 4y\;\text{V}$, the electric field at point $(1, 2)$ is', '$-6\hat{i} - 4\hat{j}\;\text{V/m}$', '$6\hat{i} + 4\hat{j}\;\text{V/m}$', '$6\hat{i} - 4\hat{j}\;\text{V/m}$', '$-6\hat{i} + 4\hat{j}\;\text{V/m}$', 'option1', '$E_x = -\partial V/\partial x = -6x = -6$ at $x=1$. $E_y = -\partial V/\partial y = -4$. $\vec{E} = -6\hat{i} - 4\hat{j}\;\text{V/m}$.', 'p_electric_potential', 2, 'JEE Mains Prep', 'approved'),
('The potential at the centre of a uniformly charged ring of total charge $Q$ and radius $R$ is', 'Zero', '$kQ/R$', '$kQ/R^2$', '$kQ/(2R)$', 'option2', 'All charge elements are at distance $R$ from the centre. $V = kQ/R$.', 'p_electric_potential', 2, 'JEE Mains Prep', 'approved'),
('The potential at the surface of a conducting sphere of radius $R$ carrying charge $Q$ is $V_0$. The potential at distance $2R$ from the centre is', '$2V_0$', '$V_0/4$', '$V_0$', '$V_0/2$', 'option4', '$V_0 = kQ/R$. At $r = 2R$: $V = kQ/(2R) = V_0/2$.', 'p_electric_potential', 2, 'JEE Mains Prep', 'approved'),
('A charge $Q$ is distributed uniformly over a thin ring of radius $R$. The potential at a point on the axis at distance $x$ from the centre is', '$kQ/\sqrt{R^2 + x^2}$', '$kQx/(R^2 + x^2)$', '$kQ/(R + x)$', '$kQR/(R^2 + x^2)$', 'option1', 'Each element is at distance $\sqrt{R^2 + x^2}$ from the point. $V = kQ/\sqrt{R^2 + x^2}$.', 'p_electric_potential', 3, 'JEE Mains Prep', 'approved'),
('A conducting sphere of radius $R_1$ and charge $Q_1$ is connected by a wire to another sphere of radius $R_2$ and charge $Q_2$. After equilibrium, the ratio of surface charge densities $\sigma_1/\sigma_2$ is', '$(R_1/R_2)^2$', '$R_1/R_2$', '$(R_2/R_1)^2$', '$R_2/R_1$', 'option4', 'At equilibrium, potentials are equal: $kQ_1''/R_1 = kQ_2''/R_2$. Since $\sigma = Q/(4\pi R^2)$, $\sigma_1/\sigma_2 = (Q_1''/R_1^2)/(Q_2''/R_2^2) = R_2/R_1$.', 'p_electric_potential', 3, 'JEE Mains Prep', 'approved'),
('The potential at a point due to a short dipole ($r \gg 2a$) at angle $\theta$ from the axis is $V = kp\cos\theta/r^2$. The locus of points where $V = 0$ is', 'A cylinder around the dipole', 'A sphere around the dipole', 'A cone of half-angle $45°$', 'A plane perpendicular to the dipole axis through the centre', 'option4', '$V = 0$ when $\cos\theta = 0$, i.e., $\theta = 90°$. This is the equatorial plane.', 'p_electric_potential', 3, 'JEE Mains Prep', 'approved'),
('Two concentric conducting shells of radii $R$ and $2R$ carry charges $+Q$ and $-Q$ respectively. The potential difference between them is', '$3kQ/(2R)$', '$kQ/R$', '$kQ/(2R)$', '$kQ/(4R)$', 'option3', '$V_{inner} = kQ/R + k(-Q)/(2R) = kQ/(2R)$. $V_{outer} = kQ/(2R) + k(-Q)/(2R) = 0$. $\Delta V = kQ/(2R)$.', 'p_electric_potential', 3, 'JEE Mains Prep', 'approved'),
('A solid conducting sphere of radius $R$ carries charge $Q$. The potential at the centre of the sphere is', 'Infinite', 'Zero', '$kQ/R^2$', '$kQ/R$ (same as at the surface)', 'option4', 'Inside a conductor, $E = 0$ everywhere. Since $V(r) = V(R) - \int_R^r E\,dr$ and $E = 0$ inside, $V$ is constant throughout and equals the surface potential $kQ/R$.', 'p_electric_potential', 3, 'JEE Mains Prep', 'approved'),
('A thin spherical shell of radius $R$ has a total charge $Q$ distributed uniformly. The potential at a point inside the shell at distance $r$ from the centre ($r < R$) is', 'Zero', '$kQ/r$', '$kQ/R$', '$kQ(R^2 - r^2)/(2R^3)$', 'option3', 'Inside a uniformly charged shell, $E = 0$, so $V$ is constant and equals the surface value: $V = kQ/R$ for all $r < R$.', 'p_electric_potential', 3, 'JEE Mains Prep', 'approved'),
('The electric potential varies along the $x$-axis as $V = 5 - 3x^2$ (in SI units). The magnitude of the electric field at $x = 2\;\text{m}$ is', '$12\;\text{V/m}$', '$6\;\text{V/m}$', '$7\;\text{V/m}$', '$1\;\text{V/m}$', 'option1', '$E = -dV/dx = -(-6x) = 6x$. At $x = 2$: $E = 12\;\text{V/m}$.', 'p_electric_potential', 3, 'JEE Mains Prep', 'approved'),

-- ============================================================
-- p_potential_energy (7 easy, 7 medium, 7 hard = 21)
-- ============================================================
('The electrostatic potential energy of a system of two point charges $q_1$ and $q_2$ separated by distance $r$ is', '$kq_1 q_2 r$', '$kq_1 q_2/r^2$', '$(q_1 + q_2)/r$', '$kq_1 q_2/r$', 'option4', '$U = kq_1 q_2/r$. This is the work done in assembling the system from infinity.', 'p_potential_energy', 1, 'JEE Mains Prep', 'approved'),
('The potential energy of a dipole in a uniform electric field $\vec{E}$ is', '$\vec{p}\cdot\vec{E}$', '$-\vec{p}\cdot\vec{E}$', '$pE$', '$p/E$', 'option2', '$U = -\vec{p}\cdot\vec{E} = -pE\cos\theta$, where $\theta$ is the angle between $\vec{p}$ and $\vec{E}$.', 'p_potential_energy', 1, 'JEE Mains Prep', 'approved'),
('The potential energy of a dipole is minimum when the angle between $\vec{p}$ and $\vec{E}$ is', '$0°$', '$90°$', '$180°$', '$45°$', 'option1', '$U = -pE\cos\theta$ is minimum when $\cos\theta = 1$, i.e., $\theta = 0°$ (dipole aligned with field). $U_{min} = -pE$.', 'p_potential_energy', 1, 'JEE Mains Prep', 'approved'),
('The potential energy of two like charges brought closer together', 'Remains zero', 'Decreases', 'Increases', 'First increases then decreases', 'option3', 'For like charges, $U = kq_1 q_2/r > 0$. As $r$ decreases, $U$ increases (repulsive interaction stores more energy).', 'p_potential_energy', 1, 'JEE Mains Prep', 'approved'),
('The electrostatic potential energy of a charge $q$ at a point where the potential is $V$ is', '$q/V$', '$qV$', '$V/q$', '$q^2 V$', 'option2', '$U = qV$. This is the work done in bringing charge $q$ from infinity to a point at potential $V$.', 'p_potential_energy', 1, 'JEE Mains Prep', 'approved'),
('The potential energy of a dipole in unstable equilibrium ($\theta = 180°$) in a uniform field $E$ is', '$+pE$', '$-pE$', 'Zero', '$2pE$', 'option1', '$U = -pE\cos 180° = -pE(-1) = +pE$.', 'p_potential_energy', 1, 'JEE Mains Prep', 'approved'),
('The potential energy of a system of two charges $+2\;\mu\text{C}$ and $-3\;\mu\text{C}$ separated by $0.1\;\text{m}$ is', '$+0.54\;\text{J}$', '$-0.54\;\text{J}$', '$-5.4\;\text{J}$', '$+5.4\;\text{J}$', 'option2', '$U = kq_1 q_2/r = 9 \times 10^9 \times 2 \times 10^{-6} \times (-3 \times 10^{-6})/0.1 = -0.54\;\text{J}$.', 'p_potential_energy', 1, 'JEE Mains Prep', 'approved'),
('Three charges $q$, $q$, and $q$ are placed at the vertices of an equilateral triangle of side $a$. The total potential energy of the system is', '$3kq^2/a$', '$kq^2/a$', '$kq^2/(3a)$', '$6kq^2/a$', 'option1', 'Three pairs, each with energy $kq^2/a$. Total $U = 3 \times kq^2/a$.', 'p_potential_energy', 2, 'JEE Mains Prep', 'approved'),
('The work done in rotating a dipole from $\theta_1 = 60°$ to $\theta_2 = 90°$ in a uniform field $E$ is', '$pE$', '$pE/2$', '$pE(\sqrt{3}/2)$', '$pE(1 - \sqrt{3}/2)$', 'option2', '$W = pE(\cos\theta_1 - \cos\theta_2) = pE(\cos 60° - \cos 90°) = pE(1/2 - 0) = pE/2$.', 'p_potential_energy', 2, 'JEE Mains Prep', 'approved'),
('Four equal charges $q$ are placed at the corners of a square of side $a$. The potential energy of the system is', '$kq^2(4 + \sqrt{2})/(a\sqrt{2})$', '$4kq^2/a$', '$kq^2(4 + \sqrt{2})/a$', '$6kq^2/a$', 'option3', 'There are 6 pairs: 4 pairs at distance $a$ and 2 pairs at diagonal $a\sqrt{2}$. $U = 4 \times kq^2/a + 2 \times kq^2/(a\sqrt{2}) = kq^2(4 + \sqrt{2})/a$.', 'p_potential_energy', 2, 'JEE Mains Prep', 'approved'),
('A charge $q$ is moved from a point at potential $V_1 = 100\;\text{V}$ to a point at potential $V_2 = 50\;\text{V}$. If $q = 2\;\mu\text{C}$, the work done by the electric field is', '$-3 \times 10^{-4}\;\text{J}$', '$-10^{-4}\;\text{J}$', '$3 \times 10^{-4}\;\text{J}$', '$10^{-4}\;\text{J}$', 'option4', '$W_{field} = q(V_1 - V_2) = 2 \times 10^{-6}(100 - 50) = 10^{-4}\;\text{J}$.', 'p_potential_energy', 2, 'JEE Mains Prep', 'approved'),
('The self-energy (energy stored) of a uniformly charged sphere of total charge $Q$ and radius $R$ is', '$3kQ^2/(5R)$', '$kQ^2/(2R)$', '$kQ^2/R$', '$5kQ^2/(3R)$', 'option1', 'The self-energy of a uniformly charged solid sphere is $U = 3kQ^2/(5R)$, obtained by integrating the energy of assembling shells.', 'p_potential_energy', 2, 'JEE Mains Prep', 'approved'),
('Two identical conducting spheres carrying charges $Q$ and $-3Q$ are brought into contact and then separated. The change in total electrostatic energy of the system is', 'Cannot be determined', 'Energy increases', 'Energy remains the same', 'Energy decreases', 'option4', 'After contact, each sphere has charge $-Q$. Initial energy $\propto Q \times (-3Q) < 0$. Final energy $\propto (-Q)(-Q) > 0$. The system releases energy during charge redistribution (sparking), so total energy decreases.', 'p_potential_energy', 2, 'JEE Mains Prep', 'approved'),
('The work done in bringing a charge $q$ from infinity to a point where the potential due to a charge $Q$ is $V_0$ is', '$qV_0$', '$QV_0$', '$qV_0/2$', '$2qV_0$', 'option1', '$W = q \times V_0$. The potential $V_0 = kQ/r$ is already established; the work to bring $q$ there is $qV_0$.', 'p_potential_energy', 2, 'JEE Mains Prep', 'approved'),
('Two point charges $+q$ and $+4q$ are separated by distance $L$. A third charge $Q$ is placed so the entire system is in equilibrium. The value of $Q$ is', '$-q/9$', '$-q/4$', '$+q/4$', '$-4q/9$', 'option4', 'For force balance on $Q$ placed at distance $d$ from $+q$: $kqQ/d^2 = k(4q)Q/(L-d)^2$, giving $(L-d)/d = 2$, so $d = L/3$. For force balance on $+q$: $kqQ/(L/3)^2 + kq(4q)/L^2 = 0$, giving $9kqQ/L^2 = -4kq^2/L^2$, so $Q = -4q/9$.', 'p_potential_energy', 3, 'JEE Mains Prep', 'approved'),
('An electron ($e = 1.6 \times 10^{-19}\;\text{C}$) is accelerated through a potential difference of $100\;\text{V}$. Its kinetic energy gained is', '$1.6 \times 10^{-17}\;\text{J}$', '$1.6 \times 10^{-19}\;\text{J}$', '$100\;\text{eV}$', 'Both option1 and option3', 'option4', '$KE = eV = 1.6 \times 10^{-19} \times 100 = 1.6 \times 10^{-17}\;\text{J} = 100\;\text{eV}$. Both expressions are correct.', 'p_potential_energy', 3, 'JEE Mains Prep', 'approved'),
('A dipole of moment $p$ is placed in a non-uniform electric field. The dipole experiences', 'Neither torque nor force', 'Only a torque', 'Only a net force', 'Both a torque and a net force', 'option4', 'In a non-uniform field, the forces on $+q$ and $-q$ are unequal, producing both a net force (translational) and a torque (rotational).', 'p_potential_energy', 3, 'JEE Mains Prep', 'approved'),
('The total energy required to assemble four charges $+q$ at the corners of a square of side $a$ starting from infinity is', '$kq^2(4 + \sqrt{2})/a$', '$4kq^2/a$', '$6kq^2/a$', '$kq^2(4 - \sqrt{2})/a$', 'option1', '6 pairs: 4 side-pairs at distance $a$, 2 diagonal-pairs at $a\sqrt{2}$. $U = 4kq^2/a + 2kq^2/(a\sqrt{2}) = kq^2(4 + \sqrt{2})/a$.', 'p_potential_energy', 3, 'JEE Mains Prep', 'approved'),
('A charge $+q$ is fixed at the origin. Another charge $+q$ is released from rest at distance $d$. The speed of the released charge at infinity is', '$\sqrt{2kq^2/(md)}$', '$\sqrt{kq^2/(md)}$', '$\sqrt{kq^2/(2md)}$', '$\sqrt{4kq^2/(md)}$', 'option1', 'By energy conservation: $kq^2/d = \frac{1}{2}mv^2$. $v = \sqrt{2kq^2/(md)}$.', 'p_potential_energy', 3, 'JEE Mains Prep', 'approved'),
('Two charges $+Q$ and $-Q$ are fixed at distance $2a$ apart. A charge $+q$ (mass $m$) is released from the midpoint along the perpendicular bisector at distance $y \ll a$. The motion is', 'Uniformly accelerated', 'Uniform velocity', 'Simple harmonic with $\omega = \sqrt{2kQq/(ma^3)}$', 'Not periodic', 'option3', 'At the midpoint, the net force is zero. For small displacement $y$ along the bisector, the restoring force is $F \approx -2kQqy/a^3$ (dipole-like). This gives SHM with $\omega = \sqrt{2kQq/(ma^3)}$.', 'p_potential_energy', 3, 'JEE Mains Prep', 'approved'),
('The energy stored in the electric field of a charged conducting sphere of radius $R$ and charge $Q$ is', '$kQ^2/(4R)$', '$kQ^2/R$', '$kQ^2/(2R)$', '$3kQ^2/(5R)$', 'option3', 'Energy $= \int_R^\infty \frac{\epsilon_0 E^2}{2} 4\pi r^2\,dr = \int_R^\infty \frac{kQ^2}{2r^2}\,dr = kQ^2/(2R)$.', 'p_potential_energy', 3, 'JEE Mains Prep', 'approved'),

-- ============================================================
-- p_capacitors_dielectrics (7 easy, 7 medium, 7 hard = 21)
-- ============================================================
('The capacitance of a parallel plate capacitor with plate area $A$ and separation $d$ is', '$\epsilon_0 A d$', '$\epsilon_0 d/A$', '$A/(4\pi\epsilon_0 d)$', '$\epsilon_0 A/d$', 'option4', '$C = \epsilon_0 A/d$ for a parallel plate capacitor with vacuum between plates.', 'p_capacitors_dielectrics', 1, 'JEE Mains Prep', 'approved'),
('The SI unit of capacitance is', 'Farad (F)', 'Coulomb (C)', 'Volt (V)', 'Henry (H)', 'option1', 'Capacitance is measured in farads: $1\;\text{F} = 1\;\text{C/V}$.', 'p_capacitors_dielectrics', 1, 'JEE Mains Prep', 'approved'),
('When a dielectric of constant $K$ is inserted between the plates of a capacitor, the capacitance', 'Becomes zero', 'Decreases by factor $K$', 'Remains unchanged', 'Increases by factor $K$', 'option4', '$C = K\epsilon_0 A/d = KC_0$. The dielectric increases capacitance by factor $K$.', 'p_capacitors_dielectrics', 1, 'JEE Mains Prep', 'approved'),
('The energy stored in a capacitor of capacitance $C$ charged to voltage $V$ is', '$\frac{1}{2}CV^2$', '$CV^2$', '$CV$', '$\frac{1}{2}C^2V$', 'option1', '$U = \frac{1}{2}CV^2 = \frac{1}{2}QV = Q^2/(2C)$.', 'p_capacitors_dielectrics', 1, 'JEE Mains Prep', 'approved'),
('Two capacitors $C_1$ and $C_2$ in series have equivalent capacitance', '$C_1 + C_2$', '$C_1 C_2/(C_1 + C_2)$', '$C_1 C_2$', '$(C_1 + C_2)/(C_1 C_2)$', 'option2', 'In series: $1/C_{eq} = 1/C_1 + 1/C_2$, giving $C_{eq} = C_1 C_2/(C_1 + C_2)$.', 'p_capacitors_dielectrics', 1, 'JEE Mains Prep', 'approved'),
('Two capacitors $C_1$ and $C_2$ in parallel have equivalent capacitance', '$C_1 + C_2$', '$C_1 C_2/(C_1 + C_2)$', '$C_1 - C_2$', '$\sqrt{C_1 C_2}$', 'option1', 'In parallel, capacitances add directly: $C_{eq} = C_1 + C_2$.', 'p_capacitors_dielectrics', 1, 'JEE Mains Prep', 'approved'),
('A conductor in electrostatic equilibrium has electric field inside it equal to', 'Depends on the shape', '$\sigma/\epsilon_0$', '$\sigma/(2\epsilon_0)$', 'Zero', 'option4', 'Free charges redistribute until $E = 0$ inside. This is a fundamental property of conductors in equilibrium.', 'p_capacitors_dielectrics', 1, 'JEE Mains Prep', 'approved'),
('A $4\;\mu\text{F}$ capacitor is charged to $200\;\text{V}$. The energy stored is', '$0.8\;\text{J}$', '$0.08\;\text{J}$', '$0.04\;\text{J}$', '$0.4\;\text{J}$', 'option2', '$U = \frac{1}{2}CV^2 = \frac{1}{2} \times 4 \times 10^{-6} \times (200)^2 = 0.08\;\text{J}$.', 'p_capacitors_dielectrics', 2, 'JEE Mains Prep', 'approved'),
('Three capacitors of $2\;\mu\text{F}$, $3\;\mu\text{F}$, and $6\;\mu\text{F}$ are connected in series. The equivalent capacitance is', '$11\;\mu\text{F}$', '$1\;\mu\text{F}$', '$0.5\;\mu\text{F}$', '$6\;\mu\text{F}$', 'option2', '$1/C = 1/2 + 1/3 + 1/6 = 3/6 + 2/6 + 1/6 = 6/6 = 1$. $C = 1\;\mu\text{F}$.', 'p_capacitors_dielectrics', 2, 'JEE Mains Prep', 'approved'),
('A parallel plate capacitor of capacitance $C$ is charged to voltage $V$ and then disconnected. If the plate separation is doubled, the new voltage across the capacitor is', '$4V$', '$V/2$', '$V$', '$2V$', 'option4', 'Charge $Q = CV$ is conserved. New capacitance $C'' = C/2$ (since $C \propto 1/d$). New voltage $V'' = Q/C'' = CV/(C/2) = 2V$.', 'p_capacitors_dielectrics', 2, 'JEE Mains Prep', 'approved'),
('A capacitor of $5\;\mu\text{F}$ charged to $10\;\text{V}$ is connected to an uncharged $5\;\mu\text{F}$ capacitor. The common voltage is', '$5\;\text{V}$', '$10\;\text{V}$', '$2.5\;\text{V}$', '$20\;\text{V}$', 'option1', 'Charge conserved: $Q = 5 \times 10^{-6} \times 10 = 50\;\mu\text{C}$. Total capacitance $= 10\;\mu\text{F}$. $V = Q/C = 50/10 = 5\;\text{V}$.', 'p_capacitors_dielectrics', 2, 'JEE Mains Prep', 'approved'),
('The energy density (energy per unit volume) in an electric field $E$ is', '$\epsilon_0 E$', '$\epsilon_0 E^2$', '$\frac{1}{2}\epsilon_0 E^2$', '$E^2/(2\epsilon_0)$', 'option3', 'Energy density $u = \frac{1}{2}\epsilon_0 E^2$ in vacuum.', 'p_capacitors_dielectrics', 2, 'JEE Mains Prep', 'approved'),
('A capacitor is charged by a battery of emf $V$. The energy supplied by the battery is $QV$ but the energy stored is $QV/2$. The remaining energy', 'Violates energy conservation', 'Is stored in the battery', 'Is dissipated as heat in the connecting wires', 'Is radiated as EM waves only', 'option3', 'Half the energy ($QV/2$) is always dissipated as heat in the resistance of the circuit, regardless of how small the resistance is.', 'p_capacitors_dielectrics', 2, 'JEE Mains Prep', 'approved'),
('The capacitance of an isolated conducting sphere of radius $R$ is', '$4\pi\epsilon_0 R$', '$\epsilon_0 R$', '$4\pi\epsilon_0/R$', '$R/(4\pi\epsilon_0)$', 'option1', 'Treating the outer conductor as at infinity: $C = Q/V = Q/(kQ/R) = R/k = 4\pi\epsilon_0 R$.', 'p_capacitors_dielectrics', 2, 'JEE Mains Prep', 'approved'),
('A parallel plate capacitor ($C = 10\;\mu\text{F}$) is connected to a $100\;\text{V}$ battery. A dielectric ($K = 2$) is inserted while the battery remains connected. The new charge on the capacitor is', '$2\;\text{mC}$', '$1\;\text{mC}$', '$0.5\;\text{mC}$', '$4\;\text{mC}$', 'option1', 'With battery connected, $V = 100\;\text{V}$ (constant). New $C = KC_0 = 20\;\mu\text{F}$. $Q = CV = 20 \times 10^{-6} \times 100 = 2 \times 10^{-3}\;\text{C} = 2\;\text{mC}$.', 'p_capacitors_dielectrics', 3, 'JEE Mains Prep', 'approved'),
('A capacitor of $2\;\mu\text{F}$ charged to $200\;\text{V}$ is connected in parallel with an uncharged $8\;\mu\text{F}$ capacitor. The energy loss in the process is', '$4 \times 10^{-2}\;\text{J}$', '$3.2 \times 10^{-2}\;\text{J}$', '$0.8 \times 10^{-2}\;\text{J}$', '$1.6 \times 10^{-2}\;\text{J}$', 'option2', 'Initial energy $= \frac{1}{2}(2 \times 10^{-6})(200)^2 = 0.04\;\text{J}$. Common voltage $= 2 \times 200/10 = 40\;\text{V}$. Final energy $= \frac{1}{2}(10 \times 10^{-6})(40)^2 = 0.008\;\text{J}$. Loss $= 0.04 - 0.008 = 0.032\;\text{J}$.', 'p_capacitors_dielectrics', 3, 'JEE Mains Prep', 'approved'),
('A parallel plate capacitor has plate area $A$ and separation $d$. A metal slab of thickness $t$ ($t < d$) is inserted between the plates. The new capacitance is', '$\epsilon_0 A t/d$', '$\epsilon_0 A/d$', '$\epsilon_0 A/(d + t)$', '$\epsilon_0 A/(d - t)$', 'option4', 'The metal slab is an equipotential, effectively reducing the gap to $(d - t)$. $C = \epsilon_0 A/(d - t)$.', 'p_capacitors_dielectrics', 3, 'JEE Mains Prep', 'approved'),
('Two capacitors $C_1 = 6\;\mu\text{F}$ (charged to $12\;\text{V}$) and $C_2 = 3\;\mu\text{F}$ (charged to $6\;\text{V}$) are connected with plates of opposite polarity together. The final voltage is', '$6\;\text{V}$', '$4\;\text{V}$', '$9\;\text{V}$', '$2\;\text{V}$', 'option1', '$Q_1 = 72\;\mu\text{C}$, $Q_2 = 18\;\mu\text{C}$. Opposite polarity: net charge $= 72 - 18 = 54\;\mu\text{C}$. $V = 54/(6+3) = 6\;\text{V}$.', 'p_capacitors_dielectrics', 3, 'JEE Mains Prep', 'approved'),
('A spherical capacitor has inner radius $a$ and outer radius $b$. Its capacitance is', '$\epsilon_0 ab/(b - a)$', '$4\pi\epsilon_0(b - a)$', '$4\pi\epsilon_0 ab/(b - a)$', '$4\pi\epsilon_0 b$', 'option3', '$V = kQ(1/a - 1/b) = kQ(b-a)/(ab)$. $C = Q/V = 4\pi\epsilon_0 ab/(b-a)$.', 'p_capacitors_dielectrics', 3, 'JEE Mains Prep', 'approved'),
('A capacitor of capacitance $C$ is charged to $V$ and disconnected. A dielectric of constant $K$ is then inserted. The ratio of final to initial energy stored is', '$1/K$', '$K$', '$1/K^2$', '$K^2$', 'option1', 'Charge $Q$ is constant. $U_i = Q^2/(2C)$. $U_f = Q^2/(2KC)$. Ratio $= 1/K$. Energy decreases as the dielectric is pulled in by the field.', 'p_capacitors_dielectrics', 3, 'JEE Mains Prep', 'approved'),
('In a network, three capacitors of $3\;\mu\text{F}$ each form a triangle. A battery of $6\;\text{V}$ is connected across one side. The charge on the capacitor directly across the battery is', '$12\;\mu\text{C}$', '$18\;\mu\text{C}$', '$6\;\mu\text{C}$', '$9\;\mu\text{C}$', 'option2', 'The capacitor directly across the battery has full $6\;\text{V}$ across it: $Q = 3 \times 6 = 18\;\mu\text{C}$. The other two are in series (equivalent $1.5\;\mu\text{F}$) in parallel with it, carrying $9\;\mu\text{C}$ each.', 'p_capacitors_dielectrics', 3, 'JEE Mains Prep', 'approved'),

-- ============================================================
-- p_drift_velocity_current (7 easy, 7 medium, 7 hard = 21)
-- ============================================================
('Electric current is defined as', 'Rate of flow of charge', 'Rate of flow of electrons', 'Force per unit charge', 'Energy per unit charge', 'option1', '$I = dQ/dt$. Current is the rate of flow of charge through a cross-section.', 'p_drift_velocity_current', 1, 'JEE Mains Prep', 'approved'),
('The SI unit of electric current is', 'Coulomb (C)', 'Ampere (A)', 'Volt (V)', 'Ohm ($\Omega$)', 'option2', 'Current is measured in amperes: $1\;\text{A} = 1\;\text{C/s}$.', 'p_drift_velocity_current', 1, 'JEE Mains Prep', 'approved'),
('Drift velocity of electrons in a conductor is', 'Independent of the applied field', 'Equal to the speed of light', 'Very small ($\sim 10^{-4}\;\text{m/s}$) and proportional to the applied field', 'Very large ($\sim 10^6\;\text{m/s}$)', 'option3', 'Drift velocity $v_d = eE\tau/m \sim 10^{-4}\;\text{m/s}$, directly proportional to $E$.', 'p_drift_velocity_current', 1, 'JEE Mains Prep', 'approved'),
('The relation between current $I$, number density $n$, drift velocity $v_d$, cross-sectional area $A$, and charge $e$ is', '$I = neAv_d$', '$I = ne/Av_d$', '$I = nAv_d$', '$I = eAv_d/n$', 'option1', '$I = neAv_d$ where $n$ is the number of free electrons per unit volume.', 'p_drift_velocity_current', 1, 'JEE Mains Prep', 'approved'),
('Mobility of a charge carrier is defined as', 'Conductivity per unit length', 'Current per unit area', 'Charge per unit time', 'Drift velocity per unit electric field', 'option4', 'Mobility $\mu = v_d/E = e\tau/m$.', 'p_drift_velocity_current', 1, 'JEE Mains Prep', 'approved'),
('The direction of conventional current is', 'Opposite to the direction of electron flow', 'Same as the direction of electron flow', 'Perpendicular to electron flow', 'Random', 'option1', 'Conventional current flows from positive to negative terminal (opposite to electron drift).', 'p_drift_velocity_current', 1, 'JEE Mains Prep', 'approved'),
('Current density $\vec{J}$ is related to electric field $\vec{E}$ by', '$\vec{J} = \vec{E}/\sigma$', '$\vec{J} = \sigma\vec{E}$', '$\vec{J} = \rho\vec{E}$', '$\vec{J} = \vec{E}\sigma^2$', 'option2', '$\vec{J} = \sigma\vec{E}$ where $\sigma$ is the conductivity. This is the microscopic form of Ohm''s law.', 'p_drift_velocity_current', 1, 'JEE Mains Prep', 'approved'),
('A copper wire carries a current of $5\;\text{A}$. If the wire has cross-sectional area $10^{-6}\;\text{m}^2$ and free electron density $8 \times 10^{28}\;\text{m}^{-3}$, the drift velocity is approximately', '$3.9 \times 10^{-4}\;\text{m/s}$', '$3.9 \times 10^{-2}\;\text{m/s}$', '$3.9 \times 10^{-6}\;\text{m/s}$', '$3.9\;\text{m/s}$', 'option1', '$v_d = I/(neA) = 5/(8 \times 10^{28} \times 1.6 \times 10^{-19} \times 10^{-6}) = 5/(1.28 \times 10^4) \approx 3.9 \times 10^{-4}\;\text{m/s}$.', 'p_drift_velocity_current', 2, 'JEE Mains Prep', 'approved'),
('If the drift velocity of electrons in a wire is doubled, the current', 'Doubles', 'Halves', 'Remains the same', 'Quadruples', 'option1', '$I = neAv_d$. Since $n$, $e$, $A$ are constant, $I \propto v_d$. Doubling $v_d$ doubles $I$.', 'p_drift_velocity_current', 2, 'JEE Mains Prep', 'approved'),
('A wire of cross-sectional area $A$ carries current $I$. If the wire is stretched to double its length (volume constant), the new drift velocity for the same current is', '$4v_d$', '$2v_d$', '$v_d/2$', '$v_d$', 'option2', 'Volume constant: $AL = A''(2L)$, so $A'' = A/2$. For the same current: $v_d'' = I/(neA'') = I/(ne \cdot A/2) = 2I/(neA) = 2v_d$.', 'p_drift_velocity_current', 2, 'JEE Mains Prep', 'approved'),
('The relaxation time of electrons in a conductor at temperature $T$ is $\tau$. If the temperature increases, $\tau$', 'Decreases', 'Increases', 'Remains constant', 'First increases then decreases', 'option1', 'Higher temperature means more frequent collisions with lattice ions, reducing the mean free time $\tau$.', 'p_drift_velocity_current', 2, 'JEE Mains Prep', 'approved'),
('A charge of $600\;\text{C}$ flows through a wire in $5\;\text{minutes}$. The current is', '$2\;\text{A}$', '$120\;\text{A}$', '$3000\;\text{A}$', '$0.5\;\text{A}$', 'option1', '$I = Q/t = 600/(5 \times 60) = 600/300 = 2\;\text{A}$.', 'p_drift_velocity_current', 2, 'JEE Mains Prep', 'approved'),
('The current density in a wire of radius $r$ carrying current $I$ is', '$I/(4\pi r^2)$', '$I/(2\pi r)$', '$I/r^2$', '$I/(\pi r^2)$', 'option4', '$J = I/A = I/(\pi r^2)$ for uniform current distribution.', 'p_drift_velocity_current', 2, 'JEE Mains Prep', 'approved'),
('If the number density of free electrons in copper is $n$ and in aluminium is $n/3$, and both wires have the same cross-section and carry the same current, the ratio of drift velocities $v_{Al}/v_{Cu}$ is', '$1$', '$1/3$', '$3$', '$9$', 'option3', '$v_d = I/(neA)$. For same $I$, $e$, $A$: $v_{Al}/v_{Cu} = n_{Cu}/n_{Al} = n/(n/3) = 3$.', 'p_drift_velocity_current', 2, 'JEE Mains Prep', 'approved'),
('A conductor has a non-uniform cross-section. When a steady current flows through it, the drift velocity is', 'Greater where the cross-section is smaller', 'Greater where the cross-section is larger', 'Same everywhere', 'Zero at the narrow end', 'option1', '$I = neAv_d$ is constant throughout. Where $A$ is smaller, $v_d$ must be larger.', 'p_drift_velocity_current', 3, 'JEE Mains Prep', 'approved'),
('The current in a wire varies with time as $I = 4 + 2t\;\text{A}$. The charge that flows through the wire from $t = 0$ to $t = 3\;\text{s}$ is', '$12\;\text{C}$', '$21\;\text{C}$', '$18\;\text{C}$', '$10\;\text{C}$', 'option2', '$Q = \int_0^3 (4 + 2t)\,dt = [4t + t^2]_0^3 = 12 + 9 = 21\;\text{C}$.', 'p_drift_velocity_current', 3, 'JEE Mains Prep', 'approved'),
('In the Drude model, the conductivity $\sigma$ of a metal is given by', '$ne^2/(m\tau)$', '$ne\tau/m$', '$ne^2\tau/m$', '$nm/(e^2\tau)$', 'option3', '$\sigma = ne^2\tau/m$ where $n$ is electron density, $\tau$ is relaxation time, $m$ is electron mass.', 'p_drift_velocity_current', 3, 'JEE Mains Prep', 'approved'),
('Two wires of the same material have lengths $L$ and $2L$ and radii $r$ and $2r$ respectively. If the same potential difference is applied, the ratio of drift velocities $v_1/v_2$ is', '$1$', '$1/2$', '$4$', '$2$', 'option4', '$v_d = eE\tau/m$ and $E = V/L$. So $v_1/v_2 = (V/L)/(V/2L) = 2$. The radius does not affect drift velocity directly (it affects current, not $v_d$ for given $E$).', 'p_drift_velocity_current', 3, 'JEE Mains Prep', 'approved'),
('A metallic wire has a current density that varies as $J = J_0 r/R$ where $r$ is the distance from the axis and $R$ is the wire radius. The total current through the wire is', '$\pi J_0 R^2$', '$2\pi J_0 R^2/3$', '$\pi J_0 R^2/2$', '$J_0 R^2/3$', 'option2', '$I = \int_0^R J \cdot 2\pi r\,dr = \int_0^R (J_0 r/R)(2\pi r)\,dr = (2\pi J_0/R)\int_0^R r^2\,dr = (2\pi J_0/R)(R^3/3) = 2\pi J_0 R^2/3$.', 'p_drift_velocity_current', 3, 'JEE Mains Prep', 'approved'),
('The mean free path of electrons in a conductor is $\lambda$ and the rms speed of electrons is $v_{rms}$. The relaxation time is', '$\lambda^2/v_{rms}$', '$v_{rms}/\lambda$', '$\lambda v_{rms}$', '$\lambda/v_{rms}$', 'option4', '$\tau = \lambda/v_{rms}$. The relaxation time is the average time between collisions.', 'p_drift_velocity_current', 3, 'JEE Mains Prep', 'approved'),
('In a semiconductor, the current is carried by both electrons (density $n_e$, mobility $\mu_e$) and holes (density $n_h$, mobility $\mu_h$). The conductivity is', '$e(n_e\mu_e - n_h\mu_h)$', '$e(n_e\mu_e + n_h\mu_h)$', '$e(n_e + n_h)(\mu_e + \mu_h)$', '$e\sqrt{n_e n_h \mu_e \mu_h}$', 'option2', '$\sigma = n_e e\mu_e + n_h e\mu_h = e(n_e\mu_e + n_h\mu_h)$. Both carriers contribute to conductivity.', 'p_drift_velocity_current', 3, 'JEE Mains Prep', 'approved'),

-- ============================================================
-- p_ohms_law_resistance (7 easy, 7 medium, 7 hard = 21)
-- ============================================================
('Ohm''s law states that', '$V = I/R$', '$V = IR$ (voltage is proportional to current for a given resistance)', '$R = VI^2$', '$I = VR$', 'option2', 'Ohm''s law: $V = IR$, where $R$ is constant for ohmic conductors.', 'p_ohms_law_resistance', 1, 'JEE Mains Prep', 'approved'),
('The SI unit of electrical resistance is', 'Ohm ($\Omega$)', 'Siemens (S)', 'Volt (V)', 'Ampere (A)', 'option1', 'Resistance is measured in ohms: $1\;\Omega = 1\;\text{V/A}$.', 'p_ohms_law_resistance', 1, 'JEE Mains Prep', 'approved'),
('The resistance of a wire is proportional to', 'Its cross-sectional area', 'Its length and inversely proportional to its cross-sectional area', 'The square of its length', 'Its volume', 'option2', '$R = \rho L/A$. Resistance increases with length and decreases with area.', 'p_ohms_law_resistance', 1, 'JEE Mains Prep', 'approved'),
('A device that does not obey Ohm''s law is called', 'Insulator', 'Superconductor', 'Non-ohmic', 'Semiconductor always', 'option3', 'Devices with non-linear I-V characteristics (like diodes, LEDs) are non-ohmic.', 'p_ohms_law_resistance', 1, 'JEE Mains Prep', 'approved'),
('Two resistors of $4\;\Omega$ and $6\;\Omega$ in parallel have equivalent resistance', '$10\;\Omega$', '$2.4\;\Omega$', '$5\;\Omega$', '$1.5\;\Omega$', 'option2', '$R = 4 \times 6/(4 + 6) = 24/10 = 2.4\;\Omega$.', 'p_ohms_law_resistance', 1, 'JEE Mains Prep', 'approved'),
('The I-V characteristic of an ohmic conductor is', 'A straight line through the origin', 'A curve', 'A straight line not through the origin', 'A parabola', 'option1', 'For ohmic conductors, $I \propto V$ (constant $R$), giving a straight line through the origin.', 'p_ohms_law_resistance', 1, 'JEE Mains Prep', 'approved'),
('Three resistors of $3\;\Omega$ each in series have total resistance', '$9\;\Omega$', '$1\;\Omega$', '$3\;\Omega$', '$27\;\Omega$', 'option1', 'In series: $R_{total} = 3 + 3 + 3 = 9\;\Omega$.', 'p_ohms_law_resistance', 1, 'JEE Mains Prep', 'approved'),
('A wire of resistance $R$ is cut into 4 equal pieces and connected in parallel. The equivalent resistance is', '$R/4$', '$R/16$', '$4R$', '$R$', 'option2', 'Each piece has resistance $R/4$. Four in parallel: $R_{eq} = (R/4)/4 = R/16$.', 'p_ohms_law_resistance', 2, 'JEE Mains Prep', 'approved'),
('A wire of resistance $12\;\Omega$ is bent into a circle. The resistance between two diametrically opposite points is', '$3\;\Omega$', '$6\;\Omega$', '$12\;\Omega$', '$24\;\Omega$', 'option1', 'Two semicircles of $6\;\Omega$ each in parallel: $R = 6 \times 6/(6 + 6) = 3\;\Omega$.', 'p_ohms_law_resistance', 2, 'JEE Mains Prep', 'approved'),
('A wire of resistance $R$ is stretched to twice its original length. Its new resistance is', '$4R$', '$2R$', '$R/2$', '$R/4$', 'option1', 'Volume constant: $AL = A''(2L)$, so $A'' = A/2$. $R'' = \rho(2L)/(A/2) = 4\rho L/A = 4R$.', 'p_ohms_law_resistance', 2, 'JEE Mains Prep', 'approved'),
('Five resistors of $1\;\Omega$ each are connected: two in series, and this combination in parallel with three in series. The equivalent resistance is', '$5/6\;\Omega$', '$6/5\;\Omega$', '$5\;\Omega$', '$1\;\Omega$', 'option2', 'Branch 1: $2\;\Omega$. Branch 2: $3\;\Omega$. Parallel: $R = 2 \times 3/(2 + 3) = 6/5\;\Omega$.', 'p_ohms_law_resistance', 2, 'JEE Mains Prep', 'approved'),
('The colour code of a resistor reads Brown-Black-Red-Gold. Its resistance is', '$1000\;\Omega \pm 5\%$', '$100\;\Omega \pm 5\%$', '$10000\;\Omega \pm 5\%$', '$10\;\Omega \pm 5\%$', 'option1', 'Brown=1, Black=0, Red=multiplier $10^2$. Resistance $= 10 \times 100 = 1000\;\Omega$. Gold $= \pm 5\%$.', 'p_ohms_law_resistance', 2, 'JEE Mains Prep', 'approved'),
('A current of $2\;\text{A}$ flows through a $5\;\Omega$ resistor. The potential difference across it is', '$0.4\;\text{V}$', '$2.5\;\text{V}$', '$10\;\text{V}$', '$7\;\text{V}$', 'option3', '$V = IR = 2 \times 5 = 10\;\text{V}$.', 'p_ohms_law_resistance', 2, 'JEE Mains Prep', 'approved'),
('The equivalent resistance of $n$ identical resistors each of resistance $R$ connected in parallel is', '$R/n^2$', '$nR$', '$R$', '$R/n$', 'option4', 'In parallel: $1/R_{eq} = n/R$, so $R_{eq} = R/n$.', 'p_ohms_law_resistance', 2, 'JEE Mains Prep', 'approved'),
('A wire of resistance $R$ has its radius halved and length doubled. The new resistance is', '$2R$', '$4R$', '$16R$', '$8R$', 'option4', 'Area $= \pi(r/2)^2 = \pi r^2/4 = A/4$. $R'' = \rho(2L)/(A/4) = 8\rho L/A = 8R$.', 'p_ohms_law_resistance', 3, 'JEE Mains Prep', 'approved'),
('An infinite ladder network has each series element $R_1$ and each shunt element $R_2$. The equivalent resistance is', '$(R_1 + \sqrt{R_1^2 + 4R_1 R_2})/2$', '$R_1 + R_2$', '$R_1 R_2/(R_1 + R_2)$', '$\sqrt{R_1 R_2}$', 'option1', 'Let equivalent resistance be $R$. Then $R = R_1 + R_2 R/(R_2 + R)$. Solving: $R(R_2 + R) = R_1(R_2 + R) + R_2 R$. $R^2 + R_2 R = R_1 R_2 + R_1 R + R_2 R$. $R^2 - R_1 R - R_1 R_2 = 0$. $R = (R_1 + \sqrt{R_1^2 + 4R_1 R_2})/2$.', 'p_ohms_law_resistance', 3, 'JEE Mains Prep', 'approved'),
('A wire of resistance $16\;\Omega$ is bent into a square. The resistance between adjacent corners is', '$12\;\Omega$', '$4\;\Omega$', '$3\;\Omega$', '$8\;\Omega$', 'option3', 'Each side $= 4\;\Omega$. Between adjacent corners: one side ($4\;\Omega$) in parallel with three sides in series ($12\;\Omega$). $R = 4 \times 12/(4 + 12) = 48/16 = 3\;\Omega$.', 'p_ohms_law_resistance', 3, 'JEE Mains Prep', 'approved'),
('A network has 12 identical resistors of $R$ each forming the edges of a cube. The resistance between two diagonally opposite corners is', '$5R/6$', '$R$', '$7R/12$', '$R/6$', 'option1', 'By symmetry and Kirchhoff''s laws: current splits into 3 at the first node, then 6 paths of 2 each at the middle, then combines at the last node. $R_{eq} = 5R/6$.', 'p_ohms_law_resistance', 3, 'JEE Mains Prep', 'approved'),
('Two wires of the same material have resistances in the ratio $1:2$ and lengths in the ratio $1:3$. The ratio of their radii $r_1:r_2$ is', '$\sqrt{2}:\sqrt{3}$', '$\sqrt{3}:\sqrt{2}$', '$2:3$', '$3:2$', 'option1', '$R \propto L/r^2$, so $r^2 \propto L/R$. $r_1^2/r_2^2 = (L_1 R_2)/(L_2 R_1) = (1 \times 2)/(3 \times 1) = 2/3$. $r_1/r_2 = \sqrt{2/3} = \sqrt{2}/\sqrt{3}$.', 'p_ohms_law_resistance', 3, 'JEE Mains Prep', 'approved'),
('A hollow cylinder of inner radius $a$ and outer radius $b$, length $L$, and resistivity $\rho$ carries current radially. The resistance between the inner and outer surfaces is', '$\rho(b-a)/(\pi(b^2-a^2))$', '$\rho\ln(b/a)/(2\pi L)$', '$\rho L/(\pi(b^2-a^2))$', '$\rho/(2\pi L(b-a))$', 'option2', 'Consider a thin shell at radius $r$, thickness $dr$. $dR = \rho\,dr/(2\pi rL)$. $R = \int_a^b \rho\,dr/(2\pi rL) = \rho\ln(b/a)/(2\pi L)$.', 'p_ohms_law_resistance', 3, 'JEE Mains Prep', 'approved'),
('A wire of resistance $24\;\Omega$ is bent into a circle. The resistance between two points subtending an angle of $60°$ at the centre is', '$20\;\Omega$', '$4\;\Omega$', '$10/3\;\Omega$', '$20/3\;\Omega$', 'option3', 'Arc subtending $60°$: $R_1 = 24 \times 60/360 = 4\;\Omega$. Remaining arc: $R_2 = 20\;\Omega$. Parallel: $R = 4 \times 20/(4 + 20) = 80/24 = 10/3\;\Omega$.', 'p_ohms_law_resistance', 3, 'JEE Mains Prep', 'approved'),

-- ============================================================
-- p_power_resistivity (7 easy, 7 medium, 7 hard = 21)
-- ============================================================
('Electrical power dissipated in a resistor $R$ carrying current $I$ is', '$IR$', '$I^2 R$', '$I/R$', '$I^2/R$', 'option2', '$P = I^2 R = VI = V^2/R$.', 'p_power_resistivity', 1, 'JEE Mains Prep', 'approved'),
('The SI unit of electrical power is', 'Joule (J)', 'Watt (W)', 'Volt-Ampere-second', 'Ohm (Ω)', 'option2', 'Power is measured in watts: $1\;\text{W} = 1\;\text{J/s} = 1\;\text{V} \times 1\;\text{A}$.', 'p_power_resistivity', 1, 'JEE Mains Prep', 'approved'),
('Resistivity of a material depends on', 'The nature of the material and temperature', 'The length of the conductor', 'The cross-sectional area', 'The applied voltage', 'option1', 'Resistivity $\rho$ is a material property that depends on the material and temperature, not on dimensions.', 'p_power_resistivity', 1, 'JEE Mains Prep', 'approved'),
('The SI unit of resistivity is', '$\text{S/m}$', '$\Omega/\text{m}$', '$\Omega\cdot\text{m}^2$', '$\Omega\cdot\text{m}$', 'option4', 'From $R = \rho L/A$: $\rho = RA/L$, unit $= \Omega \cdot \text{m}^2/\text{m} = \Omega\cdot\text{m}$.', 'p_power_resistivity', 1, 'JEE Mains Prep', 'approved'),
('For metals, resistivity with increasing temperature', 'First decreases then increases', 'Decreases', 'Remains constant', 'Increases', 'option4', 'In metals, increased temperature causes more lattice vibrations, increasing electron scattering and hence resistivity.', 'p_power_resistivity', 1, 'JEE Mains Prep', 'approved'),
('Conductivity $\sigma$ is related to resistivity $\rho$ by', '$\sigma = 1/\rho$', '$\sigma = \rho$', '$\sigma = \rho^2$', '$\sigma = \sqrt{\rho}$', 'option1', 'Conductivity is the reciprocal of resistivity: $\sigma = 1/\rho$.', 'p_power_resistivity', 1, 'JEE Mains Prep', 'approved'),
('The energy consumed by a $100\;\text{W}$ bulb in $10\;\text{hours}$ is', '$1\;\text{kWh}$', '$10\;\text{kWh}$', '$0.1\;\text{kWh}$', '$100\;\text{kWh}$', 'option1', '$E = Pt = 100 \times 10 = 1000\;\text{Wh} = 1\;\text{kWh}$.', 'p_power_resistivity', 1, 'JEE Mains Prep', 'approved'),
('Two bulbs rated $60\;\text{W}$ and $100\;\text{W}$ at $220\;\text{V}$ are connected in series to a $220\;\text{V}$ supply. Which bulb glows brighter?', 'The $60\;\text{W}$ bulb', 'The $100\;\text{W}$ bulb', 'Both glow equally', 'Neither glows', 'option1', 'In series, current is the same. $R_{60} = 220^2/60 > R_{100} = 220^2/100$. Power $= I^2 R$, so the higher resistance ($60\;\text{W}$ rated) dissipates more power and glows brighter.', 'p_power_resistivity', 2, 'JEE Mains Prep', 'approved'),
('A heater coil rated $1000\;\text{W}$ at $200\;\text{V}$ is connected to a $100\;\text{V}$ supply. The power consumed is', '$250\;\text{W}$', '$500\;\text{W}$', '$1000\;\text{W}$', '$125\;\text{W}$', 'option1', '$R = V_{rated}^2/P_{rated} = 200^2/1000 = 40\;\Omega$. At $100\;\text{V}$: $P = V^2/R = 100^2/40 = 250\;\text{W}$.', 'p_power_resistivity', 2, 'JEE Mains Prep', 'approved'),
('The resistance of a wire at $0°\text{C}$ is $10\;\Omega$ and at $100°\text{C}$ is $14\;\Omega$. The temperature coefficient of resistance is', '$4 \times 10^{-3}\;/°\text{C}$', '$0.4\;/°\text{C}$', '$4 \times 10^{-2}\;/°\text{C}$', '$4 \times 10^{-4}\;/°\text{C}$', 'option1', '$R_T = R_0(1 + \alpha T)$. $14 = 10(1 + 100\alpha)$. $\alpha = 0.4/100 = 4 \times 10^{-3}\;/°\text{C}$.', 'p_power_resistivity', 2, 'JEE Mains Prep', 'approved'),
('Two resistors of $6\;\Omega$ and $3\;\Omega$ are connected in parallel across a $6\;\text{V}$ battery. The total power dissipated is', '$12\;\text{W}$', '$6\;\text{W}$', '$18\;\text{W}$', '$9\;\text{W}$', 'option3', '$R_{eq} = 6 \times 3/(6+3) = 2\;\Omega$. $P = V^2/R = 36/2 = 18\;\text{W}$.', 'p_power_resistivity', 2, 'JEE Mains Prep', 'approved'),
('A wire of resistivity $\rho$, length $L$, and cross-sectional area $A$ has resistance $R$. Another wire of the same material with length $2L$ and area $2A$ has resistance', '$R/2$', '$2R$', '$R$', '$4R$', 'option3', '$R'' = \rho(2L)/(2A) = \rho L/A = R$.', 'p_power_resistivity', 2, 'JEE Mains Prep', 'approved'),
('For semiconductors, resistivity with increasing temperature', 'Decreases', 'Increases', 'Remains constant', 'Becomes infinite', 'option1', 'In semiconductors, higher temperature generates more charge carriers, decreasing resistivity.', 'p_power_resistivity', 2, 'JEE Mains Prep', 'approved'),
('A heater coil of resistance $R$ is cut into two equal halves and connected in parallel. The ratio of new power to original power (same voltage) is', '$2:1$', '$4:1$', '$1:2$', '$1:4$', 'option2', 'Each half has $R/2$. In parallel: $R_{eq} = (R/2)/2 = R/4$. $P'' = V^2/(R/4) = 4V^2/R = 4P$.', 'p_power_resistivity', 2, 'JEE Mains Prep', 'approved'),
('An electric kettle has two coils. When one is used, water boils in $t_1$ minutes; with the other, in $t_2$ minutes. When both are used in parallel, the time is', '$t_1 t_2/(t_1 + t_2)$', '$t_1 + t_2$', '$(t_1 + t_2)/2$', '$\sqrt{t_1 t_2}$', 'option1', 'Heat needed $H = V^2 t/R$. $R_1 = V^2 t_1/H$, $R_2 = V^2 t_2/H$. In parallel: $1/R_p = 1/R_1 + 1/R_2 = H/(V^2)(1/t_1 + 1/t_2)$. Time $t = R_p H/V^2 = t_1 t_2/(t_1 + t_2)$.', 'p_power_resistivity', 3, 'JEE Mains Prep', 'approved'),
('Three identical resistors, each rated $P$ watts at voltage $V$, are connected in series across a $V$ volt supply. The total power consumed is', '$P$', '$3P$', '$P/3$', '$P/9$', 'option3', 'Each resistor has $R = V^2/P$. Total resistance $= 3R$. Current $I = V/(3R)$. Total power $= I^2 \times 3R = V^2/(3R) = P/3$.', 'p_power_resistivity', 3, 'JEE Mains Prep', 'approved'),
('A wire of resistance $R$ at temperature $T_1$ has resistance $2R$ at temperature $T_2$. If the temperature coefficient is $\alpha$, then $T_2 - T_1$ equals', '$R/\alpha$', '$2/\alpha$', '$\alpha$', '$1/\alpha$', 'option4', '$2R = R(1 + \alpha(T_2 - T_1))$. $1 = \alpha(T_2 - T_1)$. $T_2 - T_1 = 1/\alpha$.', 'p_power_resistivity', 3, 'JEE Mains Prep', 'approved'),
('A $100\;\text{W}$, $200\;\text{V}$ bulb and a $200\;\text{W}$, $200\;\text{V}$ bulb are connected in series to a $400\;\text{V}$ supply. The power dissipated by the $100\;\text{W}$ bulb is approximately', '$178\;\text{W}$', '$100\;\text{W}$', '$200\;\text{W}$', '$89\;\text{W}$', 'option1', '$R_1 = 200^2/100 = 400\;\Omega$, $R_2 = 200^2/200 = 200\;\Omega$. $I = 400/600 = 2/3\;\text{A}$. $P_1 = I^2 R_1 = (4/9)(400) = 1600/9 \approx 178\;\text{W}$.', 'p_power_resistivity', 3, 'JEE Mains Prep', 'approved'),
('A nichrome wire of resistivity $1.1 \times 10^{-6}\;\Omega\cdot\text{m}$ has length $2\;\text{m}$ and cross-sectional area $0.1\;\text{mm}^2$. Its resistance is', '$22\;\Omega$', '$11\;\Omega$', '$2.2\;\Omega$', '$220\;\Omega$', 'option1', '$R = \rho L/A = 1.1 \times 10^{-6} \times 2/(0.1 \times 10^{-6}) = 2.2 \times 10^{-6}/(10^{-7}) = 22\;\Omega$.', 'p_power_resistivity', 3, 'JEE Mains Prep', 'approved'),
('Two heater coils of power $P_1$ and $P_2$ are connected in parallel to a voltage source. The total power is', '$\sqrt{P_1 P_2}$', '$P_1 P_2/(P_1 + P_2)$', '$(P_1 + P_2)/2$', '$P_1 + P_2$', 'option4', 'In parallel, voltage is the same. $P = V^2/R$. $P_{total} = V^2/R_1 + V^2/R_2 = P_1 + P_2$.', 'p_power_resistivity', 3, 'JEE Mains Prep', 'approved'),
('The maximum power that can be delivered to an external resistance $R$ by a battery of emf $\varepsilon$ and internal resistance $r$ occurs when', '$R = 2r$', '$R = r$', '$R = 0$', '$R \to \infty$', 'option2', '$P = I^2 R = \varepsilon^2 R/(R+r)^2$. $dP/dR = 0$ gives $R = r$ (maximum power transfer theorem).', 'p_power_resistivity', 3, 'JEE Mains Prep', 'approved'),

-- ============================================================
-- p_emf_internal_resistance (7 easy, 7 medium, 7 hard = 21)
-- ============================================================
('The emf of a cell is defined as', 'The current it can supply', 'The potential difference across its terminals when no current flows', 'The resistance of the cell', 'The power output of the cell', 'option2', 'EMF $\varepsilon$ is the open-circuit voltage, i.e., the terminal voltage when $I = 0$.', 'p_emf_internal_resistance', 1, 'JEE Mains Prep', 'approved'),
('The terminal voltage of a cell with emf $\varepsilon$ and internal resistance $r$ when supplying current $I$ is', '$Ir$', '$\varepsilon + Ir$', '$\varepsilon/I$', '$\varepsilon - Ir$', 'option4', '$V = \varepsilon - Ir$ (voltage drop across internal resistance reduces terminal voltage).', 'p_emf_internal_resistance', 1, 'JEE Mains Prep', 'approved'),
('When a cell is being charged, the terminal voltage is', 'Equal to the emf', 'Less than the emf', 'Greater than the emf', 'Zero', 'option3', 'During charging, current flows into the cell: $V = \varepsilon + Ir > \varepsilon$.', 'p_emf_internal_resistance', 1, 'JEE Mains Prep', 'approved'),
('Two cells of emf $\varepsilon_1$ and $\varepsilon_2$ in series (same polarity) give a total emf of', '$\varepsilon_1/\varepsilon_2$', '$\varepsilon_1 - \varepsilon_2$', '$\varepsilon_1 \varepsilon_2$', '$\varepsilon_1 + \varepsilon_2$', 'option4', 'In series (aiding): total emf $= \varepsilon_1 + \varepsilon_2$, total internal resistance $= r_1 + r_2$.', 'p_emf_internal_resistance', 1, 'JEE Mains Prep', 'approved'),
('The internal resistance of an ideal cell is', 'Depends on the external circuit', 'Infinite', '$1\;\Omega$', 'Zero', 'option4', 'An ideal cell has zero internal resistance, so terminal voltage always equals emf.', 'p_emf_internal_resistance', 1, 'JEE Mains Prep', 'approved'),
('A cell of emf $2\;\text{V}$ and internal resistance $1\;\Omega$ is connected to a $3\;\Omega$ external resistance. The current is', '$1\;\text{A}$', '$2\;\text{A}$', '$0.67\;\text{A}$', '$0.5\;\text{A}$', 'option4', '$I = \varepsilon/(R + r) = 2/(3 + 1) = 0.5\;\text{A}$.', 'p_emf_internal_resistance', 1, 'JEE Mains Prep', 'approved'),
('Two identical cells each of emf $\varepsilon$ and internal resistance $r$ connected in parallel supply current to an external resistance $R$. The current through $R$ is', '$2\varepsilon/(R + r)$', '$\varepsilon/(R + r/2)$', '$\varepsilon/(R + 2r)$', '$2\varepsilon/(R + 2r)$', 'option2', 'Two identical cells in parallel: equivalent emf $= \varepsilon$, equivalent internal resistance $= r/2$. $I = \varepsilon/(R + r/2)$.', 'p_emf_internal_resistance', 1, 'JEE Mains Prep', 'approved'),
('A cell of emf $1.5\;\text{V}$ and internal resistance $0.5\;\Omega$ is connected to a $2.5\;\Omega$ resistor. The terminal voltage is', '$1.5\;\text{V}$', '$1.25\;\text{V}$', '$1.0\;\text{V}$', '$0.75\;\text{V}$', 'option2', '$I = 1.5/(2.5 + 0.5) = 0.5\;\text{A}$. $V = \varepsilon - Ir = 1.5 - 0.5 \times 0.5 = 1.25\;\text{V}$.', 'p_emf_internal_resistance', 2, 'JEE Mains Prep', 'approved'),
('A cell of emf $\varepsilon$ and internal resistance $r$ is short-circuited. The maximum current is', '$\varepsilon/r$', '$\varepsilon r$', 'Infinite', 'Zero', 'option1', 'Short circuit: $R = 0$. $I_{max} = \varepsilon/r$.', 'p_emf_internal_resistance', 2, 'JEE Mains Prep', 'approved'),
('$n$ identical cells each of emf $\varepsilon$ and internal resistance $r$ are connected in series to an external resistance $R$. The current is', '$\varepsilon/(R + nr)$', '$n\varepsilon/(R + nr)$', '$n\varepsilon/(R + r)$', '$n\varepsilon/R$', 'option2', 'Series: total emf $= n\varepsilon$, total internal resistance $= nr$. $I = n\varepsilon/(R + nr)$.', 'p_emf_internal_resistance', 2, 'JEE Mains Prep', 'approved'),
('A cell of emf $2\;\text{V}$ drives a current of $0.4\;\text{A}$ through an external resistance of $4\;\Omega$. The internal resistance is', '$1\;\Omega$', '$0.5\;\Omega$', '$2\;\Omega$', '$0.4\;\Omega$', 'option1', '$\varepsilon = I(R + r)$. $2 = 0.4(4 + r)$. $5 = 4 + r$. $r = 1\;\Omega$.', 'p_emf_internal_resistance', 2, 'JEE Mains Prep', 'approved'),
('Two cells of emf $2\;\text{V}$ ($r_1 = 1\;\Omega$) and $4\;\text{V}$ ($r_2 = 2\;\Omega$) are connected in series opposing. The current through a $3\;\Omega$ external resistance is', '$2\;\text{A}$', '$1\;\text{A}$', '$2/3\;\text{A}$', '$1/3\;\text{A}$', 'option4', 'Net emf $= 4 - 2 = 2\;\text{V}$. Total resistance $= 3 + 1 + 2 = 6\;\Omega$. $I = 2/6 = 1/3\;\text{A}$.', 'p_emf_internal_resistance', 2, 'JEE Mains Prep', 'approved'),
('The efficiency of a cell ($\varepsilon$, $r$) connected to external resistance $R$ is', '$R/r$', '$r/(R + r)$', '$\varepsilon/(R + r)$', '$R/(R + r)$', 'option4', 'Efficiency $= $ useful power / total power $= I^2 R/(I^2(R+r)) = R/(R+r)$.', 'p_emf_internal_resistance', 2, 'JEE Mains Prep', 'approved'),
('A potentiometer wire of length $1\;\text{m}$ has a potential drop of $2\;\text{V}$. The emf of a cell balanced at $60\;\text{cm}$ is', '$3.33\;\text{V}$', '$0.6\;\text{V}$', '$2\;\text{V}$', '$1.2\;\text{V}$', 'option4', 'Potential gradient $= 2/1 = 2\;\text{V/m}$. $\varepsilon = 2 \times 0.6 = 1.2\;\text{V}$.', 'p_emf_internal_resistance', 2, 'JEE Mains Prep', 'approved'),
('For maximum current from $n$ identical cells ($\varepsilon$, $r$), they should be connected in series when', '$R = nr$', '$R \ll r$', '$R = r$', '$R \gg r$', 'option4', 'Series gives $I = n\varepsilon/(R + nr)$. Parallel gives $I = \varepsilon/(R + r/n)$. Series is better when $R \gg r$ (external resistance dominates).', 'p_emf_internal_resistance', 3, 'JEE Mains Prep', 'approved'),
('$m$ rows of $n$ cells each (emf $\varepsilon$, internal resistance $r$) are connected in parallel, with each row being a series combination. The current through external resistance $R$ is', '$mn\varepsilon/(mR + nr)$', '$n\varepsilon/(R + nr/m)$', '$m\varepsilon/(R + mr/n)$', '$n\varepsilon/(mR + r)$', 'option2', 'Each row: emf $= n\varepsilon$, resistance $= nr$. $m$ rows in parallel: equivalent emf $= n\varepsilon$, equivalent internal resistance $= nr/m$. $I = n\varepsilon/(R + nr/m)$.', 'p_emf_internal_resistance', 3, 'JEE Mains Prep', 'approved'),
('Two cells of emf $\varepsilon_1 = 6\;\text{V}$ ($r_1 = 2\;\Omega$) and $\varepsilon_2 = 4\;\text{V}$ ($r_2 = 8\;\Omega$) are connected in parallel across an external resistance. The equivalent emf is', '$10\;\text{V}$', '$5\;\text{V}$', '$5.6\;\text{V}$', '$4.8\;\text{V}$', 'option3', 'For unequal cells in parallel: $\varepsilon_{eq} = (\varepsilon_1/r_1 + \varepsilon_2/r_2)/(1/r_1 + 1/r_2) = (6/2 + 4/8)/(1/2 + 1/8) = (3 + 0.5)/(0.5 + 0.125) = 3.5/0.625 = 5.6\;\text{V}$.', 'p_emf_internal_resistance', 3, 'JEE Mains Prep', 'approved'),
('A battery of emf $10\;\text{V}$ and internal resistance $3\;\Omega$ is connected to a variable resistor. The maximum power delivered to the resistor is', '$25\;\text{W}$', '$100/3\;\text{W}$', '$10\;\text{W}$', '$25/3\;\text{W}$', 'option4', 'Maximum power at $R = r = 3\;\Omega$. $I = 10/6 = 5/3\;\text{A}$. $P = I^2 R = (25/9)(3) = 25/3\;\text{W}$.', 'p_emf_internal_resistance', 3, 'JEE Mains Prep', 'approved'),
('A cell of emf $\varepsilon$ and internal resistance $r$ is connected to two external resistances $R_1$ and $R_2$ in parallel. The terminal voltage is', '$\varepsilon(R_1 + R_2)/(R_1 R_2 + r)$', '$\varepsilon/(R_1 + R_2 + r)$', '$\varepsilon R_1 R_2/(R_1 R_2 + r(R_1 + R_2))$', '$\varepsilon R_1/(R_1 + R_2 + r)$', 'option3', 'External resistance $R_p = R_1 R_2/(R_1 + R_2)$. $V = \varepsilon R_p/(R_p + r) = \varepsilon R_1 R_2/(R_1 R_2 + r(R_1 + R_2))$.', 'p_emf_internal_resistance', 3, 'JEE Mains Prep', 'approved'),
('In a mixed grouping of $mn$ cells to get maximum current through $R$, the condition is', '$R = mnr$', '$R = mr/n$', '$R = r$', '$R = nr/m$ (internal resistance of combination equals $R$)', 'option4', 'For $n$ cells in series per row and $m$ rows in parallel: internal resistance $= nr/m$. Maximum current when $R = nr/m$.', 'p_emf_internal_resistance', 3, 'JEE Mains Prep', 'approved'),
('A potentiometer is used to compare emfs of two cells. Balance lengths are $l_1 = 75\;\text{cm}$ and $l_2 = 50\;\text{cm}$. The ratio $\varepsilon_1/\varepsilon_2$ is', '$5/3$', '$2/3$', '$3/2$', '$3/5$', 'option3', '$\varepsilon_1/\varepsilon_2 = l_1/l_2 = 75/50 = 3/2$.', 'p_emf_internal_resistance', 3, 'JEE Mains Prep', 'approved'),

-- ============================================================
-- p_kirchhoff_bridges (7 easy, 7 medium, 7 hard = 21)
-- ============================================================
('Kirchhoff''s junction rule (KCL) states that', 'The sum of voltages in a loop is zero', 'The algebraic sum of currents at a junction is zero', 'Current is always constant', 'Resistance at a junction is zero', 'option2', 'KCL: $\sum I_{in} = \sum I_{out}$ at any junction (conservation of charge).', 'p_kirchhoff_bridges', 1, 'JEE Mains Prep', 'approved'),
('Kirchhoff''s loop rule (KVL) is based on conservation of', 'Mass', 'Charge', 'Momentum', 'Energy', 'option4', 'KVL: the algebraic sum of potential differences around any closed loop is zero (energy conservation).', 'p_kirchhoff_bridges', 1, 'JEE Mains Prep', 'approved'),
('In a Wheatstone bridge, the bridge is balanced when', '$P/Q = R/S$', '$P/Q = S/R$', '$PR = QS$', 'Both option1 and option3', 'option4', 'Balance condition: $P/Q = R/S$, equivalently $PS = QR$ (or $PR = QS$ depending on labelling). Standard form: $P/Q = R/S$.', 'p_kirchhoff_bridges', 1, 'JEE Mains Prep', 'approved'),
('When a Wheatstone bridge is balanced, the current through the galvanometer is', 'Zero', 'Maximum', 'Equal to the battery current', 'Infinite', 'option1', 'At balance, the potential difference across the galvanometer is zero, so no current flows through it.', 'p_kirchhoff_bridges', 1, 'JEE Mains Prep', 'approved'),
('A metre bridge works on the principle of', 'Wheatstone bridge', 'Potentiometer', 'Ohm''s law only', 'Kirchhoff''s junction rule only', 'option1', 'A metre bridge is a practical form of the Wheatstone bridge using a uniform wire.', 'p_kirchhoff_bridges', 1, 'JEE Mains Prep', 'approved'),
('In a metre bridge, if the balance point is at $40\;\text{cm}$ from the left end and the known resistance is $6\;\Omega$, the unknown resistance is', '$9\;\Omega$', '$4\;\Omega$', '$6\;\Omega$', '$2.4\;\Omega$', 'option2', '$X/6 = 40/60 = 2/3$. $X = 4\;\Omega$.', 'p_kirchhoff_bridges', 1, 'JEE Mains Prep', 'approved'),
('The sensitivity of a Wheatstone bridge is maximum when', 'One resistance is much larger than others', 'All four resistances are equal', 'The galvanometer resistance is infinite', 'The battery has zero internal resistance', 'option2', 'Maximum sensitivity occurs when $P = Q = R = S$ (all arms equal).', 'p_kirchhoff_bridges', 1, 'JEE Mains Prep', 'approved'),
('In a Wheatstone bridge with $P = 100\;\Omega$, $Q = 200\;\Omega$, $R = 40\;\Omega$, the value of $S$ for balance is', '$80\;\Omega$', '$20\;\Omega$', '$40\;\Omega$', '$100\;\Omega$', 'option1', '$P/Q = R/S$. $100/200 = 40/S$. $S = 80\;\Omega$.', 'p_kirchhoff_bridges', 2, 'JEE Mains Prep', 'approved'),
('In a circuit with two loops sharing a common branch, the minimum number of equations needed to solve for all currents using Kirchhoff''s laws is', '$3$ (2 loop equations + 1 junction equation)', '$2$', '$4$', '$1$', 'option1', 'With 3 unknown currents: 1 junction equation + 2 loop equations give 3 independent equations.', 'p_kirchhoff_bridges', 2, 'JEE Mains Prep', 'approved'),
('In a metre bridge, the balance point is at $l = 33.3\;\text{cm}$ with a $10\;\Omega$ standard resistance. The unknown resistance is', '$5\;\Omega$', '$10\;\Omega$', '$20\;\Omega$', '$15\;\Omega$', 'option1', '$X/S = l/(100-l) = 33.3/66.7 = 1/2$. $X = S/2 = 10/2 = 5\;\Omega$.', 'p_kirchhoff_bridges', 2, 'JEE Mains Prep', 'approved'),
('A Wheatstone bridge has $P = 10\;\Omega$, $Q = 30\;\Omega$, $R = 15\;\Omega$, $S = 45\;\Omega$. The bridge is', 'Unbalanced with current from B to D', 'Balanced', 'Unbalanced with current from D to B', 'Cannot be determined', 'option2', '$P/Q = 10/30 = 1/3$. $R/S = 15/45 = 1/3$. Since $P/Q = R/S$, the bridge is balanced.', 'p_kirchhoff_bridges', 2, 'JEE Mains Prep', 'approved'),
('In a metre bridge, interchanging the unknown and standard resistances', 'Makes the bridge unbalanced', 'Increases sensitivity', 'Has no effect', 'Reduces end-correction errors', 'option4', 'Interchanging and averaging the two balance lengths eliminates end-correction errors.', 'p_kirchhoff_bridges', 2, 'JEE Mains Prep', 'approved'),
('At a junction in a circuit, three wires carry currents $2\;\text{A}$ (in), $3\;\text{A}$ (in), and $I$ (out). By KCL, $I$ equals', '$5\;\text{A}$', '$1\;\text{A}$', '$6\;\text{A}$', '$2.5\;\text{A}$', 'option1', 'KCL: $\sum I_{in} = \sum I_{out}$. $2 + 3 = I$. $I = 5\;\text{A}$.', 'p_kirchhoff_bridges', 2, 'JEE Mains Prep', 'approved'),
('Two batteries of emf $6\;\text{V}$ ($r_1 = 1\;\Omega$) and $12\;\text{V}$ ($r_2 = 2\;\Omega$) are connected in parallel with positive terminals together, across a $4\;\Omega$ resistor. The current through the $4\;\Omega$ resistor is', '$2\;\text{A}$', '$3\;\text{A}$', '$18/7\;\text{A}$', '$12/7\;\text{A}$', 'option4', 'Using KVL: Let $I = I_1 + I_2$ through $4\;\Omega$. Loop 1: $6 = I_1 + 4I$. Loop 2: $12 = 2I_2 + 4I$. So $I_1 = 6 - 4I$, $I_2 = 6 - 2I$. $I = 12 - 6I$, giving $I = 12/7\;\text{A}$.', 'p_kirchhoff_bridges', 2, 'JEE Mains Prep', 'approved'),
('In a Wheatstone bridge, $P = 100\;\Omega$, $Q = 1000\;\Omega$, $R = 40\;\Omega$, $S = 400\;\Omega$. If the positions of the galvanometer and battery are interchanged, the bridge', 'Cannot be determined', 'Becomes unbalanced', 'Shows maximum deflection', 'Remains balanced', 'option4', 'The balance condition $PS = QR$ ($100 \times 400 = 1000 \times 40 = 40000$) is independent of the positions of the galvanometer and battery (reciprocity theorem).', 'p_kirchhoff_bridges', 3, 'JEE Mains Prep', 'approved'),
('In a circuit, three resistors $R_1 = 2\;\Omega$, $R_2 = 4\;\Omega$, $R_3 = 6\;\Omega$ are connected in a delta. The equivalent star resistances are', '$4/3\;\Omega$, $8/3\;\Omega$, $4\;\Omega$', '$1\;\Omega$, $2\;\Omega$, $3\;\Omega$', '$2\;\Omega$, $4\;\Omega$, $6\;\Omega$', '$2/3\;\Omega$, $1\;\Omega$, $2\;\Omega$', 'option4', 'Sum $= 2+4+6 = 12$. $R_a = R_1 R_2/12 = 8/12 = 2/3\;\Omega$. $R_b = R_1 R_3/12 = 12/12 = 1\;\Omega$. $R_c = R_2 R_3/12 = 24/12 = 2\;\Omega$.', 'p_kirchhoff_bridges', 3, 'JEE Mains Prep', 'approved'),
('A metre bridge has a $10\;\Omega$ resistance in the left gap. The balance point is at $40\;\text{cm}$. The unknown resistance in the right gap is', '$15\;\Omega$', '$6.67\;\Omega$', '$25\;\Omega$', '$4\;\Omega$', 'option1', '$R/S = l/(100-l)$. $10/S = 40/60$. $S = 10 \times 60/40 = 15\;\Omega$.', 'p_kirchhoff_bridges', 3, 'JEE Mains Prep', 'approved'),
('In a circuit with two cells ($\varepsilon_1 = 10\;\text{V}$, $r_1 = 1\;\Omega$ and $\varepsilon_2 = 5\;\text{V}$, $r_2 = 2\;\Omega$) connected in a loop with a $12\;\Omega$ resistor, the current (cells opposing) is', '$15\;\text{A}$', '$1\;\text{A}$', '$5/15\;\text{A}$', '$1/3\;\text{A}$', 'option4', 'Net emf $= 10 - 5 = 5\;\text{V}$. Total resistance $= 12 + 1 + 2 = 15\;\Omega$. $I = 5/15 = 1/3\;\text{A}$.', 'p_kirchhoff_bridges', 3, 'JEE Mains Prep', 'approved'),
('In a Wheatstone bridge with $P = 2\;\Omega$, $Q = 3\;\Omega$, $R = 4\;\Omega$, $S = 6\;\Omega$, connected to a $12\;\text{V}$ battery, the potential difference across the galvanometer terminals (B and D) is', '$2\;\text{V}$', 'Zero', '$1.2\;\text{V}$', '$0.6\;\text{V}$', 'option2', '$P/Q = 2/3$ and $R/S = 4/6 = 2/3$. Since $P/Q = R/S$, the bridge is balanced and $V_{BD} = 0$.', 'p_kirchhoff_bridges', 3, 'JEE Mains Prep', 'approved'),
('A Kelvin double bridge is used to measure', 'Very high resistances', 'Very low resistances (below $1\;\Omega$)', 'Capacitance', 'Inductance', 'option2', 'The Kelvin double bridge eliminates lead and contact resistance errors, making it suitable for measuring very low resistances.', 'p_kirchhoff_bridges', 3, 'JEE Mains Prep', 'approved'),
('In a circuit with three meshes, the number of independent KVL equations needed is', '$3$', '$2$', '$1$', '$4$', 'option1', 'The number of independent loop equations equals the number of independent meshes, which is 3.', 'p_kirchhoff_bridges', 3, 'JEE Mains Prep', 'approved'),

-- ============================================================
-- p_biot_savart (7 easy, 7 medium, 7 hard = 21)
-- ============================================================
('The Biot-Savart law gives the magnetic field due to', 'A magnetic monopole', 'A stationary charge', 'A small current element', 'A changing electric field', 'option3', 'Biot-Savart law: $d\vec{B} = \frac{\mu_0}{4\pi}\frac{I\,d\vec{l} \times \hat{r}}{r^2}$ gives the field due to a current element $Id\vec{l}$.', 'p_biot_savart', 1, 'JEE Mains Prep', 'approved'),
('The magnetic field at the centre of a circular loop of radius $R$ carrying current $I$ is', '$\mu_0 I R/2$', '$\mu_0 I/R$', '$\mu_0 I/(4\pi R)$', '$\mu_0 I/(2R)$', 'option4', '$B = \mu_0 I/(2R)$ at the centre of a circular loop.', 'p_biot_savart', 1, 'JEE Mains Prep', 'approved'),
('The direction of the magnetic field due to a current-carrying wire is given by', 'Faraday''s law', 'Left-hand rule', 'Lenz''s law', 'Right-hand thumb rule', 'option4', 'Point the thumb along the current; the curled fingers give the direction of $\vec{B}$.', 'p_biot_savart', 1, 'JEE Mains Prep', 'approved'),
('The magnetic field due to a long straight wire at distance $r$ is', '$\mu_0 I r/2$', '$\mu_0 I/(4\pi r)$', '$\mu_0 I/(2\pi r)$', '$\mu_0 I/(2r)$', 'option3', '$B = \mu_0 I/(2\pi r)$ for an infinitely long straight wire.', 'p_biot_savart', 1, 'JEE Mains Prep', 'approved'),
('The SI unit of magnetic field is', 'Weber (Wb)', 'Gauss (G)', 'Tesla (T)', 'Henry (H)', 'option3', 'Magnetic field is measured in tesla: $1\;\text{T} = 1\;\text{Wb/m}^2 = 1\;\text{kg/(A}\cdot\text{s}^2)$.', 'p_biot_savart', 1, 'JEE Mains Prep', 'approved'),
('The magnetic field at the centre of a semicircular wire of radius $R$ carrying current $I$ is', '$\mu_0 I/(4R)$', '$\mu_0 I/(2R)$', '$\mu_0 I/(8R)$', '$\mu_0 I/(\pi R)$', 'option1', 'A semicircle is half a full loop. $B = \frac{1}{2} \times \mu_0 I/(2R) = \mu_0 I/(4R)$.', 'p_biot_savart', 1, 'JEE Mains Prep', 'approved'),
('The magnetic field lines around a long straight current-carrying wire are', 'Concentric circles centred on the wire', 'Straight lines parallel to the wire', 'Radial lines from the wire', 'Ellipses', 'option1', 'The field lines form concentric circles in planes perpendicular to the wire.', 'p_biot_savart', 1, 'JEE Mains Prep', 'approved'),
('The magnetic field on the axis of a circular loop of radius $R$ at distance $x$ from the centre is', '$\mu_0 IR/(2x^2)$', '$\mu_0 I/(2R)$', '$\mu_0 IR^2/(2(R^2 + x^2)^{3/2})$', '$\mu_0 Ix/(2R^2)$', 'option3', '$B = \mu_0 IR^2/(2(R^2 + x^2)^{3/2})$. At $x = 0$, this reduces to $\mu_0 I/(2R)$.', 'p_biot_savart', 2, 'JEE Mains Prep', 'approved'),
('A circular coil of $N$ turns, radius $R$, carrying current $I$ has magnetic field at its centre', '$N\mu_0 I/(2R)$', '$\mu_0 I/(2NR)$', '$\mu_0 NI/R$', '$\mu_0 I/(2R)$', 'option1', 'Each turn contributes $\mu_0 I/(2R)$. Total $B = N\mu_0 I/(2R)$.', 'p_biot_savart', 2, 'JEE Mains Prep', 'approved'),
('The magnetic field at the centre of a circular arc of radius $R$ subtending angle $\theta$ at the centre, carrying current $I$, is', '$\mu_0 I\theta/(2\pi R)$', '$\mu_0 I/(2R)$', '$\mu_0 I\theta/(4\pi R)$', '$\mu_0 I/(4R)$', 'option3', 'Arc of angle $\theta$: $B = (\theta/2\pi) \times \mu_0 I/(2R) = \mu_0 I\theta/(4\pi R)$.', 'p_biot_savart', 2, 'JEE Mains Prep', 'approved'),
('Two parallel wires $10\;\text{cm}$ apart carry currents of $5\;\text{A}$ each in the same direction. The magnetic field midway between them is', 'Zero', '$2 \times 10^{-5}\;\text{T}$', '$4 \times 10^{-5}\;\text{T}$', '$10^{-5}\;\text{T}$', 'option1', 'At the midpoint, the fields from the two wires are equal in magnitude but opposite in direction (by right-hand rule for same-direction currents). They cancel: $B = 0$.', 'p_biot_savart', 2, 'JEE Mains Prep', 'approved'),
('The magnetic field at a distance $d$ from a long straight wire carrying current $I$ is $B$. At distance $2d$, the field is', '$2B$', '$B/4$', '$B/2$', '$B$', 'option3', '$B \propto 1/r$. At $2d$: $B'' = B/2$.', 'p_biot_savart', 2, 'JEE Mains Prep', 'approved'),
('A wire bent into a regular hexagon of side $a$ carries current $I$. The magnetic field at the centre is', '$6\mu_0 I/(4\pi a)$', '$\mu_0 I/(2a)$', '$\sqrt{3}\mu_0 I/(\pi a)$', '$3\mu_0 I/(\pi a)$', 'option3', 'Each side subtends $60°$ at the centre. Distance from centre to side $= a\sqrt{3}/2$. Field due to one side: $B_1 = \frac{\mu_0 I}{4\pi d}(2\sin 30°) = \frac{\mu_0 I}{4\pi(a\sqrt{3}/2)} = \frac{\mu_0 I}{2\pi a\sqrt{3}}$. Total: $6B_1 = \frac{6\mu_0 I}{2\pi a\sqrt{3}} = \frac{3\mu_0 I}{\pi a\sqrt{3}} = \frac{\sqrt{3}\mu_0 I}{\pi a}$.', 'p_biot_savart', 2, 'JEE Mains Prep', 'approved'),
('A wire is bent into a figure-eight (two tangent circles of radius $R$) carrying current $I$. The magnetic field at the common point is', '$\mu_0 I/(2R)$', '$\mu_0 I/R$', 'Zero', '$2\mu_0 I/R$', 'option3', 'Current flows clockwise in one loop and counterclockwise in the other. The fields at the common point are equal and opposite, so $B = 0$.', 'p_biot_savart', 2, 'JEE Mains Prep', 'approved'),
('A long straight wire carries current $I$. The magnetic field at a point $P$ due to a finite segment of the wire subtending angles $\alpha$ and $\beta$ at $P$ is', '$\frac{\mu_0 I}{2\pi d}$', '$\frac{\mu_0 I}{4\pi d}(\sin\alpha + \sin\beta)$', '$\frac{\mu_0 I}{4\pi d}(\cos\alpha + \cos\beta)$', '$\frac{\mu_0 I}{4\pi d}(\sin\alpha - \sin\beta)$', 'option2', 'For a finite wire at perpendicular distance $d$: $B = \frac{\mu_0 I}{4\pi d}(\sin\alpha + \sin\beta)$ where $\alpha$ and $\beta$ are the angles subtended by the ends.', 'p_biot_savart', 3, 'JEE Mains Prep', 'approved'),
('Two concentric coplanar circular loops of radii $R$ and $2R$ carry equal currents $I$ in opposite directions. The magnetic field at the centre is', '$\mu_0 I/(2R)$', '$3\mu_0 I/(4R)$', 'Zero', '$\mu_0 I/(4R)$', 'option4', '$B_1 = \mu_0 I/(2R)$ (say inward). $B_2 = \mu_0 I/(2 \times 2R) = \mu_0 I/(4R)$ (outward). Net $= \mu_0 I/(2R) - \mu_0 I/(4R) = \mu_0 I/(4R)$.', 'p_biot_savart', 3, 'JEE Mains Prep', 'approved'),
('A circular loop of radius $R$ carries current $I$. The ratio of the magnetic field at a point on the axis at distance $R$ from the centre to the field at the centre is', '$1/(2\sqrt{2})$', '$1/2$', '$\sqrt{2}$', '$1/\sqrt{2}$', 'option1', 'At distance $x = R$: $B = \mu_0 IR^2/(2(R^2+R^2)^{3/2}) = \mu_0 IR^2/(2(2R^2)^{3/2}) = \mu_0 I/(2R \times 2\sqrt{2}) = B_0/(2\sqrt{2})$.', 'p_biot_savart', 3, 'JEE Mains Prep', 'approved'),
('A wire carrying current $I$ is bent into a shape consisting of a semicircle of radius $R$ connected to two long straight segments. The magnetic field at the centre of the semicircle is', '$\mu_0 I(1/4R + 1/(\pi R))$', '$\mu_0 I/(4R)$', '$\mu_0 I/(2R)$', '$\mu_0 I(\pi + 2)/(4\pi R)$', 'option4', 'Semicircle contributes $\mu_0 I/(4R)$. Each semi-infinite wire at distance $R$ contributes $\mu_0 I/(4\pi R)$. Total $= \mu_0 I/(4R) + 2 \times \mu_0 I/(4\pi R) = \mu_0 I(\pi + 2)/(4\pi R)$.', 'p_biot_savart', 3, 'JEE Mains Prep', 'approved'),
('Two identical circular coils of radius $R$ are placed coaxially at distance $R$ apart (Helmholtz coils). Each carries current $I$ in the same direction. The field at the midpoint is', '$\mu_0 I/(2R)$', '$\mu_0 I/R$', '$\frac{8\mu_0 I}{5\sqrt{5}R}$', '$\frac{4\mu_0 I}{5\sqrt{5}R}$', 'option3', 'At midpoint ($x = R/2$ from each coil): $B = 2 \times \frac{\mu_0 IR^2}{2(R^2 + R^2/4)^{3/2}} = \frac{\mu_0 IR^2}{(5R^2/4)^{3/2}} = \frac{\mu_0 IR^2}{(5/4)^{3/2}R^3} = \frac{\mu_0 I}{R} \times \frac{(4/5)^{3/2}}{1} = \frac{8\mu_0 I}{5\sqrt{5}R}$.', 'p_biot_savart', 3, 'JEE Mains Prep', 'approved'),
('A square loop of side $a$ carries current $I$. The magnetic field at the centre is', '$\mu_0 I/(2a)$', '$2\sqrt{2}\mu_0 I/(\pi a)$', '$4\mu_0 I/(\pi a)$', '$\sqrt{2}\mu_0 I/(\pi a)$', 'option2', 'Distance from centre to each side $= a/2$. Each side subtends $45°$ at each end. $B_{side} = \frac{\mu_0 I}{4\pi(a/2)}(2\sin 45°) = \frac{\mu_0 I\sqrt{2}}{2\pi a}$. Total $= 4 \times \frac{\mu_0 I\sqrt{2}}{2\pi a} = \frac{2\sqrt{2}\mu_0 I}{\pi a}$.', 'p_biot_savart', 3, 'JEE Mains Prep', 'approved'),
('The magnetic field at the centre of a circular coil of $N$ turns, radius $R$, carrying current $I$ is $B$. If the coil is unwound and rewound into a coil of $2N$ turns (same wire length), the new field at the centre is', '$2B$', '$4B$', '$B/2$', '$B$', 'option2', 'Same wire length: $N(2\pi R) = 2N(2\pi R'')$, so $R'' = R/2$. New field $= \mu_0(2N)I/(2 \times R/2) = 2\mu_0 NI/R = 4 \times \mu_0 NI/(2R) = 4B$.', 'p_biot_savart', 3, 'JEE Mains Prep', 'approved'),

-- ============================================================
-- p_ampere_law (7 easy, 7 medium, 7 hard = 21)
-- ============================================================
('Ampere''s circuital law states that', '$\oint \vec{B}\cdot d\vec{l} = 0$ always', '$\oint \vec{B}\cdot d\vec{l} = \mu_0 I_{enclosed}$', '$\vec{B} = \mu_0 I/r$', '$\nabla \times \vec{B} = 0$', 'option2', 'Ampere''s law: the line integral of $\vec{B}$ around a closed loop equals $\mu_0$ times the enclosed current.', 'p_ampere_law', 1, 'JEE Mains Prep', 'approved'),
('The magnetic field inside a long solenoid of $n$ turns per unit length carrying current $I$ is', '$\mu_0 nI$', '$\mu_0 nI/2$', '$\mu_0 I/(2\pi r)$', '$nI$', 'option1', 'By Ampere''s law: $B = \mu_0 nI$ (uniform inside, zero outside for ideal solenoid).', 'p_ampere_law', 1, 'JEE Mains Prep', 'approved'),
('The magnetic field outside an ideal solenoid is', '$\mu_0 nI$', 'Zero', '$\mu_0 nI/2$', 'Depends on distance', 'option2', 'For an ideal (infinite) solenoid, the field outside is zero by Ampere''s law.', 'p_ampere_law', 1, 'JEE Mains Prep', 'approved'),
('Ampere''s law is most useful when the magnetic field has', 'High symmetry (cylindrical, planar, or solenoidal)', 'No symmetry', 'Spherical symmetry only', 'Time-varying fields', 'option1', 'Ampere''s law is practical when symmetry allows $\vec{B}$ to be taken out of the integral.', 'p_ampere_law', 1, 'JEE Mains Prep', 'approved'),
('The magnetic field inside a toroid of $N$ total turns, mean radius $R$, carrying current $I$ is', 'Zero', '$\mu_0 NI/R$', '$\mu_0 NI$', '$\mu_0 NI/(2\pi R)$', 'option4', 'By Ampere''s law: $B(2\pi R) = \mu_0 NI$. $B = \mu_0 NI/(2\pi R)$.', 'p_ampere_law', 1, 'JEE Mains Prep', 'approved'),
('The magnetic field outside a toroid is', 'Zero', '$\mu_0 NI/(2\pi r)$', 'Same as inside', 'Non-zero and uniform', 'option1', 'Outside the toroid, the net enclosed current is zero, so $B = 0$.', 'p_ampere_law', 1, 'JEE Mains Prep', 'approved'),
('A long straight wire carries current $I$. Using Ampere''s law with a circular path of radius $r$, the field is', '$\mu_0 I r$', '$\mu_0 I/r$', '$\mu_0 I/(4\pi r)$', '$\mu_0 I/(2\pi r)$', 'option4', '$B(2\pi r) = \mu_0 I$. $B = \mu_0 I/(2\pi r)$.', 'p_ampere_law', 1, 'JEE Mains Prep', 'approved'),
('A solenoid of length $50\;\text{cm}$ has $500$ turns and carries $2\;\text{A}$. The magnetic field inside is', '$2.51 \times 10^{-3}\;\text{T}$', '$1.26 \times 10^{-3}\;\text{T}$', '$6.28 \times 10^{-3}\;\text{T}$', '$5.03 \times 10^{-3}\;\text{T}$', 'option1', '$n = 500/0.5 = 1000\;\text{turns/m}$. $B = \mu_0 nI = 4\pi \times 10^{-7} \times 1000 \times 2 = 2.51 \times 10^{-3}\;\text{T}$.', 'p_ampere_law', 2, 'JEE Mains Prep', 'approved'),
('A thick cylindrical wire of radius $R$ carries uniform current $I$. The magnetic field at distance $r < R$ from the axis is', '$\mu_0 Ir/(2\pi R^2)$', '$\mu_0 I/(2\pi r)$', '$\mu_0 I/(2\pi R)$', 'Zero', 'option1', 'Enclosed current $= I(r/R)^2$. $B(2\pi r) = \mu_0 I r^2/R^2$. $B = \mu_0 Ir/(2\pi R^2)$.', 'p_ampere_law', 2, 'JEE Mains Prep', 'approved'),
('The magnetic field inside a thick cylindrical wire varies with distance $r$ from the axis as', '$B \propto 1/r$', '$B \propto r$', '$B \propto r^2$', '$B$ is constant', 'option2', 'Inside: $B = \mu_0 Ir/(2\pi R^2) \propto r$ (linear increase from zero at the axis).', 'p_ampere_law', 2, 'JEE Mains Prep', 'approved'),
('A toroid has $1000$ turns, mean radius $20\;\text{cm}$, and carries $2\;\text{A}$. The field inside is', '$2 \times 10^{-3}\;\text{T}$', '$4 \times 10^{-3}\;\text{T}$', '$10^{-3}\;\text{T}$', '$8 \times 10^{-3}\;\text{T}$', 'option1', '$B = \mu_0 NI/(2\pi R) = 4\pi \times 10^{-7} \times 1000 \times 2/(2\pi \times 0.2) = 2 \times 10^{-3}\;\text{T}$.', 'p_ampere_law', 2, 'JEE Mains Prep', 'approved'),
('A coaxial cable has inner conductor (radius $a$, current $I$ outward) and outer conductor (radius $b$, current $I$ inward). The field at $r > b$ is', 'Zero', '$\mu_0 I/(2\pi r)$', '$\mu_0 I/(\pi r)$', '$\mu_0 2I/(2\pi r)$', 'option1', 'Net enclosed current $= I - I = 0$. By Ampere''s law: $B = 0$ for $r > b$.', 'p_ampere_law', 2, 'JEE Mains Prep', 'approved'),
('Two solenoids of the same length have $n_1$ and $n_2$ turns per unit length carrying currents $I_1$ and $I_2$. The ratio of their interior fields is', '$n_1 I_1/(n_2 I_2)$', '$n_1/n_2$', '$I_1/I_2$', '$(n_1 I_1)^2/(n_2 I_2)^2$', 'option1', '$B = \mu_0 nI$. Ratio $= n_1 I_1/(n_2 I_2)$.', 'p_ampere_law', 2, 'JEE Mains Prep', 'approved'),
('A solenoid of length $0.4\;\text{m}$ with $800$ turns carries $3\;\text{A}$. The magnetic field inside is approximately', '$6.03 \times 10^{-3}\;\text{T}$', '$3.77 \times 10^{-3}\;\text{T}$', '$1.51 \times 10^{-2}\;\text{T}$', '$7.54 \times 10^{-3}\;\text{T}$', 'option4', '$n = 800/0.4 = 2000\;\text{turns/m}$. $B = \mu_0 nI = 4\pi \times 10^{-7} \times 2000 \times 3 = 7.54 \times 10^{-3}\;\text{T}$.', 'p_ampere_law', 2, 'JEE Mains Prep', 'approved'),
('A hollow cylindrical conductor (inner radius $a$, outer radius $b$) carries current $I$ uniformly distributed. The field at $r$ ($a < r < b$) is', '$\frac{\mu_0 I}{2\pi r}\frac{r^2 - a^2}{b^2 - a^2}$', '$\mu_0 I/(2\pi r)$', '$\frac{\mu_0 I r}{2\pi b^2}$', 'Zero', 'option1', 'Enclosed current $= I \times \frac{\pi(r^2-a^2)}{\pi(b^2-a^2)}$. $B(2\pi r) = \mu_0 I(r^2-a^2)/(b^2-a^2)$. $B = \frac{\mu_0 I}{2\pi r}\frac{r^2-a^2}{b^2-a^2}$.', 'p_ampere_law', 3, 'JEE Mains Prep', 'approved'),
('An infinite conducting sheet carries surface current density $K$ (A/m). The magnetic field on each side is', '$\mu_0 K/2$', '$\mu_0 K$', '$\mu_0 K/(4\pi)$', 'Zero', 'option1', 'By Ampere''s law with a rectangular loop: $2BL = \mu_0 KL$. $B = \mu_0 K/2$ on each side, parallel to the sheet.', 'p_ampere_law', 3, 'JEE Mains Prep', 'approved'),
('A thick wire of radius $R$ carries current with density $J = J_0 r/R$. The magnetic field at $r < R$ is', '$\mu_0 J_0 r^2/(2R)$', '$\mu_0 J_0 r/(2R)$', '$\mu_0 J_0 R/3$', '$\mu_0 J_0 r^2/(3R)$', 'option4', '$I_{enc} = \int_0^r J_0(r''/R)(2\pi r'')\,dr'' = 2\pi J_0 r^3/(3R)$. $B(2\pi r) = \mu_0 \times 2\pi J_0 r^3/(3R)$. $B = \mu_0 J_0 r^2/(3R)$.', 'p_ampere_law', 3, 'JEE Mains Prep', 'approved'),
('A solenoid of $n$ turns per unit length has a core of relative permeability $\mu_r$. The field inside is', '$\mu_r \mu_0 nI$', '$\mu_0 nI/\mu_r$', '$\mu_0 nI$', '$\mu_r nI$', 'option1', 'With a magnetic core: $B = \mu_r \mu_0 nI = \mu nI$.', 'p_ampere_law', 3, 'JEE Mains Prep', 'approved'),
('The magnetic field at the surface of a thick wire of radius $R$ carrying uniform current $I$ is', '$\mu_0 I/(2\pi R)$', '$\mu_0 I/R$', '$\mu_0 I/(4\pi R)$', 'Zero', 'option1', 'At $r = R$: $B = \mu_0 I/(2\pi R)$ (same as for a thin wire at distance $R$).', 'p_ampere_law', 3, 'JEE Mains Prep', 'approved'),
('Two coaxial solenoids have the same length. The inner solenoid ($n_1$ turns/m, current $I_1$) is inside the outer ($n_2$ turns/m, current $I_2$, opposite direction). The field inside the inner solenoid is', '$\mu_0 n_2 I_2$', '$\mu_0(n_1 I_1 + n_2 I_2)$', '$\mu_0 n_1 I_1$', '$\mu_0(n_1 I_1 - n_2 I_2)$', 'option4', 'Inside the inner solenoid, both fields exist. Since currents are opposite: $B = \mu_0 n_1 I_1 - \mu_0 n_2 I_2 = \mu_0(n_1 I_1 - n_2 I_2)$.', 'p_ampere_law', 3, 'JEE Mains Prep', 'approved'),
('A long cylindrical conductor of radius $R$ has a cylindrical hole of radius $a$ (axis parallel, offset by distance $d$ from the main axis). If the conductor carries uniform current density $J$, the field inside the hole is', 'Zero', 'Uniform: $\mu_0 Jd/2$', 'Non-uniform', '$\mu_0 Ja/2$', 'option2', 'By superposition of a solid cylinder ($+J$) and a hole cylinder ($-J$): the field inside the hole is uniform with magnitude $B = \mu_0 Jd/2$, directed perpendicular to the line joining the axes.', 'p_ampere_law', 3, 'JEE Mains Prep', 'approved'),

-- ============================================================
-- p_force_moving_charge (7 easy, 7 medium, 7 hard = 21)
-- ============================================================
('The force on a charge $q$ moving with velocity $\vec{v}$ in a magnetic field $\vec{B}$ is', '$q(\vec{v} \times \vec{B})$', '$q\vec{v}\cdot\vec{B}$', '$qvB$', '$q\vec{B}/v$', 'option1', 'Lorentz force: $\vec{F} = q(\vec{v} \times \vec{B})$. The force is perpendicular to both $\vec{v}$ and $\vec{B}$.', 'p_force_moving_charge', 1, 'JEE Mains Prep', 'approved'),
('A charged particle moving parallel to a magnetic field experiences', 'Force along the field', 'Maximum force', 'No force', 'Constant deceleration', 'option3', '$F = qvB\sin\theta$. When $\vec{v} \parallel \vec{B}$, $\theta = 0$ and $F = 0$.', 'p_force_moving_charge', 1, 'JEE Mains Prep', 'approved'),
('The force on a straight conductor of length $L$ carrying current $I$ in a uniform field $B$ at angle $\theta$ is', '$BIL\cos\theta$', '$BIL\sin\theta$', '$BIL$', '$BI/L$', 'option2', '$F = BIL\sin\theta = I(\vec{L} \times \vec{B})$.', 'p_force_moving_charge', 1, 'JEE Mains Prep', 'approved'),
('A charged particle in a uniform magnetic field moves in a', 'Hyperbolic path', 'Straight line always', 'Parabolic path', 'Circular path (if $\vec{v} \perp \vec{B}$)', 'option4', 'The magnetic force provides centripetal acceleration, causing circular motion when $\vec{v} \perp \vec{B}$.', 'p_force_moving_charge', 1, 'JEE Mains Prep', 'approved'),
('The work done by a magnetic force on a moving charged particle is', 'Negative', 'Positive', 'Always zero', 'Depends on the charge', 'option3', 'Since $\vec{F} \perp \vec{v}$ always, $W = \vec{F}\cdot\vec{v}\,dt = 0$. Magnetic force does no work.', 'p_force_moving_charge', 1, 'JEE Mains Prep', 'approved'),
('The radius of the circular path of a charged particle (charge $q$, mass $m$, speed $v$) in a magnetic field $B$ is', '$qB/(mv)$', '$mv/(qB)$', '$mv^2/(qB)$', '$qBv/m$', 'option2', '$qvB = mv^2/r$. $r = mv/(qB)$.', 'p_force_moving_charge', 1, 'JEE Mains Prep', 'approved'),
('Fleming''s left-hand rule gives the direction of', 'Force on a current-carrying conductor in a magnetic field', 'Induced current', 'Magnetic field due to a current', 'Electric field', 'option1', 'Fleming''s left-hand rule: thumb = force, index = field ($B$), middle = current ($I$).', 'p_force_moving_charge', 1, 'JEE Mains Prep', 'approved'),
('A proton and an alpha particle enter a magnetic field with the same velocity. The ratio of radii of their circular paths is', '$4:1$', '$2:1$', '$1:4$', '$1:2$', 'option4', '$r = mv/(qB)$. For proton: $r_p = m_p v/(eB)$. For alpha ($m = 4m_p$, $q = 2e$): $r_\alpha = 4m_p v/(2eB) = 2m_p v/(eB) = 2r_p$. Ratio $= 1:2$.', 'p_force_moving_charge', 2, 'JEE Mains Prep', 'approved'),
('A charged particle enters a uniform magnetic field perpendicular to it with kinetic energy $K$. If the field is doubled, the radius of the circular path', 'Becomes $1/\sqrt{2}$ times', 'Doubles', 'Remains the same', 'Halves', 'option4', '$r = mv/(qB) = \sqrt{2mK}/(qB)$. If $B \to 2B$: $r \to r/2$.', 'p_force_moving_charge', 2, 'JEE Mains Prep', 'approved'),
('An electron ($e = 1.6 \times 10^{-19}\;\text{C}$, $m = 9.1 \times 10^{-31}\;\text{kg}$) moves at $10^7\;\text{m/s}$ perpendicular to a $0.1\;\text{T}$ field. The radius of its path is approximately', '$5.7 \times 10^{-4}\;\text{m}$', '$5.7 \times 10^{-2}\;\text{m}$', '$5.7 \times 10^{-6}\;\text{m}$', '$5.7\;\text{m}$', 'option1', '$r = mv/(eB) = 9.1 \times 10^{-31} \times 10^7/(1.6 \times 10^{-19} \times 0.1) = 9.1 \times 10^{-24}/(1.6 \times 10^{-20}) = 5.69 \times 10^{-4}\;\text{m}$.', 'p_force_moving_charge', 2, 'JEE Mains Prep', 'approved'),
('The time period of revolution of a charged particle in a magnetic field is', '$2\pi qB/m$', '$2\pi m/(qB)$', '$2\pi mv/(qB)$', '$mv/(2\pi qB)$', 'option2', '$T = 2\pi r/v = 2\pi m/(qB)$. The period is independent of speed.', 'p_force_moving_charge', 2, 'JEE Mains Prep', 'approved'),
('A wire of length $0.5\;\text{m}$ carrying $10\;\text{A}$ is placed perpendicular to a $0.2\;\text{T}$ field. The force on the wire is', '$2\;\text{N}$', '$0.1\;\text{N}$', '$1\;\text{N}$', '$0.5\;\text{N}$', 'option3', '$F = BIL = 0.2 \times 10 \times 0.5 = 1\;\text{N}$.', 'p_force_moving_charge', 2, 'JEE Mains Prep', 'approved'),
('A charged particle enters a magnetic field at angle $\theta$ to the field. Its path is', 'A straight line', 'A circle', 'A helix', 'A parabola', 'option3', 'The component $v\cos\theta$ along $\vec{B}$ is unaffected; $v\sin\theta$ perpendicular to $\vec{B}$ causes circular motion. The combination is a helix.', 'p_force_moving_charge', 2, 'JEE Mains Prep', 'approved'),
('The pitch of the helical path of a charged particle (mass $m$, charge $q$, speed $v$) entering a field $B$ at angle $\theta$ is', '$2\pi mv/(qB)$', '$2\pi mv\sin\theta/(qB)$', '$mv\cos\theta/(qB)$', '$2\pi mv\cos\theta/(qB)$', 'option4', 'Pitch $= v_\parallel \times T = v\cos\theta \times 2\pi m/(qB) = 2\pi mv\cos\theta/(qB)$.', 'p_force_moving_charge', 3, 'JEE Mains Prep', 'approved'),
('A proton and an electron enter a uniform magnetic field with the same momentum. The ratio of radii of their paths $r_p/r_e$ is', '$\sqrt{m_p/m_e}$', '$m_p/m_e$', '$m_e/m_p$', '$1$', 'option4', '$r = mv/(qB) = p/(qB)$. Same momentum $p$ and same $|q| = e$: $r_p/r_e = 1$.', 'p_force_moving_charge', 3, 'JEE Mains Prep', 'approved'),
('A charged particle moves in a region with both $\vec{E}$ and $\vec{B}$ fields. For the particle to move undeflected in a straight line, the condition is', '$\vec{E} + \vec{v} \times \vec{B} = 0$ (i.e., $v = E/B$ with $\vec{E} \perp \vec{B}$)', '$E = B$', '$v = EB$', '$\vec{E} \parallel \vec{B}$', 'option1', 'For zero net force: $q\vec{E} + q\vec{v} \times \vec{B} = 0$. This gives $v = E/B$ with $\vec{E}$, $\vec{v}$, $\vec{B}$ mutually perpendicular (velocity selector).', 'p_force_moving_charge', 3, 'JEE Mains Prep', 'approved'),
('Two particles of masses $m$ and $4m$, charges $q$ and $2q$, are accelerated through the same potential difference and enter a magnetic field. The ratio of their radii is', '$2:1$', '$\sqrt{2}:1$', '$1:2$', '$1:\sqrt{2}$', 'option4', '$r = \sqrt{2mV}/(qB)$ (since $KE = qV$, $mv = \sqrt{2mqV}$, $r = mv/(qB) = \sqrt{2mV/q}/B$). $r_1/r_2 = \sqrt{m_1/(q_1)} / \sqrt{m_2/(q_2)} = \sqrt{m \cdot 2q/(q \cdot 4m)} = \sqrt{1/2} = 1/\sqrt{2}$. Ratio $= 1:\sqrt{2}$.', 'p_force_moving_charge', 3, 'JEE Mains Prep', 'approved'),
('A semicircular wire of radius $R$ carrying current $I$ is placed in a uniform field $B$ perpendicular to its plane. The net force on the wire is', 'Zero', '$\pi BIR$', '$BIR$', '$2BIR$', 'option4', 'The net force on a curved wire in a uniform field equals the force on a straight wire connecting its endpoints: $F = BI(2R) = 2BIR$.', 'p_force_moving_charge', 3, 'JEE Mains Prep', 'approved'),
('In a cyclotron, the maximum kinetic energy of a particle (mass $m$, charge $q$) with maximum radius $R$ and field $B$ is', '$qBR$', '$q^2 B^2 R^2/(2m)$', '$qB^2R^2/(2m)$', '$q^2BR^2/(2m)$', 'option2', '$r = mv/(qB)$, so $v_{max} = qBR/m$. $KE_{max} = \frac{1}{2}mv_{max}^2 = q^2B^2R^2/(2m)$.', 'p_force_moving_charge', 3, 'JEE Mains Prep', 'approved'),
('A current-carrying rectangular loop (sides $a$ and $b$) is placed in a non-uniform magnetic field. The loop experiences', 'Both a net force and a torque', 'Only a torque', 'Only a net force', 'Neither force nor torque', 'option1', 'In a non-uniform field, forces on opposite sides are unequal, producing both a net force (translation) and a torque (rotation).', 'p_force_moving_charge', 3, 'JEE Mains Prep', 'approved'),
('The frequency of revolution (cyclotron frequency) of a charged particle in a magnetic field is', '$mv/(qB)$', '$2\pi m/(qB)$', '$qBv/(2\pi m)$', '$qB/(2\pi m)$', 'option4', '$f = 1/T = qB/(2\pi m)$. The cyclotron frequency is independent of the speed of the particle.', 'p_force_moving_charge', 2, 'JEE Mains Prep', 'approved'),

-- ============================================================
-- p_parallel_conductors_torque (7 easy, 7 medium, 7 hard = 21)
-- ============================================================
('Two long parallel wires carrying currents in the same direction', 'Attract each other', 'Repel each other', 'Exert no force', 'Twist around each other', 'option1', 'Parallel currents attract; antiparallel currents repel. This follows from the force between the current and the other wire''s magnetic field.', 'p_parallel_conductors_torque', 1, 'JEE Mains Prep', 'approved'),
('The force per unit length between two parallel wires carrying currents $I_1$ and $I_2$ separated by distance $d$ is', '$\mu_0 I_1 I_2/(2\pi d)$', '$\mu_0 I_1 I_2/d$', '$\mu_0 I_1 I_2/(4\pi d)$', '$\mu_0 I_1 I_2 d$', 'option1', '$F/L = \mu_0 I_1 I_2/(2\pi d)$.', 'p_parallel_conductors_torque', 1, 'JEE Mains Prep', 'approved'),
('One ampere is defined as the current which, when flowing through two parallel wires $1\;\text{m}$ apart, produces a force per unit length of', '$2 \times 10^{-7}\;\text{N/m}$', '$4\pi \times 10^{-7}\;\text{N/m}$', '$1\;\text{N/m}$', '$10^{-7}\;\text{N/m}$', 'option1', '$F/L = \mu_0 I^2/(2\pi d) = 4\pi \times 10^{-7} \times 1/(2\pi \times 1) = 2 \times 10^{-7}\;\text{N/m}$.', 'p_parallel_conductors_torque', 1, 'JEE Mains Prep', 'approved'),
('The torque on a current loop of area $A$ carrying current $I$ in a uniform field $B$ at angle $\theta$ between the normal and $\vec{B}$ is', '$IAB$', '$IAB\cos\theta$', '$IAB\sin\theta$', '$IA/B$', 'option3', '$\tau = NIAB\sin\theta$ (for $N = 1$ turn). Maximum when $\theta = 90°$.', 'p_parallel_conductors_torque', 1, 'JEE Mains Prep', 'approved'),
('The magnetic moment of a current loop of area $A$ carrying current $I$ is', '$I^2A$', '$I/A$', '$A/I$', '$IA$', 'option4', 'Magnetic moment $M = NIA$ (for $N$ turns). Direction is along the area vector (right-hand rule).', 'p_parallel_conductors_torque', 1, 'JEE Mains Prep', 'approved'),
('Two long parallel wires carrying currents in opposite directions', 'Repel each other', 'Attract each other', 'Exert no force', 'Attract then repel', 'option1', 'Antiparallel currents repel each other.', 'p_parallel_conductors_torque', 1, 'JEE Mains Prep', 'approved'),
('The torque on a current loop is maximum when the plane of the loop is', 'It does not depend on orientation', 'Perpendicular to the magnetic field', 'At $45°$ to the field', 'Parallel to the magnetic field', 'option4', '$\tau = NIAB\sin\theta$. Maximum when $\theta = 90°$, i.e., the normal to the loop is perpendicular to $\vec{B}$, meaning the plane of the loop is parallel to $\vec{B}$.', 'p_parallel_conductors_torque', 1, 'JEE Mains Prep', 'approved'),
('Two parallel wires $5\;\text{cm}$ apart carry $10\;\text{A}$ each in the same direction. The force per metre between them is', '$4 \times 10^{-4}\;\text{N/m}$', '$2 \times 10^{-4}\;\text{N/m}$', '$8 \times 10^{-4}\;\text{N/m}$', '$10^{-4}\;\text{N/m}$', 'option1', '$F/L = \mu_0 I_1 I_2/(2\pi d) = 4\pi \times 10^{-7} \times 100/(2\pi \times 0.05) = 4 \times 10^{-4}\;\text{N/m}$ (attractive).', 'p_parallel_conductors_torque', 2, 'JEE Mains Prep', 'approved'),
('A rectangular coil of $100$ turns, area $0.01\;\text{m}^2$, carrying $2\;\text{A}$ is in a $0.5\;\text{T}$ field. The maximum torque is', '$1\;\text{N}\cdot\text{m}$', '$0.5\;\text{N}\cdot\text{m}$', '$0.1\;\text{N}\cdot\text{m}$', '$10\;\text{N}\cdot\text{m}$', 'option1', '$\tau_{max} = NIAB = 100 \times 2 \times 0.01 \times 0.5 = 1\;\text{N}\cdot\text{m}$.', 'p_parallel_conductors_torque', 2, 'JEE Mains Prep', 'approved'),
('A circular coil of radius $R$ and $N$ turns carrying current $I$ has magnetic moment', '$NI/(2R)$', '$NIR$', '$NI\pi R^2$', '$2\pi NIR$', 'option3', '$M = NIA = NI(\pi R^2)$.', 'p_parallel_conductors_torque', 2, 'JEE Mains Prep', 'approved'),
('The potential energy of a magnetic dipole of moment $\vec{M}$ in a field $\vec{B}$ is', '$-\vec{M}\cdot\vec{B}$', '$\vec{M}\cdot\vec{B}$', '$MB$', '$M/B$', 'option1', '$U = -\vec{M}\cdot\vec{B} = -MB\cos\theta$. Minimum (stable) when $\vec{M} \parallel \vec{B}$.', 'p_parallel_conductors_torque', 2, 'JEE Mains Prep', 'approved'),
('If the current in both parallel wires is doubled, the force between them becomes', '$8$ times', '$2$ times', 'Same', '$4$ times the original', 'option4', '$F \propto I_1 I_2$. If both double: $F'' = (2I)(2I)/(I \cdot I) \times F = 4F$.', 'p_parallel_conductors_torque', 2, 'JEE Mains Prep', 'approved'),
('A current loop of magnetic moment $M$ is in stable equilibrium in a field $B$. The work done to rotate it by $60°$ from equilibrium is', '$MB$', '$MB/2$', '$MB(1 - \sqrt{3}/2)$', '$MB\sqrt{3}/2$', 'option2', '$W = MB(\cos 0° - \cos 60°) = MB(1 - 1/2) = MB/2$.', 'p_parallel_conductors_torque', 2, 'JEE Mains Prep', 'approved'),
('The work done in rotating a current loop from stable ($\theta = 0$) to unstable ($\theta = \pi$) equilibrium in a field $B$ is', 'Zero', '$MB$', '$MB/2$', '$2MB$', 'option4', '$W = MB(\cos 0° - \cos 180°) = MB(1 - (-1)) = 2MB$.', 'p_parallel_conductors_torque', 2, 'JEE Mains Prep', 'approved'),
('A current loop of moment $M$ is free to rotate in a uniform field $B$. The angular frequency of small oscillations about equilibrium is', '$\sqrt{MB/I_{rot}}$ where $I_{rot}$ is the moment of inertia', '$\sqrt{I_{rot}/(MB)}$', '$MB/I_{rot}$', '$\sqrt{MB}$', 'option1', 'Restoring torque $\tau = -MB\sin\theta \approx -MB\theta$ for small $\theta$. SHM: $\omega = \sqrt{MB/I_{rot}}$.', 'p_parallel_conductors_torque', 3, 'JEE Mains Prep', 'approved'),
('Three long parallel wires at the vertices of an equilateral triangle of side $a$ carry equal currents $I$ in the same direction. The force per unit length on each wire is', '$\mu_0 I^2 \sqrt{3}/(2\pi a)$', '$\mu_0 I^2/(2\pi a)$', '$\mu_0 I^2/(\pi a)$', '$\mu_0 I^2/(4\pi a)$', 'option3', 'Each wire is attracted by the other two. Force from each neighbour: $F_1 = \mu_0 I^2/(2\pi a)$. The two forces are at $60°$. Resultant $= \sqrt{F_1^2 + F_1^2 + 2F_1^2\cos 60°} = F_1\sqrt{3} = \mu_0 I^2\sqrt{3}/(2\pi a)$.', 'p_parallel_conductors_torque', 3, 'JEE Mains Prep', 'approved'),
('A square coil of side $a$, $N$ turns, current $I$, is placed in a field $B$ with its plane at $30°$ to the field. The torque on the coil is', '$NIa^2B\cos 30°$', '$NIa^2B\sin 30°$', '$NIa^2B$', '$NIa^2B\tan 30°$', 'option1', 'Angle between normal and $\vec{B}$ is $90° - 30° = 60°$. $\tau = NIa^2B\sin 60° = NIa^2B\cos 30° = NIa^2B\sqrt{3}/2$.', 'p_parallel_conductors_torque', 3, 'JEE Mains Prep', 'approved'),
('Two parallel wires of length $L$ carry currents $I_1 = 5\;\text{A}$ and $I_2 = 10\;\text{A}$ in opposite directions, separated by $0.1\;\text{m}$. The force between them for $L = 2\;\text{m}$ is', '$2 \times 10^{-4}\;\text{N}$ (repulsive)', '$10^{-4}\;\text{N}$ (attractive)', '$4 \times 10^{-4}\;\text{N}$ (repulsive)', '$2 \times 10^{-4}\;\text{N}$ (attractive)', 'option1', '$F = \mu_0 I_1 I_2 L/(2\pi d) = 4\pi \times 10^{-7} \times 50 \times 2/(2\pi \times 0.1) = 2 \times 10^{-4}\;\text{N}$. Opposite currents: repulsive.', 'p_parallel_conductors_torque', 3, 'JEE Mains Prep', 'approved'),
('A coil of $N$ turns and area $A$ carrying current $I$ is suspended in a radial magnetic field $B$. The deflecting torque for any deflection angle $\phi$ is', '$NIAB\cos\phi$', '$NIAB\sin\phi$', '$NIAB$ (constant, independent of $\phi$)', 'Zero', 'option3', 'In a radial field, the plane of the coil is always parallel to $\vec{B}$, so $\theta = 90°$ always. $\tau = NIAB\sin 90° = NIAB$ (constant).', 'p_parallel_conductors_torque', 3, 'JEE Mains Prep', 'approved'),
('A current-carrying coil of magnetic moment $\vec{M}$ is placed in a non-uniform magnetic field. The force on the coil is', 'Zero', '$\nabla(\vec{M}\cdot\vec{B})$', '$M \times B$', '$MB$', 'option2', 'In a non-uniform field, the net force on a magnetic dipole is $\vec{F} = \nabla(\vec{M}\cdot\vec{B})$.', 'p_parallel_conductors_torque', 3, 'JEE Mains Prep', 'approved'),
('A flat circular coil of $20$ turns, radius $5\;\text{cm}$, carries $0.5\;\text{A}$ in a $0.2\;\text{T}$ field. The maximum torque is approximately', '$3.14 \times 10^{-3}\;\text{N}\cdot\text{m}$', '$1.57 \times 10^{-2}\;\text{N}\cdot\text{m}$', '$6.28 \times 10^{-3}\;\text{N}\cdot\text{m}$', '$0.314\;\text{N}\cdot\text{m}$', 'option2', '$A = \pi(0.05)^2 = 7.85 \times 10^{-3}\;\text{m}^2$. $\tau = NIAB = 20 \times 0.5 \times 7.85 \times 10^{-3} \times 0.2 = 1.57 \times 10^{-2}\;\text{N}\cdot\text{m}$.', 'p_parallel_conductors_torque', 3, 'JEE Mains Prep', 'approved'),

-- ============================================================
-- p_galvanometer (7 easy, 7 medium, 7 hard = 21)
-- ============================================================
('A moving coil galvanometer works on the principle of', 'Electrostatic force', 'Electromagnetic induction', 'Heating effect of current', 'Torque on a current loop in a magnetic field', 'option4', 'A galvanometer uses the torque $\tau = NIAB$ on a current-carrying coil in a radial magnetic field.', 'p_galvanometer', 1, 'JEE Mains Prep', 'approved'),
('To convert a galvanometer into an ammeter, one must connect', 'A low resistance in series', 'A high resistance in series', 'A low resistance (shunt) in parallel', 'A high resistance in parallel', 'option3', 'A shunt (low resistance) in parallel diverts most of the current, protecting the galvanometer.', 'p_galvanometer', 1, 'JEE Mains Prep', 'approved'),
('To convert a galvanometer into a voltmeter, one must connect', 'A high resistance in parallel', 'A low resistance in parallel', 'A high resistance in series', 'A low resistance in series', 'option3', 'A high series resistance limits the current through the galvanometer for a given voltage.', 'p_galvanometer', 1, 'JEE Mains Prep', 'approved'),
('The deflection in a moving coil galvanometer is proportional to', 'The current through the coil', 'The square of the current', 'The voltage across the coil', 'The resistance of the coil', 'option1', '$\theta = NIAB/(k)$ where $k$ is the torsion constant. $\theta \propto I$.', 'p_galvanometer', 1, 'JEE Mains Prep', 'approved'),
('A radial magnetic field is used in a galvanometer so that', 'The sensitivity decreases', 'The field is stronger', 'The coil rotates faster', 'The torque is constant for all deflections', 'option4', 'In a radial field, $\sin\theta = 1$ always, making $\tau = NIAB$ independent of deflection angle.', 'p_galvanometer', 1, 'JEE Mains Prep', 'approved'),
('The current sensitivity of a galvanometer is defined as', 'Current per unit deflection', 'Deflection per unit current ($\theta/I$)', 'Voltage per unit deflection', 'Resistance per unit current', 'option2', 'Current sensitivity $= \theta/I = NAB/k$ (radians per ampere).', 'p_galvanometer', 1, 'JEE Mains Prep', 'approved'),
('An ideal ammeter has', 'Resistance equal to the circuit', 'Infinite resistance', 'Very high resistance', 'Zero resistance', 'option4', 'An ideal ammeter has zero resistance so it does not alter the current being measured.', 'p_galvanometer', 1, 'JEE Mains Prep', 'approved'),
('A galvanometer of resistance $G = 50\;\Omega$ gives full-scale deflection at $I_g = 1\;\text{mA}$. To convert it to an ammeter of range $1\;\text{A}$, the shunt resistance needed is', '$999\;\Omega$', '$50\;\Omega$', '$50/999\;\Omega \approx 0.05\;\Omega$', '$0.5\;\Omega$', 'option3', '$S = I_g G/(I - I_g) = 0.001 \times 50/(1 - 0.001) = 0.05/0.999 \approx 0.05\;\Omega = 50/999\;\Omega$.', 'p_galvanometer', 2, 'JEE Mains Prep', 'approved'),
('A galvanometer of resistance $100\;\Omega$ gives full-scale deflection at $10\;\text{mA}$. To convert it to a voltmeter of range $10\;\text{V}$, the series resistance needed is', '$1000\;\Omega$', '$900\;\Omega$', '$100\;\Omega$', '$9900\;\Omega$', 'option2', '$R = V/I_g - G = 10/0.01 - 100 = 1000 - 100 = 900\;\Omega$.', 'p_galvanometer', 2, 'JEE Mains Prep', 'approved'),
('Increasing the number of turns in a galvanometer coil', 'Increases current sensitivity', 'Decreases current sensitivity', 'Has no effect on sensitivity', 'Increases voltage sensitivity only', 'option1', 'Current sensitivity $= NAB/k$. Increasing $N$ increases sensitivity.', 'p_galvanometer', 2, 'JEE Mains Prep', 'approved'),
('An ideal voltmeter has', 'Zero resistance', 'Infinite resistance', 'Resistance equal to the circuit', 'Very low resistance', 'option2', 'An ideal voltmeter draws no current, requiring infinite resistance.', 'p_galvanometer', 2, 'JEE Mains Prep', 'approved'),
('A galvanometer has a figure of merit of $10^{-9}\;\text{A/div}$. This means', 'The voltage sensitivity is $10^{-9}\;\text{V/div}$', 'The current needed for one division deflection is $10^{-9}\;\text{A}$', 'The resistance is $10^{-9}\;\Omega$', 'The maximum current is $10^{-9}\;\text{A}$', 'option2', 'Figure of merit is the current per division of deflection.', 'p_galvanometer', 2, 'JEE Mains Prep', 'approved'),
('The voltage sensitivity of a galvanometer is', '$k/(NAB)$', '$NAB/k$', '$NAB/(kG)$ where $G$ is the galvanometer resistance', '$NABG/k$', 'option3', 'Voltage sensitivity $= \theta/V = \theta/(IG) = (NAB/k)/G = NAB/(kG)$.', 'p_galvanometer', 2, 'JEE Mains Prep', 'approved'),
('A galvanometer can be made more sensitive by', 'Using a stiffer spring', 'Using a weaker spring (smaller $k$) and stronger magnet', 'Reducing the number of turns', 'Reducing the area of the coil', 'option2', 'Sensitivity $= NAB/k$. Increase $N$, $A$, $B$ or decrease $k$ to improve sensitivity.', 'p_galvanometer', 2, 'JEE Mains Prep', 'approved'),
('A galvanometer ($G = 20\;\Omega$, $I_g = 5\;\text{mA}$) is converted to an ammeter of range $5\;\text{A}$. The combined resistance of the ammeter is approximately', '$2\;\Omega$', '$20\;\Omega$', '$0.2\;\Omega$', '$0.02\;\Omega$', 'option4', 'Shunt $S = I_g G/(I - I_g) \approx 0.005 \times 20/5 = 0.02\;\Omega$. Ammeter resistance $= GS/(G+S) \approx S = 0.02\;\Omega$ (since $S \ll G$).', 'p_galvanometer', 3, 'JEE Mains Prep', 'approved'),
('A galvanometer of resistance $G$ is converted to a voltmeter of range $V$ and an ammeter of range $I$. The ratio of the voltmeter resistance to the ammeter resistance is approximately', '$V \times I$', '$(V/I)^2$', '$V/(IG)$', '$VI/(I_g^2 G)$ where $I_g$ is the full-scale current', 'option4', 'Voltmeter resistance $\approx V/I_g$. Ammeter resistance $\approx I_g G/I$. Ratio $= (V/I_g)/(I_g G/I) = VI/(I_g^2 G)$.', 'p_galvanometer', 3, 'JEE Mains Prep', 'approved'),
('When a galvanometer is used as a null detector (as in a Wheatstone bridge), its sensitivity is most important because', 'It must detect very small currents near balance', 'It must carry large currents', 'It must measure voltage accurately', 'It must have zero resistance', 'option1', 'As a null detector, the galvanometer must detect the slightest imbalance (very small current), so high sensitivity is crucial.', 'p_galvanometer', 3, 'JEE Mains Prep', 'approved'),
('A galvanometer ($G = 100\;\Omega$, $I_g = 1\;\text{mA}$) is converted to a voltmeter of range $0$ to $10\;\text{V}$. If this voltmeter is used to measure the voltage across a $10\;\text{k}\Omega$ resistor in a circuit, the reading will be', 'Exactly the actual voltage', 'Less than the actual voltage due to loading effect', 'More than the actual voltage', 'Zero', 'option2', 'Voltmeter resistance $= 10/0.001 = 10\;\text{k}\Omega$. This is comparable to the circuit resistance, so significant current is drawn, reducing the measured voltage (loading effect).', 'p_galvanometer', 3, 'JEE Mains Prep', 'approved'),
('A galvanometer ($G = 50\;\Omega$, $I_g = 2\;\text{mA}$) is to be converted to a voltmeter of range $0$-$10\;\text{V}$ and an ammeter of range $0$-$2\;\text{A}$. The series resistance for the voltmeter is', '$4900\;\Omega$', '$5000\;\Omega$', '$50\;\Omega$', '$4950\;\Omega$', 'option4', '$R = V/I_g - G = 10/0.002 - 50 = 5000 - 50 = 4950\;\Omega$.', 'p_galvanometer', 3, 'JEE Mains Prep', 'approved'),
('Two galvanometers $G_1$ (resistance $10\;\Omega$, $I_g = 10\;\text{mA}$) and $G_2$ (resistance $20\;\Omega$, $I_g = 5\;\text{mA}$) are available. For conversion to a voltmeter of range $5\;\text{V}$, which requires less additional resistance?', '$G_2$ (needs $980\;\Omega$)', '$G_1$ (needs $490\;\Omega$)', 'Both need the same', 'Cannot be determined', 'option2', '$R_1 = 5/0.01 - 10 = 490\;\Omega$. $R_2 = 5/0.005 - 20 = 980\;\Omega$. $G_1$ needs less.', 'p_galvanometer', 3, 'JEE Mains Prep', 'approved'),
('A galvanometer shows full-scale deflection for a current $I_g$. A shunt of resistance $G/n$ is connected (where $G$ is galvanometer resistance). The new range of the ammeter is', '$(n+1)I_g$', '$nI_g$', '$I_g/n$', '$I_g(n-1)$', 'option1', 'With shunt $S = G/n$: $I = I_g(1 + G/S) = I_g(1 + n) = (n+1)I_g$.', 'p_galvanometer', 3, 'JEE Mains Prep', 'approved'),

-- ============================================================
-- p_magnetic_dipole (7 easy, 7 medium, 7 hard = 21)
-- ============================================================
('A current-carrying circular loop behaves as a', 'Quadrupole', 'Electric dipole', 'Magnetic monopole', 'Magnetic dipole', 'option4', 'A current loop has a magnetic moment $M = IA$ and produces a dipole field at large distances.', 'p_magnetic_dipole', 1, 'JEE Mains Prep', 'approved'),
('A bar magnet is equivalent to', 'A single moving charge', 'A solenoid carrying current', 'An electric dipole', 'A capacitor', 'option2', 'A bar magnet can be modelled as a solenoid with circulating atomic currents producing the same external field.', 'p_magnetic_dipole', 1, 'JEE Mains Prep', 'approved'),
('Magnetic field lines', 'Start from north pole and end at south pole only', 'Form closed loops (no beginning or end)', 'Can cross each other', 'Start from south pole', 'option2', 'Magnetic field lines are always closed loops ($\nabla \cdot \vec{B} = 0$). Inside a magnet, they go from S to N.', 'p_magnetic_dipole', 1, 'JEE Mains Prep', 'approved'),
('The magnetic moment of a bar magnet of pole strength $m$ and length $2l$ is', '$m \times l$', '$m/2l$', '$m \times 2l$', '$2m/l$', 'option3', '$M = m \times 2l$ (pole strength times magnetic length), directed from S to N.', 'p_magnetic_dipole', 1, 'JEE Mains Prep', 'approved'),
('Inside a bar magnet, the magnetic field lines go from', 'South pole to north pole', 'North pole to south pole', 'They do not exist inside', 'Randomly', 'option1', 'Inside the magnet, field lines go from S to N (completing the closed loop from N to S outside).', 'p_magnetic_dipole', 1, 'JEE Mains Prep', 'approved'),
('The SI unit of magnetic moment is', '$\text{A}\cdot\text{m}^2$', '$\text{T}\cdot\text{m}$', '$\text{Wb}\cdot\text{m}$', '$\text{A/m}$', 'option1', 'Magnetic moment $= IA$, unit: $\text{A}\cdot\text{m}^2$ (or equivalently $\text{J/T}$).', 'p_magnetic_dipole', 1, 'JEE Mains Prep', 'approved'),
('The net magnetic flux through any closed surface is', 'Non-zero for a magnet', 'Equal to the enclosed magnetic charge', 'Always zero', 'Depends on the surface', 'option3', 'Gauss''s law for magnetism: $\oint \vec{B}\cdot d\vec{A} = 0$. No magnetic monopoles exist.', 'p_magnetic_dipole', 1, 'JEE Mains Prep', 'approved'),
('A short bar magnet of moment $M$ is placed along the axis of a solenoid. The torque on the magnet is', 'Depends on position', '$MB$', '$MB/2$', 'Zero (field is uniform inside solenoid)', 'option4', 'Inside an ideal solenoid, the field is uniform. A dipole in a uniform field aligned with it experiences zero torque.', 'p_magnetic_dipole', 2, 'JEE Mains Prep', 'approved'),
('The magnetic field at a point on the axis of a short bar magnet at distance $r$ ($r \gg l$) is', '$\mu_0 2M/(4\pi r^3)$', '$\mu_0 M/(4\pi r^3)$', '$\mu_0 M/(4\pi r^2)$', '$\mu_0 2M/(4\pi r^2)$', 'option1', 'Axial field of a magnetic dipole: $B = \mu_0 2M/(4\pi r^3)$, same form as an electric dipole.', 'p_magnetic_dipole', 2, 'JEE Mains Prep', 'approved'),
('The magnetic field at a point on the equatorial line of a short bar magnet at distance $r$ is', 'Zero', '$\mu_0 2M/(4\pi r^3)$', '$\mu_0 M/(4\pi r^2)$', '$\mu_0 M/(4\pi r^3)$', 'option4', 'Equatorial field: $B = \mu_0 M/(4\pi r^3)$, directed antiparallel to $\vec{M}$.', 'p_magnetic_dipole', 2, 'JEE Mains Prep', 'approved'),
('A bar magnet of moment $0.5\;\text{A}\cdot\text{m}^2$ is placed in a uniform field of $0.2\;\text{T}$ at $30°$ to the field. The torque is', '$0.1\;\text{N}\cdot\text{m}$', '$0.05\;\text{N}\cdot\text{m}$', '$0.087\;\text{N}\cdot\text{m}$', '$0.2\;\text{N}\cdot\text{m}$', 'option2', '$\tau = MB\sin\theta = 0.5 \times 0.2 \times \sin 30° = 0.1 \times 0.5 = 0.05\;\text{N}\cdot\text{m}$.', 'p_magnetic_dipole', 2, 'JEE Mains Prep', 'approved'),
('The ratio of the axial field to the equatorial field of a magnetic dipole at the same distance is', '$2:1$', '$1:2$', '$1:1$', '$4:1$', 'option1', '$B_{axial}/B_{eq} = (\mu_0 2M/(4\pi r^3))/(\mu_0 M/(4\pi r^3)) = 2$.', 'p_magnetic_dipole', 2, 'JEE Mains Prep', 'approved'),
('A current loop of area $A$ and current $I$ is equivalent to a magnetic dipole. The field far from the loop varies as', '$1/r$', '$1/r^2$', '$1/r^3$', '$1/r^4$', 'option3', 'At large distances, a current loop produces a dipole field: $B \propto 1/r^3$.', 'p_magnetic_dipole', 2, 'JEE Mains Prep', 'approved'),
('The magnetic field at the equatorial point of a bar magnet is directed', 'Opposite to the magnetic moment (from N to S of the magnet)', 'Along the magnetic moment', 'Perpendicular to the axis', 'Radially outward', 'option1', 'On the equatorial line, $\vec{B}$ is antiparallel to $\vec{M}$ (points from N to S externally, which is opposite to $\vec{M}$ which goes S to N).', 'p_magnetic_dipole', 2, 'JEE Mains Prep', 'approved'),
('A bar magnet of moment $M$ is cut into two equal halves along its length. The magnetic moment of each half is', '$M/2$', '$M$', '$2M$', '$M/4$', 'option1', 'Cutting along the length halves the pole strength but keeps the length the same. $M'' = (m/2)(2l) = M/2$.', 'p_magnetic_dipole', 3, 'JEE Mains Prep', 'approved'),
('A bar magnet of moment $M$ is cut into two equal halves perpendicular to its length. The magnetic moment of each half is', '$2M$', '$M$', '$M/4$', '$M/2$', 'option4', 'Cutting perpendicular to length: pole strength stays $m$, length becomes $l$. $M'' = m \times l = M/2$.', 'p_magnetic_dipole', 3, 'JEE Mains Prep', 'approved'),
('Two short bar magnets of moments $M_1$ and $M_2$ are placed at distance $d$ apart with their axes perpendicular. The interaction energy is', '$-\mu_0 M_1 M_2/(4\pi d^3)$', 'Zero', '$\mu_0 M_1 M_2/(4\pi d^3)$', '$-\mu_0 2M_1 M_2/(4\pi d^3)$', 'option2', 'When one dipole is on the equatorial line of the other and perpendicular to it, $U = -\vec{M}_2 \cdot \vec{B}_1 = 0$ (since $\vec{M}_2 \perp \vec{B}_1$).', 'p_magnetic_dipole', 3, 'JEE Mains Prep', 'approved'),
('A bar magnet of moment $M$ oscillates in a horizontal magnetic field $B$ with time period $T$. If the magnet is cut in half (perpendicular to length), the time period of each half in the same field is', '$T$', '$T/2$', '$T/\sqrt{2}$', '$T\sqrt{2}$', 'option2', 'Each half: $M'' = M/2$, $I'' = I/8$ (moment of inertia of a rod $\propto mL^2$; mass halves, length halves: $I'' = (m/2)(L/2)^2/12 = mL^2/(96) = I/8$ where $I = mL^2/12$). $T'' = 2\pi\sqrt{I''/(M''B)} = 2\pi\sqrt{(I/8)/(MB/2)} = 2\pi\sqrt{I/(4MB)} = T/2$.', 'p_magnetic_dipole', 3, 'JEE Mains Prep', 'approved'),
('Two identical bar magnets are placed end to end with like poles touching. The combination behaves as', 'A magnetic quadrupole at large distances', 'A stronger dipole', 'A monopole', 'No magnetic effect', 'option1', 'Like poles together cancel the dipole moment. The leading term in the field expansion is the quadrupole term ($\propto 1/r^4$).', 'p_magnetic_dipole', 3, 'JEE Mains Prep', 'approved'),
('The magnetic field at a general point $(r, \theta)$ from a magnetic dipole has magnitude', '$\frac{\mu_0 2M\cos\theta}{4\pi r^3}$', '$\frac{\mu_0 M}{4\pi r^3}$', '$\frac{\mu_0 M}{4\pi r^3}\sqrt{1 + 3\cos^2\theta}$', '$\frac{\mu_0 M\sin\theta}{4\pi r^3}$', 'option3', '$B_r = \frac{\mu_0 2M\cos\theta}{4\pi r^3}$, $B_\theta = \frac{\mu_0 M\sin\theta}{4\pi r^3}$. $B = \frac{\mu_0 M}{4\pi r^3}\sqrt{4\cos^2\theta + \sin^2\theta} = \frac{\mu_0 M}{4\pi r^3}\sqrt{1 + 3\cos^2\theta}$.', 'p_magnetic_dipole', 3, 'JEE Mains Prep', 'approved'),
('A bar magnet of moment $M$ and moment of inertia $I$ oscillates in Earth''s field $B_H = 3 \times 10^{-5}\;\text{T}$ with period $2\;\text{s}$. If $B_H$ becomes $1.2 \times 10^{-4}\;\text{T}$, the new period is', '$\sqrt{2}\;\text{s}$', '$0.5\;\text{s}$', '$4\;\text{s}$', '$1\;\text{s}$', 'option4', '$T \propto 1/\sqrt{B}$. $T_2/T_1 = \sqrt{B_1/B_2} = \sqrt{3 \times 10^{-5}/(1.2 \times 10^{-4})} = \sqrt{1/4} = 1/2$. $T_2 = 2/2 = 1\;\text{s}$.', 'p_magnetic_dipole', 3, 'JEE Mains Prep', 'approved'),

-- ============================================================
-- p_magnetic_field_dipole (7 easy, 7 medium, 7 hard = 21)
-- ============================================================
('The magnetic field on the axial line of a bar magnet points', 'Opposite to the magnetic moment', 'In the same direction as the magnetic moment', 'Perpendicular to the axis', 'Radially outward', 'option2', 'On the axial line, $\vec{B}$ is parallel to $\vec{M}$ (from S to N inside, N to S outside along axis).', 'p_magnetic_field_dipole', 1, 'JEE Mains Prep', 'approved'),
('The magnetic field on the equatorial line of a bar magnet points', 'Away from the magnet', 'Along the magnetic moment', 'Perpendicular to the axis', 'Opposite to the magnetic moment', 'option4', 'On the equatorial line, $\vec{B}$ is antiparallel to $\vec{M}$.', 'p_magnetic_field_dipole', 1, 'JEE Mains Prep', 'approved'),
('The torque on a magnetic dipole of moment $M$ in a uniform field $B$ at angle $\theta$ is', '$MB\cos\theta$', '$MB\sin\theta$', '$MB$', '$M/B$', 'option2', '$\tau = MB\sin\theta = |\vec{M} \times \vec{B}|$.', 'p_magnetic_field_dipole', 1, 'JEE Mains Prep', 'approved'),
('A freely suspended bar magnet aligns itself', 'Vertically', 'Perpendicular to Earth''s field', 'Along the Earth''s magnetic field (geographic N-S approximately)', 'Randomly', 'option3', 'A free magnet aligns with the horizontal component of Earth''s field, pointing approximately N-S.', 'p_magnetic_field_dipole', 1, 'JEE Mains Prep', 'approved'),
('The angle of dip at the magnetic equator is', '$45°$', '$90°$', '$0°$', '$60°$', 'option3', 'At the magnetic equator, the field is horizontal, so the dip angle is $0°$.', 'p_magnetic_field_dipole', 1, 'JEE Mains Prep', 'approved'),
('The horizontal component of Earth''s magnetic field $B_H$ is related to the total field $B$ and dip angle $\delta$ by', '$B_H = B\sin\delta$', '$B_H = B\cos\delta$', '$B_H = B\tan\delta$', '$B_H = B/\cos\delta$', 'option2', '$B_H = B\cos\delta$ and $B_V = B\sin\delta$.', 'p_magnetic_field_dipole', 1, 'JEE Mains Prep', 'approved'),
('The angle of dip at the magnetic poles is', '$90°$', '$0°$', '$45°$', '$60°$', 'option1', 'At the magnetic poles, the field is vertical, so the dip angle is $90°$.', 'p_magnetic_field_dipole', 1, 'JEE Mains Prep', 'approved'),
('A bar magnet of moment $M$ is placed at distance $d$ on the axial line of another identical magnet. The force between them varies as', '$1/d$', '$1/d^2$', '$1/d^3$', '$1/d^4$', 'option4', 'Force between two dipoles: $F \propto dB/dr \propto d(1/r^3)/dr \propto 1/r^4$.', 'p_magnetic_field_dipole', 2, 'JEE Mains Prep', 'approved'),
('At a place where the dip is $60°$ and $B_H = 0.3\;\text{G}$, the total magnetic field is', '$0.6\;\text{G}$', '$0.3\;\text{G}$', '$0.15\;\text{G}$', '$0.52\;\text{G}$', 'option1', '$B = B_H/\cos\delta = 0.3/\cos 60° = 0.3/0.5 = 0.6\;\text{G}$.', 'p_magnetic_field_dipole', 2, 'JEE Mains Prep', 'approved'),
('A bar magnet of moment $M$ is placed perpendicular to a uniform field $B$. The torque on it is', '$2MB$', '$MB/2$', 'Zero', '$MB$', 'option4', '$\tau = MB\sin 90° = MB$ (maximum torque).', 'p_magnetic_field_dipole', 2, 'JEE Mains Prep', 'approved'),
('The vertical component of Earth''s field at a place where dip is $45°$ and $B_H = 0.4\;\text{G}$ is', '$0.2\;\text{G}$', '$0.4\;\text{G}$', '$0.8\;\text{G}$', '$0.283\;\text{G}$', 'option2', '$B_V = B_H\tan\delta = 0.4 \times \tan 45° = 0.4\;\text{G}$.', 'p_magnetic_field_dipole', 2, 'JEE Mains Prep', 'approved'),
('A compass needle oscillates with period $T$ in Earth''s field. If a bar magnet is brought near such that the field doubles, the new period is', '$T/\sqrt{2}$', '$T/2$', '$T\sqrt{2}$', '$2T$', 'option1', '$T \propto 1/\sqrt{B}$. If $B \to 2B$: $T'' = T/\sqrt{2}$.', 'p_magnetic_field_dipole', 2, 'JEE Mains Prep', 'approved'),
('The magnetic declination at a place is', 'The horizontal component of the field', 'The angle of dip', 'The angle between geographic north and magnetic north', 'The total field strength', 'option3', 'Declination is the angle between the geographic meridian and the magnetic meridian at that place.', 'p_magnetic_field_dipole', 2, 'JEE Mains Prep', 'approved'),
('A tangent galvanometer has a coil of $50$ turns, radius $0.1\;\text{m}$. If $B_H = 3.6 \times 10^{-5}\;\text{T}$ and the deflection is $45°$, the current is', '$\approx 0.115\;\text{A}$', '$\approx 1.15\;\text{A}$', '$\approx 0.0115\;\text{A}$', '$\approx 11.5\;\text{A}$', 'option1', '$I = (2RB_H\tan\theta)/(\mu_0 N) = (2 \times 0.1 \times 3.6 \times 10^{-5} \times 1)/(4\pi \times 10^{-7} \times 50) = 7.2 \times 10^{-6}/(6.283 \times 10^{-5}) \approx 0.115\;\text{A}$.', 'p_magnetic_field_dipole', 2, 'JEE Mains Prep', 'approved'),
('Two short bar magnets of moments $M$ and $2M$ are placed at distance $d$ apart with their axes along the same line (N-S-N-S arrangement). The null point (where $B = 0$) lies', 'Between them, closer to the weaker magnet', 'Between them, at the midpoint', 'Outside, beyond the weaker magnet', 'Outside, beyond the stronger magnet', 'option1', 'Between two like-oriented axial dipoles, the fields oppose. The null point is closer to the weaker magnet (similar to electric charges).', 'p_magnetic_field_dipole', 3, 'JEE Mains Prep', 'approved'),
('A bar magnet oscillates in Earth''s horizontal field with period $T_1$. When another magnet is placed nearby with its field aiding Earth''s field, the period becomes $T_2$. When opposing, $T_3$. The ratio $B_{magnet}/B_H$ is', '$(T_3^2 + T_2^2)/(T_3^2 - T_2^2)$', '$(T_3^2 - T_2^2)/(T_3^2 + T_2^2)$', '$T_2/T_3$', '$T_3/T_2$', 'option2', '$T_2 = 2\pi\sqrt{I/(M(B_H + B''))}$, $T_3 = 2\pi\sqrt{I/(M(B_H - B''))}$. $T_2^2/T_3^2 = (B_H - B'')/(B_H + B'')$. Solving: $B''/B_H = (T_3^2 - T_2^2)/(T_3^2 + T_2^2)$.', 'p_magnetic_field_dipole', 3, 'JEE Mains Prep', 'approved'),
('At a point on the axis of a short magnet at distance $r$, the field is $B_1$. At the same distance on the equatorial line, the field is $B_2$. The angle that the resultant field at a general point at the same distance makes with the radial direction when $\theta = 45°$ is', '$30°$', '$45°$', '$\arctan(2)$', '$\arctan(1/2)$ from the radial direction', 'option4', 'At general point: $\tan\alpha = B_\theta/B_r = \sin\theta/(2\cos\theta) = \tan\theta/2$. At $\theta = 45°$: $\tan\alpha = 1/2$. $\alpha = \arctan(1/2)$.', 'p_magnetic_field_dipole', 3, 'JEE Mains Prep', 'approved'),
('A dip circle is rotated so that its plane makes angle $\phi$ with the magnetic meridian. The apparent dip $\delta''$ is related to the true dip $\delta$ by', '$\tan\delta'' = \tan\delta/\cos\phi$', '$\tan\delta'' = \tan\delta \cos\phi$', '$\delta'' = \delta + \phi$', '$\tan\delta'' = \tan\delta \sin\phi$', 'option1', 'In a plane at angle $\phi$ to the meridian: $B_H'' = B_H\cos\phi$ but $B_V$ is unchanged. $\tan\delta'' = B_V/B_H'' = B_V/(B_H\cos\phi) = \tan\delta/\cos\phi$.', 'p_magnetic_field_dipole', 3, 'JEE Mains Prep', 'approved'),
('Two identical bar magnets are placed at right angles to each other with their centres coinciding. The resultant magnetic moment is', '$M\sqrt{2}$', '$2M$', '$M$', 'Zero', 'option1', 'Two equal vectors at $90°$: resultant $= \sqrt{M^2 + M^2} = M\sqrt{2}$, at $45°$ to each.', 'p_magnetic_field_dipole', 3, 'JEE Mains Prep', 'approved'),
('A short magnet oscillating in Earth''s field $B_H$ has period $T$. When an identical magnet is placed nearby such that the net field becomes $B_H + B''$, the new period is $T/2$. The value of $B''$ is', '$3B_H$', '$B_H$', '$2B_H$', '$4B_H$', 'option1', '$T \propto 1/\sqrt{B}$. $T/(T/2) = 2 = \sqrt{(B_H + B'')/B_H}$. $4 = (B_H + B'')/B_H$. $B'' = 3B_H$.', 'p_magnetic_field_dipole', 3, 'JEE Mains Prep', 'approved'),
('The neutral points around a bar magnet placed with its north pole pointing geographic north are located on', 'A circle around the magnet', 'The axial line of the magnet', 'The equatorial line of the magnet', 'There are no neutral points', 'option3', 'When N points north, Earth''s field and the magnet''s axial field are in the same direction on the axis. On the equatorial line, the magnet''s field opposes Earth''s field, creating neutral points where they cancel.', 'p_magnetic_field_dipole', 3, 'JEE Mains Prep', 'approved'),

-- ============================================================
-- p_magnetic_materials (7 easy, 7 medium, 7 hard = 21)
-- ============================================================
('Diamagnetic materials are', 'Strongly attracted by a magnetic field', 'Weakly repelled by a magnetic field', 'Weakly attracted by a magnetic field', 'Not affected by magnetic fields', 'option2', 'Diamagnetic materials have small negative susceptibility and are weakly repelled by external fields.', 'p_magnetic_materials', 1, 'JEE Mains Prep', 'approved'),
('Paramagnetic materials are', 'Not affected', 'Strongly attracted', 'Weakly repelled', 'Weakly attracted by a magnetic field', 'option4', 'Paramagnetic materials have small positive susceptibility and are weakly attracted by external fields.', 'p_magnetic_materials', 1, 'JEE Mains Prep', 'approved'),
('Ferromagnetic materials are', 'Strongly attracted by a magnetic field and can be permanently magnetized', 'Weakly attracted', 'Weakly repelled', 'Attracted only at low temperatures', 'option1', 'Ferromagnetic materials (Fe, Co, Ni) have very large positive susceptibility and exhibit spontaneous magnetization.', 'p_magnetic_materials', 1, 'JEE Mains Prep', 'approved'),
('The magnetic susceptibility of a diamagnetic material is', 'Small and positive', 'Small and negative', 'Large and positive', 'Zero', 'option2', 'Diamagnetic: $\chi < 0$ (small magnitude, $\sim -10^{-5}$).', 'p_magnetic_materials', 1, 'JEE Mains Prep', 'approved'),
('An example of a diamagnetic material is', 'Bismuth', 'Iron', 'Aluminium', 'Nickel', 'option1', 'Bismuth, copper, gold, water are diamagnetic. Iron and nickel are ferromagnetic. Aluminium is paramagnetic.', 'p_magnetic_materials', 1, 'JEE Mains Prep', 'approved'),
('The Curie temperature is the temperature above which', 'A ferromagnetic material becomes paramagnetic', 'A paramagnetic material becomes diamagnetic', 'A diamagnetic material becomes ferromagnetic', 'All materials lose magnetism', 'option1', 'Above the Curie temperature, thermal energy disrupts domain alignment, and the material becomes paramagnetic.', 'p_magnetic_materials', 1, 'JEE Mains Prep', 'approved'),
('The relative permeability of a diamagnetic material is', 'Slightly less than 1', 'Slightly greater than 1', 'Much greater than 1', 'Exactly 1', 'option1', '$\mu_r = 1 + \chi$. For diamagnetic: $\chi < 0$ (small), so $\mu_r < 1$ (slightly).', 'p_magnetic_materials', 1, 'JEE Mains Prep', 'approved'),
('The susceptibility of a paramagnetic material varies with temperature as', '$\chi$ is independent of $T$', '$\chi \propto T$', '$\chi \propto 1/T$ (Curie law)', '$\chi \propto T^2$', 'option3', 'Curie law: $\chi = C/T$ where $C$ is the Curie constant. Higher temperature reduces alignment.', 'p_magnetic_materials', 2, 'JEE Mains Prep', 'approved'),
('The susceptibility of a diamagnetic material with temperature', 'Becomes zero above Curie temperature', 'Increases with temperature', 'Decreases with temperature', 'Is nearly independent of temperature', 'option4', 'Diamagnetic susceptibility arises from orbital motion and is essentially temperature-independent.', 'p_magnetic_materials', 2, 'JEE Mains Prep', 'approved'),
('In a ferromagnetic material, magnetic domains are', 'External magnetic field lines', 'Regions of zero magnetization', 'Individual atoms', 'Regions where atomic magnetic moments are aligned in the same direction', 'option4', 'Domains are microscopic regions ($\sim 1\;\text{mm}$) where all atomic moments are spontaneously aligned.', 'p_magnetic_materials', 2, 'JEE Mains Prep', 'approved'),
('The B-H curve (hysteresis loop) of a ferromagnetic material encloses an area that represents', 'The susceptibility', 'The magnetic moment', 'Energy dissipated per cycle per unit volume', 'The permeability', 'option3', 'The area of the hysteresis loop equals the energy lost as heat per unit volume per magnetization cycle.', 'p_magnetic_materials', 2, 'JEE Mains Prep', 'approved'),
('Retentivity of a magnetic material is', 'The maximum magnetization', 'The field needed to demagnetize it', 'The magnetization remaining after the external field is removed', 'The Curie temperature', 'option3', 'Retentivity (remanence) is the residual magnetic flux density when $H = 0$ after saturation.', 'p_magnetic_materials', 2, 'JEE Mains Prep', 'approved'),
('Coercivity of a magnetic material is', 'The maximum magnetization', 'The reverse field needed to reduce magnetization to zero', 'The retentivity', 'The susceptibility', 'option2', 'Coercivity is the magnitude of the reverse magnetic field $H$ needed to bring $B$ to zero.', 'p_magnetic_materials', 2, 'JEE Mains Prep', 'approved'),
('For making permanent magnets, the material should have', 'High retentivity and low coercivity', 'Low retentivity and low coercivity', 'High retentivity and high coercivity', 'Low retentivity and high coercivity', 'option3', 'Permanent magnets need to retain strong magnetization (high retentivity) and resist demagnetization (high coercivity). Example: Alnico, Nd-Fe-B.', 'p_magnetic_materials', 2, 'JEE Mains Prep', 'approved'),
('For making transformer cores, the material should have', 'Low coercivity and high permeability (soft ferromagnet)', 'High coercivity', 'High retentivity', 'Low permeability', 'option1', 'Transformer cores need easy magnetization/demagnetization (low hysteresis loss), so soft ferromagnets like soft iron are used.', 'p_magnetic_materials', 3, 'JEE Mains Prep', 'approved'),
('The Curie-Weiss law for a ferromagnetic material above the Curie temperature $T_C$ is', '$\chi = CT$', '$\chi = C/T$', '$\chi = C/(T - T_C)$', '$\chi = C/(T + T_C)$', 'option3', 'Above $T_C$: $\chi = C/(T - T_C)$ (Curie-Weiss law). This diverges as $T \to T_C$ from above.', 'p_magnetic_materials', 3, 'JEE Mains Prep', 'approved'),
('A paramagnetic salt has susceptibility $\chi = 3.6 \times 10^{-3}$ at $300\;\text{K}$. At $600\;\text{K}$, its susceptibility is', '$7.2 \times 10^{-3}$', '$1.8 \times 10^{-3}$', '$3.6 \times 10^{-3}$', '$0.9 \times 10^{-3}$', 'option2', 'Curie law: $\chi \propto 1/T$. $\chi_2 = \chi_1 T_1/T_2 = 3.6 \times 10^{-3} \times 300/600 = 1.8 \times 10^{-3}$.', 'p_magnetic_materials', 3, 'JEE Mains Prep', 'approved'),
('The magnetization $M$ of a paramagnetic material in a field $B$ at temperature $T$ is described by', 'A step function', 'A linear function always', 'An exponential decay', 'The Langevin function (or Brillouin function for quantum treatment)', 'option4', 'The classical Langevin function $L(x) = \coth(x) - 1/x$ where $x = mB/(k_BT)$ describes paramagnetic magnetization. For small $x$: $M \propto B/T$ (Curie law).', 'p_magnetic_materials', 3, 'JEE Mains Prep', 'approved'),
('Antiferromagnetic materials have', 'Random moment orientations', 'All moments aligned parallel', 'Adjacent atomic moments aligned antiparallel, giving zero net moment', 'Moments aligned perpendicular to each other', 'option3', 'In antiferromagnets (e.g., MnO), adjacent atomic moments are equal and antiparallel, cancelling out. They have a Néel temperature above which they become paramagnetic.', 'p_magnetic_materials', 3, 'JEE Mains Prep', 'approved'),
('A ferromagnetic material is heated above its Curie temperature and then cooled in the absence of any external field. The material will', 'Retain its original magnetization', 'Have zero net magnetization (demagnetized)', 'Become diamagnetic permanently', 'Have maximum magnetization', 'option2', 'Above $T_C$, domains randomize. Cooling without a field allows random domain formation, resulting in zero net magnetization.', 'p_magnetic_materials', 3, 'JEE Mains Prep', 'approved'),
('The relative permeability of a ferromagnetic material can be as high as', '$10^3$ to $10^5$', '$1$ to $10$', '$10^{-5}$ to $10^{-3}$', 'Exactly $1$', 'option1', 'Ferromagnetic materials have $\mu_r \sim 10^3$ to $10^5$ (e.g., soft iron $\sim 5000$, mu-metal $\sim 100000$).', 'p_magnetic_materials', 3, 'JEE Mains Prep', 'approved'),

-- ============================================================
-- p_faraday_lenz (7 easy, 7 medium, 7 hard = 21)
-- ============================================================
('Faraday''s law of electromagnetic induction states that the induced emf equals', 'The negative rate of change of magnetic flux', 'The magnetic flux itself', 'The current times resistance', 'The magnetic field strength', 'option1', '$\varepsilon = -d\Phi_B/dt$. The induced emf is proportional to the rate of change of flux.', 'p_faraday_lenz', 1, 'JEE Mains Prep', 'approved'),
('Lenz''s law states that the direction of induced current is such that it', 'Opposes the change in flux that caused it', 'Aids the change in flux', 'Is always clockwise', 'Is perpendicular to the flux', 'option1', 'Lenz''s law is a consequence of energy conservation: the induced current opposes the cause.', 'p_faraday_lenz', 1, 'JEE Mains Prep', 'approved'),
('The SI unit of magnetic flux is', 'Weber (Wb)', 'Tesla (T)', 'Henry (H)', 'Volt (V)', 'option1', '$1\;\text{Wb} = 1\;\text{T}\cdot\text{m}^2 = 1\;\text{V}\cdot\text{s}$.', 'p_faraday_lenz', 1, 'JEE Mains Prep', 'approved'),
('Self-inductance of a coil is defined as', 'Current per unit flux', 'Flux linkage per unit current ($L = N\Phi/I$)', 'Resistance per unit length', 'Capacitance per unit area', 'option2', '$L = N\Phi/I$. Self-induced emf: $\varepsilon = -L\,dI/dt$.', 'p_faraday_lenz', 1, 'JEE Mains Prep', 'approved'),
('The SI unit of inductance is', 'Weber (Wb)', 'Henry (H)', 'Farad (F)', 'Ohm ($\Omega$)', 'option2', '$1\;\text{H} = 1\;\text{Wb/A} = 1\;\text{V}\cdot\text{s/A}$.', 'p_faraday_lenz', 1, 'JEE Mains Prep', 'approved'),
('Eddy currents are', 'Currents in a capacitor', 'Currents in a solenoid', 'Currents due to static charges', 'Induced currents in bulk conductors due to changing magnetic flux', 'option4', 'Eddy currents are loops of current induced in conductors by changing magnetic fields, causing heating.', 'p_faraday_lenz', 1, 'JEE Mains Prep', 'approved'),
('Mutual inductance between two coils depends on', 'Only the current in the coils', 'Their geometry, number of turns, and the medium between them', 'Only the resistance of the coils', 'The voltage applied', 'option2', '$M$ depends on $N_1$, $N_2$, geometry, separation, and permeability of the medium.', 'p_faraday_lenz', 1, 'JEE Mains Prep', 'approved'),
('A coil of $100$ turns and area $0.01\;\text{m}^2$ is in a field that changes from $0.1\;\text{T}$ to $0.5\;\text{T}$ in $0.1\;\text{s}$. The induced emf is', '$40\;\text{V}$', '$0.4\;\text{V}$', '$4\;\text{V}$', '$0.04\;\text{V}$', 'option3', '$\varepsilon = N\Delta\Phi/\Delta t = 100 \times 0.01 \times (0.5 - 0.1)/0.1 = 100 \times 0.01 \times 4 = 4\;\text{V}$.', 'p_faraday_lenz', 2, 'JEE Mains Prep', 'approved'),
('The self-inductance of a solenoid of $N$ turns, length $l$, and cross-sectional area $A$ is', '$\mu_0 N^2 A/l$', '$\mu_0 NA/l$', '$\mu_0 N^2 l/A$', '$\mu_0 NA$', 'option1', '$L = \mu_0 n^2 Al = \mu_0 (N/l)^2 Al = \mu_0 N^2 A/l$.', 'p_faraday_lenz', 2, 'JEE Mains Prep', 'approved'),
('The energy stored in an inductor of inductance $L$ carrying current $I$ is', '$\frac{1}{2}L^2I$', '$LI^2$', '$LI$', '$\frac{1}{2}LI^2$', 'option4', '$U = \frac{1}{2}LI^2$, analogous to $\frac{1}{2}CV^2$ for a capacitor.', 'p_faraday_lenz', 2, 'JEE Mains Prep', 'approved'),
('A conducting rod of length $l$ moves with velocity $v$ perpendicular to a uniform field $B$. The emf induced across the rod is', '$Bvl$', '$Bv/l$', '$Bl/v$', '$B^2vl$', 'option1', '$\varepsilon = Bvl$ (motional emf). The force on charges in the rod creates a potential difference.', 'p_faraday_lenz', 2, 'JEE Mains Prep', 'approved'),
('Two coils have mutual inductance $M = 0.5\;\text{H}$. If the current in one coil changes at $10\;\text{A/s}$, the emf induced in the other is', '$5\;\text{V}$', '$0.5\;\text{V}$', '$50\;\text{V}$', '$0.05\;\text{V}$', 'option1', '$\varepsilon = M\,dI/dt = 0.5 \times 10 = 5\;\text{V}$.', 'p_faraday_lenz', 2, 'JEE Mains Prep', 'approved'),
('The coefficient of coupling $k$ between two coils of self-inductances $L_1$ and $L_2$ with mutual inductance $M$ is', '$M/\sqrt{L_1 L_2}$', '$M/(L_1 + L_2)$', '$\sqrt{L_1 L_2}/M$', '$M^2/(L_1 L_2)$', 'option1', '$k = M/\sqrt{L_1 L_2}$, where $0 \leq k \leq 1$. $k = 1$ for perfect coupling.', 'p_faraday_lenz', 2, 'JEE Mains Prep', 'approved'),
('An inductor of $2\;\text{H}$ carries $5\;\text{A}$. The energy stored is', '$5\;\text{J}$', '$10\;\text{J}$', '$25\;\text{J}$', '$50\;\text{J}$', 'option3', '$U = \frac{1}{2}LI^2 = \frac{1}{2} \times 2 \times 25 = 25\;\text{J}$.', 'p_faraday_lenz', 2, 'JEE Mains Prep', 'approved'),
('A circular coil of $N$ turns and radius $R$ rotates at angular velocity $\omega$ in a uniform field $B$. The maximum emf induced is', '$NBA$', '$NBA\omega = NB\pi R^2\omega$', '$NB\omega/R$', '$NB\pi R\omega$', 'option2', '$\Phi = NBA\cos(\omega t)$. $\varepsilon = NBA\omega\sin(\omega t)$. Maximum $= NBA\omega = NB\pi R^2\omega$.', 'p_faraday_lenz', 3, 'JEE Mains Prep', 'approved'),
('A conducting rod of length $l$ rotates about one end with angular velocity $\omega$ in a uniform field $B$ perpendicular to the plane of rotation. The emf induced is', '$\frac{1}{2}B\omega l^2$', '$B\omega l^2$', '$B\omega l$', '$\frac{1}{4}B\omega l^2$', 'option1', 'Consider element $dr$ at distance $r$: $d\varepsilon = Bvdr = B\omega r\,dr$. $\varepsilon = \int_0^l B\omega r\,dr = B\omega l^2/2$.', 'p_faraday_lenz', 3, 'JEE Mains Prep', 'approved'),
('In an LR circuit with emf $\varepsilon$, the current grows as $I = (\varepsilon/R)(1 - e^{-t/\tau})$ where the time constant $\tau$ is', '$LR$', '$R/L$', '$L/R$', '$\sqrt{L/R}$', 'option3', 'The LR time constant $\tau = L/R$. At $t = \tau$, current reaches $\approx 63\%$ of its final value.', 'p_faraday_lenz', 3, 'JEE Mains Prep', 'approved'),
('A square loop of side $a$ moves with velocity $v$ into a region of uniform field $B$ (perpendicular to the loop). The induced emf while entering is', 'Zero', '$Bva^2$', '$Bv/a$', '$Bva$', 'option4', 'Only the leading edge cuts flux. $\varepsilon = Bva$. Once fully inside, $\varepsilon = 0$ (flux is constant).', 'p_faraday_lenz', 3, 'JEE Mains Prep', 'approved'),
('Two coils of self-inductances $L_1$ and $L_2$ are connected in series with mutual inductance $M$ (fields aiding). The total inductance is', '$L_1 L_2/(L_1 + L_2)$', '$L_1 + L_2 - 2M$', '$L_1 + L_2$', '$L_1 + L_2 + 2M$', 'option4', 'Series aiding: $L = L_1 + L_2 + 2M$. Series opposing: $L = L_1 + L_2 - 2M$.', 'p_faraday_lenz', 3, 'JEE Mains Prep', 'approved'),
('A metal disc of radius $R$ rotates at $\omega$ rad/s in a field $B$ perpendicular to it. The emf between the centre and the rim is', '$B\omega R^2/2$', '$B\omega R^2$', '$B\omega R$', '$B\omega R^2/4$', 'option1', 'Same as a rotating rod: $\varepsilon = \int_0^R B\omega r\,dr = B\omega R^2/2$ (Faraday disc).', 'p_faraday_lenz', 3, 'JEE Mains Prep', 'approved'),
('The mutual inductance between a long solenoid ($n$ turns/m, area $A$) and a coil of $N$ turns wound around it is', '$\mu_0 n^2 NA$', '$\mu_0 nNA$', '$\mu_0 NA/n$', '$\mu_0 nN/A$', 'option2', 'Flux through the coil due to solenoid: $\Phi = \mu_0 nIA$. $M = N\Phi/I = \mu_0 nNA$.', 'p_faraday_lenz', 3, 'JEE Mains Prep', 'approved'),

-- ============================================================
-- p_ac_values_impedance (7 easy, 7 medium, 7 hard = 21)
-- ============================================================
('The RMS value of an AC voltage $V = V_0\sin\omega t$ is', '$V_0/\sqrt{2}$', '$V_0$', '$V_0/2$', '$\sqrt{2}V_0$', 'option1', '$V_{rms} = V_0/\sqrt{2} \approx 0.707 V_0$.', 'p_ac_values_impedance', 1, 'JEE Mains Prep', 'approved'),
('The frequency of AC mains in India is', '$25\;\text{Hz}$', '$60\;\text{Hz}$', '$100\;\text{Hz}$', '$50\;\text{Hz}$', 'option4', 'India uses $50\;\text{Hz}$ AC supply (angular frequency $\omega = 100\pi\;\text{rad/s}$).', 'p_ac_values_impedance', 1, 'JEE Mains Prep', 'approved'),
('The reactance of a pure inductor of inductance $L$ at angular frequency $\omega$ is', '$1/(\omega L)$', '$\omega L$', '$\omega/L$', '$L/\omega$', 'option2', 'Inductive reactance $X_L = \omega L$. It increases with frequency.', 'p_ac_values_impedance', 1, 'JEE Mains Prep', 'approved'),
('The reactance of a pure capacitor of capacitance $C$ at angular frequency $\omega$ is', '$1/(\omega C)$', '$\omega C$', '$\omega/C$', '$C/\omega$', 'option1', 'Capacitive reactance $X_C = 1/(\omega C)$. It decreases with frequency.', 'p_ac_values_impedance', 1, 'JEE Mains Prep', 'approved'),
('In a pure resistive AC circuit, the voltage and current are', '$90°$ out of phase', 'In phase', '$180°$ out of phase', '$45°$ out of phase', 'option2', 'In a pure resistor, $V$ and $I$ are in phase ($\phi = 0$).', 'p_ac_values_impedance', 1, 'JEE Mains Prep', 'approved'),
('In a pure inductive AC circuit, the current', 'Is in phase with voltage', 'Leads the voltage by $90°$', 'Lags the voltage by $90°$', 'Lags by $45°$', 'option3', 'In a pure inductor, current lags voltage by $\pi/2$ (ELI the ICE man).', 'p_ac_values_impedance', 1, 'JEE Mains Prep', 'approved'),
('In a pure capacitive AC circuit, the current', 'Leads the voltage by $90°$', 'Lags the voltage by $90°$', 'Is in phase with voltage', 'Leads by $45°$', 'option1', 'In a pure capacitor, current leads voltage by $\pi/2$.', 'p_ac_values_impedance', 1, 'JEE Mains Prep', 'approved'),
('The impedance of a series RL circuit with resistance $R$ and inductive reactance $X_L$ is', '$RX_L/(R + X_L)$', '$R + X_L$', '$R - X_L$', '$\sqrt{R^2 + X_L^2}$', 'option4', '$Z = \sqrt{R^2 + X_L^2}$. The phase angle $\phi = \arctan(X_L/R)$.', 'p_ac_values_impedance', 2, 'JEE Mains Prep', 'approved'),
('An AC source of $220\;\text{V}$ (RMS) has peak voltage', '$155\;\text{V}$', '$220\;\text{V}$', '$311\;\text{V}$', '$440\;\text{V}$', 'option3', '$V_0 = V_{rms}\sqrt{2} = 220\sqrt{2} \approx 311\;\text{V}$.', 'p_ac_values_impedance', 2, 'JEE Mains Prep', 'approved'),
('A $0.1\;\text{H}$ inductor is connected to a $50\;\text{Hz}$ AC source. Its reactance is', '$31.4\;\Omega$', '$5\;\Omega$', '$314\;\Omega$', '$0.314\;\Omega$', 'option1', '$X_L = \omega L = 2\pi \times 50 \times 0.1 = 10\pi \approx 31.4\;\Omega$.', 'p_ac_values_impedance', 2, 'JEE Mains Prep', 'approved'),
('A $10\;\mu\text{F}$ capacitor is connected to a $50\;\text{Hz}$ source. Its reactance is approximately', '$3180\;\Omega$', '$31.8\;\Omega$', '$318\;\Omega$', '$3.18\;\Omega$', 'option3', '$X_C = 1/(\omega C) = 1/(2\pi \times 50 \times 10^{-5}) = 1/(3.14 \times 10^{-3}) \approx 318\;\Omega$.', 'p_ac_values_impedance', 2, 'JEE Mains Prep', 'approved'),
('The impedance of a series RC circuit with $R = 30\;\Omega$ and $X_C = 40\;\Omega$ is', '$10\;\Omega$', '$70\;\Omega$', '$50\;\Omega$', '$35\;\Omega$', 'option3', '$Z = \sqrt{R^2 + X_C^2} = \sqrt{900 + 1600} = \sqrt{2500} = 50\;\Omega$.', 'p_ac_values_impedance', 2, 'JEE Mains Prep', 'approved'),
('The phase angle in a series RL circuit with $R = 100\;\Omega$ and $X_L = 100\;\Omega$ is', '$45°$', '$90°$', '$0°$', '$60°$', 'option1', '$\tan\phi = X_L/R = 100/100 = 1$. $\phi = 45°$ (current lags voltage).', 'p_ac_values_impedance', 2, 'JEE Mains Prep', 'approved'),
('The average value of $V = V_0\sin\omega t$ over a full cycle is', '$V_0/2$', '$V_0/\sqrt{2}$', '$2V_0/\pi$', 'Zero', 'option4', 'The average of a sinusoidal function over a complete cycle is zero.', 'p_ac_values_impedance', 2, 'JEE Mains Prep', 'approved'),
('The impedance of a series RLC circuit is', '$R + |X_L - X_C|$', '$R + X_L + X_C$', '$\sqrt{R^2 + X_L^2 + X_C^2}$', '$\sqrt{R^2 + (X_L - X_C)^2}$', 'option4', '$Z = \sqrt{R^2 + (X_L - X_C)^2}$. At resonance ($X_L = X_C$): $Z = R$.', 'p_ac_values_impedance', 3, 'JEE Mains Prep', 'approved'),
('In a series RLC circuit, $R = 100\;\Omega$, $L = 1\;\text{H}$, $C = 10\;\mu\text{F}$, $\omega = 100\;\text{rad/s}$. The impedance is', '$500\;\Omega$', '$100\;\Omega$', '$1000\;\Omega$', '$\approx 906\;\Omega$', 'option4', '$X_L = 100$, $X_C = 1/(100 \times 10^{-5}) = 1000\;\Omega$. $Z = \sqrt{100^2 + (100-1000)^2} = \sqrt{10000 + 810000} = \sqrt{820000} \approx 906\;\Omega$.', 'p_ac_values_impedance', 3, 'JEE Mains Prep', 'approved'),
('The RMS value of a current $I = 5\sin(100\pi t) + 5\cos(100\pi t)\;\text{A}$ is', '$5\;\text{A}$', '$5\sqrt{2}\;\text{A}$', '$10\;\text{A}$', '$5/\sqrt{2}\;\text{A}$', 'option1', '$I = 5\sin(100\pi t) + 5\cos(100\pi t) = 5\sqrt{2}\sin(100\pi t + \pi/4)$. Peak $= 5\sqrt{2}$. $I_{rms} = 5\sqrt{2}/\sqrt{2} = 5\;\text{A}$.', 'p_ac_values_impedance', 3, 'JEE Mains Prep', 'approved'),
('A choke coil (inductor with some resistance) is preferred over a resistor for reducing AC current because', 'It increases frequency', 'It is cheaper', 'It reduces voltage', 'It consumes less power (ideally zero for pure inductor)', 'option4', 'A pure inductor has zero average power consumption ($P = VI\cos 90° = 0$), unlike a resistor which dissipates $I^2R$ as heat.', 'p_ac_values_impedance', 3, 'JEE Mains Prep', 'approved'),
('The form factor of a sinusoidal AC wave is', '$1$', '$\sqrt{2} \approx 1.414$', '$\pi/(2\sqrt{2}) \approx 1.11$', '$2/\pi \approx 0.637$', 'option3', 'Form factor $= V_{rms}/V_{avg(half)} = (V_0/\sqrt{2})/(2V_0/\pi) = \pi/(2\sqrt{2}) \approx 1.11$.', 'p_ac_values_impedance', 3, 'JEE Mains Prep', 'approved'),
('An AC voltage $V = 100\sin(1000t)$ is applied across a $50\;\mu\text{F}$ capacitor. The peak current is', '$5\;\text{A}$', '$2\;\text{A}$', '$0.5\;\text{A}$', '$50\;\text{A}$', 'option1', '$X_C = 1/(\omega C) = 1/(1000 \times 50 \times 10^{-6}) = 1/0.05 = 20\;\Omega$. $I_0 = V_0/X_C = 100/20 = 5\;\text{A}$.', 'p_ac_values_impedance', 3, 'JEE Mains Prep', 'approved'),
('The quality factor of a series RLC circuit at resonance is', '$\omega_0 L/R = 1/(\omega_0 CR)$', '$R/(\omega_0 L)$', '$\omega_0 R/L$', '$R\omega_0 C$', 'option1', '$Q = \omega_0 L/R = 1/(R\omega_0 C) = (1/R)\sqrt{L/C}$. Higher $Q$ means sharper resonance.', 'p_ac_values_impedance', 3, 'JEE Mains Prep', 'approved'),

-- ============================================================
-- p_lcr_resonance_power (7 easy, 7 medium, 7 hard = 21)
-- ============================================================
('Resonance in a series LCR circuit occurs when', '$X_L = R$', '$R = 0$', '$X_L = X_C$ (i.e., $\omega = 1/\sqrt{LC}$)', '$X_C = R$', 'option3', 'At resonance: $\omega L = 1/(\omega C)$, giving $\omega_0 = 1/\sqrt{LC}$. Impedance is minimum ($Z = R$).', 'p_lcr_resonance_power', 1, 'JEE Mains Prep', 'approved'),
('At resonance in a series LCR circuit, the impedance equals', 'Zero', '$\sqrt{R^2 + X_L^2}$', '$R$ (the resistance only)', '$X_L + X_C$', 'option3', 'At resonance, $X_L = X_C$, so $Z = \sqrt{R^2 + 0} = R$.', 'p_lcr_resonance_power', 1, 'JEE Mains Prep', 'approved'),
('The power factor of an AC circuit is', '$V/I$', '$\sin\phi$', '$\tan\phi$', '$\cos\phi$ where $\phi$ is the phase angle between $V$ and $I$', 'option4', 'Power factor $= \cos\phi = R/Z$. It determines the fraction of apparent power that is real power.', 'p_lcr_resonance_power', 1, 'JEE Mains Prep', 'approved'),
('The average power in an AC circuit is', '$V_{rms}I_{rms}$', '$V_{rms}I_{rms}\cos\phi$', '$V_0 I_0$', '$V_{rms}I_{rms}\sin\phi$', 'option2', '$P_{avg} = V_{rms}I_{rms}\cos\phi$. Only the component of current in phase with voltage contributes to power.', 'p_lcr_resonance_power', 1, 'JEE Mains Prep', 'approved'),
('Wattless current is the component of current that', 'Produces maximum heating', 'Is in phase with voltage', 'Is $90°$ out of phase with voltage and dissipates no power', 'Flows only in resistors', 'option3', 'Wattless (reactive) current $= I\sin\phi$. It oscillates energy between source and reactive elements without net dissipation.', 'p_lcr_resonance_power', 1, 'JEE Mains Prep', 'approved'),
('A transformer works on the principle of', 'Self-induction', 'Mutual induction', 'Electrostatic induction', 'Eddy currents', 'option2', 'A transformer uses mutual induction between primary and secondary coils to step up or step down AC voltage.', 'p_lcr_resonance_power', 1, 'JEE Mains Prep', 'approved'),
('In an ideal transformer, $V_s/V_p$ equals', '$I_s/I_p$', '$N_p/N_s$', '$N_s/N_p$ (turns ratio)', '$R_s/R_p$', 'option3', '$V_s/V_p = N_s/N_p$. For an ideal transformer: $V_p I_p = V_s I_s$ (power conserved).', 'p_lcr_resonance_power', 1, 'JEE Mains Prep', 'approved'),
('The resonant frequency of a series LCR circuit with $L = 1\;\text{mH}$ and $C = 1\;\mu\text{F}$ is', '$\approx 159\;\text{Hz}$', '$\approx 503\;\text{Hz}$', '$\approx 50330\;\text{Hz}$', '$\approx 5033\;\text{Hz}$', 'option4', '$f_0 = 1/(2\pi\sqrt{LC}) = 1/(2\pi\sqrt{10^{-3} \times 10^{-6}}) = 1/(2\pi \times 10^{-4.5}) = 10^{4.5}/(2\pi) \approx 31623/6.283 \approx 5033\;\text{Hz}$.', 'p_lcr_resonance_power', 2, 'JEE Mains Prep', 'approved'),
('At resonance in a series LCR circuit, the current is', 'Maximum', 'Minimum', 'Zero', 'Depends on $L$ and $C$', 'option1', 'At resonance, $Z = R$ (minimum), so $I = V/R$ (maximum).', 'p_lcr_resonance_power', 2, 'JEE Mains Prep', 'approved'),
('The power factor of a series LCR circuit at resonance is', '$0$', '$1$', '$0.5$', '$1/\sqrt{2}$', 'option2', 'At resonance, $\phi = 0$ (voltage and current in phase). $\cos\phi = 1$.', 'p_lcr_resonance_power', 2, 'JEE Mains Prep', 'approved'),
('A step-up transformer has $100$ turns in the primary and $500$ in the secondary. If the primary voltage is $220\;\text{V}$, the secondary voltage is', '$44\;\text{V}$', '$1100\;\text{V}$', '$550\;\text{V}$', '$2200\;\text{V}$', 'option2', '$V_s = V_p \times N_s/N_p = 220 \times 500/100 = 1100\;\text{V}$.', 'p_lcr_resonance_power', 2, 'JEE Mains Prep', 'approved'),
('The power dissipated in a pure inductor or pure capacitor in an AC circuit is', '$V^2/X_C$', '$V_{rms}I_{rms}$', '$I^2 X_L$', 'Zero', 'option4', 'For pure $L$ or $C$: $\phi = 90°$, so $P = VI\cos 90° = 0$. Energy oscillates but is not dissipated.', 'p_lcr_resonance_power', 2, 'JEE Mains Prep', 'approved'),
('In an AC generator, the emf produced is', '$\varepsilon = BA/\omega$', '$\varepsilon = NBA$', '$\varepsilon = NBI\omega$', '$\varepsilon = NBA\omega\sin(\omega t)$', 'option4', 'A coil of $N$ turns, area $A$, rotating at $\omega$ in field $B$: $\varepsilon = NBA\omega\sin(\omega t)$.', 'p_lcr_resonance_power', 2, 'JEE Mains Prep', 'approved'),
('An ideal transformer with turns ratio $10:1$ (step-down) has primary current $0.5\;\text{A}$. The secondary current is', '$5\;\text{A}$', '$0.05\;\text{A}$', '$50\;\text{A}$', '$0.5\;\text{A}$', 'option1', '$I_s/I_p = N_p/N_s = 10/1$. $I_s = 0.5 \times 10 = 5\;\text{A}$.', 'p_lcr_resonance_power', 2, 'JEE Mains Prep', 'approved'),
('In a series LCR circuit driven at frequency below resonance, the circuit is', 'Capacitive (current leads voltage)', 'Inductive (current lags voltage)', 'Resistive', 'At resonance', 'option1', 'Below resonance: $X_C > X_L$, so the net reactance is capacitive and current leads voltage.', 'p_lcr_resonance_power', 3, 'JEE Mains Prep', 'approved'),
('The bandwidth of a series RLC resonant circuit is', '$1/\sqrt{LC}$', '$L/R$', '$R/L$ (in rad/s)', '$R/(2L)$', 'option3', 'Bandwidth $\Delta\omega = R/L$. The half-power frequencies are $\omega_0 \pm R/(2L)$.', 'p_lcr_resonance_power', 3, 'JEE Mains Prep', 'approved'),
('A series LCR circuit has $R = 10\;\Omega$, $L = 0.1\;\text{H}$, $C = 100\;\mu\text{F}$. The quality factor is', '$\approx 10$', '$\approx 3.16$', '$\approx 31.6$', '$\approx 1$', 'option2', '$Q = (1/R)\sqrt{L/C} = (1/10)\sqrt{0.1/(10^{-4})} = 0.1\sqrt{1000} = 0.1 \times 31.6 = 3.16$.', 'p_lcr_resonance_power', 3, 'JEE Mains Prep', 'approved'),
('At resonance in a series LCR circuit, the voltage across the inductor is', '$V$', '$QV$ where $Q$ is the quality factor and $V$ is the source voltage', '$V/Q$', 'Zero', 'option2', '$V_L = IX_L = (V/R)(\omega_0 L) = V \times \omega_0 L/R = QV$. This can exceed the source voltage.', 'p_lcr_resonance_power', 3, 'JEE Mains Prep', 'approved'),
('A transformer has efficiency $90\%$. If the primary draws $2\;\text{kW}$, the power delivered to the secondary is', '$2\;\text{kW}$', '$1.8\;\text{kW}$', '$2.22\;\text{kW}$', '$1\;\text{kW}$', 'option2', '$P_s = \eta \times P_p = 0.9 \times 2 = 1.8\;\text{kW}$.', 'p_lcr_resonance_power', 3, 'JEE Mains Prep', 'approved'),
('In a series LCR circuit at resonance, the voltages across $L$ and $C$ are', 'Unequal', 'Equal and in phase', 'Zero', 'Equal in magnitude but opposite in phase (they cancel)', 'option4', 'At resonance: $V_L = IX_L$ and $V_C = IX_C$. Since $X_L = X_C$, $|V_L| = |V_C|$. They are $180°$ out of phase and cancel.', 'p_lcr_resonance_power', 3, 'JEE Mains Prep', 'approved'),
('Long-distance power transmission uses high voltage because', 'Transformers only work at high voltage', 'High voltage is safer', 'It increases the power generated', 'It reduces current and hence $I^2R$ losses in transmission lines', 'option4', 'For fixed power $P = VI$, higher $V$ means lower $I$, reducing transmission losses $P_{loss} = I^2R$.', 'p_lcr_resonance_power', 3, 'JEE Mains Prep', 'approved'),

